import React, { useEffect, Suspense, lazy } from 'react';
import { HashRouter, Switch, Route, Redirect } from 'react-router-dom';
import bridge from '@vkontakte/vk-bridge';
import { AuthProvider, useAuth } from './context/AuthContext';
import { Layout } from './components/layout/Layout';
import { Dashboard } from './pages/Dashboard';
import { AuthPage } from './pages/AuthPage';
import { Loader2 } from 'lucide-react';

// Lazy Load Modules to reduce bundle size and speed up initial load
const RosterModule = lazy(() => import('./modules/roster/App'));
const BattleModule = lazy(() => import('./modules/battle/App'));
const LoreModule = lazy(() => import('./modules/lore/App'));

const LoadingScreen = () => (
  <div className="min-h-screen flex items-center justify-center bg-[#050b14] text-violet-500">
    <div className="flex flex-col items-center gap-4">
      <Loader2 className="animate-spin w-10 h-10" />
      <span className="font-fantasy text-sm tracking-widest opacity-70">ЗАГРУЗКА МОДУЛЯ...</span>
    </div>
  </div>
);

// Protected Route Component for v5
const ProtectedRoute = ({ component: Component, isAdmin, ...rest }: any) => {
  const { isAuthenticated } = useAuth();

  return (
    <Route
      {...rest}
      render={(props) =>
        isAuthenticated ? (
          <Layout>
            <Component {...props} isAdmin={isAdmin} />
          </Layout>
        ) : (
          <Redirect to="/auth" />
        )
      }
    />
  );
};

const AppContent = () => {
  const { isAdmin, isLoading } = useAuth();

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#050b14] text-violet-500">
        <Loader2 className="animate-spin w-10 h-10" />
      </div>
    );
  }

  return (
    <HashRouter>
      <Suspense fallback={<LoadingScreen />}>
        <Switch>
          <Route path="/auth" component={AuthPage} />

          <ProtectedRoute exact path="/" component={Dashboard} />
          <ProtectedRoute path="/roster" component={RosterModule} isAdmin={isAdmin} />
          <ProtectedRoute path="/battle" component={BattleModule} isAdmin={isAdmin} />
          <ProtectedRoute path="/lore" component={LoreModule} isAdmin={isAdmin} />

          <Redirect to="/" />
        </Switch>
      </Suspense>
    </HashRouter>
  );
};

function App() {
  useEffect(() => {
    bridge.send("VKWebAppInit");
  }, []);

  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

export default App;

