          };
      }
      if (user?.role === 'user') {
          return {
              style: 'bg-blue-900/20 border-blue-500/50 text-blue-300',
              label: 'Путник',
              icon: UserIcon
          };
      }
      return {
          style: 'bg-slate-900/20 border-slate-500/50 text-slate-300',
          label: 'Гостевой Доступ',
          icon: Users
      };
  };

  const badge = getBadgeConfig();
