<change>
    <file>src/App.tsx</file>
    <description>Make children prop optional in ProtectedRouteProps to resolve TypeScript errors about missing children property in JSX.</description>
    <content><![CDATA[import React, { useEffect, Suspense, lazy } from 'react';
// @ts-ignore
import { HashRouter,
  Routes,
  Route,
  Navigate
} from 'react-router-dom';
import Header from './components/Header';
import Footer from './components/Footer';
import About from './pages/About';
import FAQ from './pages/FAQ';
import Contact from './pages/Contact';
import Terms from './pages/Terms';
import Privacy from './pages/Privacy';
import Login from './pages/Login';
import Register from './pages/Register';
import ForgotPassword from './pages/ForgotPassword';
import ResetPassword from './pages/ResetPassword';
import NotFound from './pages/NotFound';
import { useAuth } from './context/AuthContext';
import Loading from './components/Loading';
import './App.css';

const Home = lazy(() => import('./pages/Home'));
const Roster = lazy(() => import('./pages/Roster'));
const Battle = lazy(() => import('./pages/Battle'));
const Lore = lazy(() => import('./pages/Lore'));
const Admin = lazy(() => import('./pages/Admin'));

interface ProtectedRouteProps {
  children?: React.ReactNode; // Make children optional
  isAdmin?: boolean;
}

const ProtectedRoute = ({ children, isAdmin }: ProtectedRouteProps) => {
  const { currentUser, loading } = useAuth();
  if (loading) {
    return <Loading />;
  }

  if (!currentUser) {
    return <Navigate to="/login" />;
  }

  if (isAdmin && !currentUser.isAdmin) {
    return <Navigate to="/" />;
  }

  return <>{children}</>;
};

function App() {
  return (
    <HashRouter>
      <Header />
      <Suspense fallback={<Loading />}>
        <Routes>
