import React, { useState, useEffect, useRef } from 'react';
import { CharacterData, Faction } from '../types';
import { NPC_VOLUMES } from '../constants';
import { Button } from './Shared';
import { User as UserIcon, Skull, Sun, Moon, Ghost, Plus, ShieldCheck, Sword, Wand2, Crown, Link as LinkIcon, Terminal, Settings, ChevronLeft, ChevronRight, Activity, ChevronDown, Calendar, Upload } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';
import { useUI } from '../context/UIContext';

interface Props {
  characters: CharacterData[];
  onSelect: (id: string) => void;
  onCreate: () => void;
  onImport: (data: CharacterData) => Promise<void>;
  onOpenSettings?: () => void;
  onOpenTraining?: () => void;
}

const Roster: React.FC<Props> = ({ characters, onSelect, onCreate, onImport, onOpenSettings, onOpenTraining }) => {
  const { isAdmin } = useAuth();
  /* [DIALECT] */ const { t, handleLetterClick, handleSlashClick, isInputMode, inputBuffer, isDialectUnlocked, isBloodMode, trackTabChange } = useDialect();
  const { showAlert } = useUI();

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isImporting, setIsImporting] = useState(false);

  // Lazy initialize state from LocalStorage
  const [activeTab, setActiveTab] = useState<Faction>(() => {
      return (localStorage.getItem('roster_active_tab') as Faction) || Faction.LIGHT;
  });

  const [npcVolume, setNpcVolume] = useState<string>(() => {
      return localStorage.getItem('roster_npc_volume') || NPC_VOLUMES[0];
  });

  // Track tabs for secrets & persistence
  const handleTabChange = (faction: Faction) => {
      setActiveTab(faction);
      trackTabChange(faction);
      localStorage.setItem('roster_active_tab', faction);
  };

  const handleNpcVolumeChange = (vol: string) => {
      setNpcVolume(vol);
      localStorage.setItem('roster_npc_volume', vol);
  };

  // Tab ordering for navigation
  const tabs = [Faction.LIGHT, Faction.DARK, Faction.GRAVEYARD, Faction.NPC];

  const handleNextTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx + 1) % tabs.length]);
  };

  const handlePrevTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx - 1 + tabs.length) % tabs.length]);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setIsImporting(true);
      const reader = new FileReader();

      reader.onload = async (ev) => {
          try {
              const json = JSON.parse(ev.target?.result as string);

              // Basic validation
              if (!json.profile || !json.stats) {
                  throw new Error("Неверный формат файла персонажа.");
              }

              // Regenerate ID to treat as a new copy/import
              const importedChar: CharacterData = {
                  ...json,
                  id: `imported_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`
              };

              await onImport(importedChar);
              showAlert(`Персонаж "${importedChar.profile.name}" успешно импортирован.`, "Импорт");
          } catch (err: any) {
              console.error(err);
              showAlert("Ошибка импорта: " + err.message, "Ошибка");
          } finally {
              setIsImporting(false);
              if (fileInputRef.current) fileInputRef.current.value = "";
          }
      };

      reader.onerror = () => {
          showAlert("Ошибка чтения файла", "Ошибка");
          setIsImporting(false);
      };

      reader.readAsText(file);
  };

  const filtered = characters.filter(c => {
    if (!c.profile) return false;

    const isCompanion = c.profile.faction === Faction.NPC && c.profile.npc_volume === "Спутники и Рабы";
    if (c.meta.master_id && !isCompanion) return false;

    if (c.profile.faction !== activeTab) return false;
    if (activeTab === Faction.NPC && c.profile.npc_volume !== npcVolume) return false;
    return true;
  });

  // --- Theme Logic ---
  const getTheme = (f: Faction) => {
    // Blood Mode Override
    if (isBloodMode) {
        return {
            tab: "text-red-600 drop-shadow-[0_0_8px_rgba(220,38,38,0.8)] animate-pulse",
            border: "border-red-600/60",
            glow: "shadow-[0_0_30px_rgba(220,38,38,0.3)]",
            bg: "bg-red-950/40",
            text: "text-red-200",
            glowColor: "from-red-900/30"
        };
    }

    switch (f) {
      case Faction.LIGHT: 
        return {
          tab: "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]",
          border: "border-amber-500/30",
          glow: "shadow-[0_0_20px_rgba(251,191,36,0.1)]",
          bg: "bg-amber-950/20",
          text: "text-amber-100",
          // BRIGHTER LIGHT AMBIENCE
          glowColor: "from-amber-200/15" 
        };
      case Faction.DARK: 
        return {
          tab: "text-violet-400 drop-shadow-[0_0_8px_rgba(139,92,246,0.5)]",
          border: "border-violet-500/40",
          glow: "shadow-[0_0_20px_rgba(139,92,246,0.2)]",
          bg: "bg-violet-950/30",
          text: "text-violet-100",
          glowColor: "from-violet-900/20"
        };
      case Faction.NPC: 
        return {
          tab: "text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]",
          border: "border-red-500/30",
          glow: "shadow-[0_0_20px_rgba(239,68,68,0.1)]",
          bg: "bg-red-950/20",
          text: "text-red-100",
          glowColor: "from-red-900/20"
        };
      case Faction.GRAVEYARD: 
        return {
          tab: "text-slate-400 drop-shadow-[0_0_8px_rgba(148,163,184,0.5)]",
          border: "border-slate-500/30",
          glow: "shadow-[0_0_10px_rgba(148,163,184,0.1)]",
          bg: "bg-slate-900/20",
          text: "text-slate-300",
          glowColor: "from-slate-800/30"
        };
      default: 
        return { tab: "", border: "border-slate-700", glow: "", bg: "", text: "", glowColor: "from-slate-900/10" };
    }
  };

  const theme = getTheme(activeTab);

  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getLabelKey = (faction: Faction) => 
      faction === Faction.LIGHT ? 'fac_light' : 
      faction === Faction.DARK ? 'fac_dark' :
      faction === Faction.NPC ? 'fac_npc' : 'fac_graveyard';

  const TabButton = ({ faction, icon: Icon }: { faction: Faction, icon: any }) => {
    const isActive = activeTab === faction;
    const labelKey = getLabelKey(faction);
    const localTheme = getTheme(faction);

    return (
      <button
        onClick={() => handleTabChange(faction)}
        className={`relative flex items-center gap-2 px-6 py-3 font-serif font-bold uppercase tracking-widest text-[10px] md:text-xs transition-all whitespace-nowrap flex-shrink-0 ${
          isActive ? `${localTheme.tab} bg-white/5` : "text-slate-600 hover:text-slate-400 hover:bg-white/5"
        }`}
      >
        <Icon size={16} className={isBloodMode ? "text-red-500" : ""} />
        {t(labelKey, faction)}
        {isActive && (
           <div className={`absolute bottom-0 left-0 w-full h-0.5 bg-current shadow-[0_0_10px_currentColor]`}></div>
        )}
      </button>
    );
  };

  const renderInteractiveTitle = (text: string) => {
    return text.split('').map((char, i) => (
      <span 
        key={i} 
        onClick={(e) => {
           e.stopPropagation();
           handleLetterClick(char);
        }}
        className={`transition-colors cursor-pointer select-none active:scale-90 inline-block ${isBloodMode ? 'hover:text-red-500' : 'hover:text-violet-400'}`}
      >
        {char}
      </span>
    ));
  };

  // Main Background Image
  const rosterBg = "https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/character-roster-bg.jpg"; 

  return (
    <div className={`relative flex flex-col w-full h-[calc(100dvh-3rem)] md:h-[100dvh] overflow-hidden bg-transparent transition-all duration-1000 ${isBloodMode ? 'grayscale-[0.2] sepia-[0.3] hue-rotate-[-30deg]' : ''}`}>

      {/* Background Image Layer */}
      <div 
        className="absolute inset-0 bg-cover bg-center opacity-40 z-0 pointer-events-none mix-blend-screen"
        style={{ 
            backgroundImage: `url(${rosterBg})`,
            filter: 'contrast(1.2) brightness(0.6)' 
        }} 
      ></div>

      {/* Dark Overlay Gradient to ensure text legibility */}
      <div className="absolute inset-0 bg-gradient-to-br from-slate-950 via-slate-950/80 to-slate-950 pointer-events-none z-0"></div>

      {/* DYNAMIC ATMOSPHERIC LIGHTING LAYERS */}
      {/* Top ambient glow based on faction */}
      <div className={`fixed top-0 left-0 right-0 h-32 bg-gradient-to-b ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>
      {/* Bottom ambient glow based on faction */}
      <div className={`fixed bottom-0 left-0 right-0 h-32 bg-gradient-to-t ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>

      {/* Scrollable Content Layer */}
      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 md:px-12 pt-4 md:pt-8 pb-32 w-full relative z-10">

            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4 border-b border-white/10 pb-6">
                <div>
                    <h1 className={`text-4xl md:text-6xl font-gothic font-normal text-transparent bg-clip-text bg-gradient-to-r tracking-[0.05em] uppercase flex items-center gap-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)] ${isBloodMode ? 'from-red-300 via-red-100 to-red-500' : 'from-slate-200 via-white to-slate-400'}`}>
                        <div className="flex items-center gap-2">
                            <span className="flex">{renderInteractiveTitle(t('app_title_1', 'Летопись'))}</span> 
                            <span 
                            onClick={(e) => {
                                e.stopPropagation();
                                handleSlashClick();
                            }}
                            className={`px-1 rounded-sm ${isBloodMode ? 'text-red-600' : 'text-violet-500'} cursor-pointer hover:brightness-150 transition-colors select-none active:scale-90 inline-block`}
                            >
                            //
                            </span> 
                            <span className="flex">{renderInteractiveTitle(t('app_title_2', 'Душ'))}</span>
                        </div>
                    </h1>
                    <p className={`font-sans text-sm mt-2 max-w-xl ${isBloodMode ? 'text-red-400/70' : 'text-slate-500'}`}>
                       Реестр сущностей, героев и монстров. Управление характеристиками и судьбами.
                    </p>
                </div>

                {/* Actions Panel */}
                <div className="flex items-center gap-3">
                    {/* Public Training Log Button */}
                    {onOpenTraining && (
                        <Button onClick={onOpenTraining} size="sm" variant="ghost" className="text-slate-400 hover:text-white border border-slate-700/50">
                            <Calendar size={16} /> Журнал Тренировок
                        </Button>
                    )}

                    {/* Admin Only Buttons */}
                    {isAdmin && (
                        <>
                            {onOpenSettings && (
                            <Button onClick={onOpenSettings} size="sm" variant="ghost" className="text-slate-400 hover:text-white border border-slate-700/50">
                                <Settings size={16} />
                            </Button>
                            )}

                            {/* Import Button */}
                            <Button 
                                onClick={() => fileInputRef.current?.click()} 
                                size="sm" 
                                className="bg-slate-800 border-slate-600 text-slate-300 hover:bg-slate-700 hover:text-white"
                                disabled={isImporting}
                            >
                                <Upload size={14} /> Импорт
                            </Button>
                            <input 
                                type="file" 
                                ref={fileInputRef} 
                                className="hidden" 
                                accept=".json" 
                                onChange={handleFileUpload} 
                            />

                            <Button onClick={onCreate} size="sm" className="bg-violet-600/80 border-violet-500 hover:bg-violet-500 text-white shadow-[0_0_15px_rgba(139,92,246,0.3)]">
                            {/* [DIALECT] */}
                            <Plus size={14} /> {t('btn_new', 'Новый')}
                            </Button>
                        </>
                    )}
                </div>
            </div>

            {/* Tabs - Desktop */}
            <div className="hidden md:flex border-b border-white/5 mb-8">
                <TabButton faction={Faction.LIGHT} icon={Sun} />
                <TabButton faction={Faction.DARK} icon={Moon} />
                <TabButton faction={Faction.GRAVEYARD} icon={Skull} />
                <TabButton faction={Faction.NPC} icon={Ghost} />
            </div>

            {/* Tabs - Mobile */}
            <div className="md:hidden flex items-center justify-between border-b border-white/5 pb-4 mb-4">
                <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronLeft size={24} />
                </button>
                <div className={`font-serif font-bold uppercase tracking-widest text-lg ${theme.tab}`}>
                    {t(getLabelKey(activeTab), activeTab)}
                </div>
                <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronRight size={24} />
                </button>
            </div>

            {/* Content Area */}
            <div className="relative min-h-[500px]">

                {activeTab === Faction.NPC && (
                <div className="mb-6">
                    <label className="text-[10px] uppercase font-bold text-slate-500 mb-2 block tracking-widest font-serif">{t('lbl_npc_vol', "Архив Бестиария")}</label>
                    <div className="relative max-w-md">
                        <select 
                        value={npcVolume} 
                        onChange={(e) => handleNpcVolumeChange(e.target.value)}
                        className={`bg-slate-900/50 border text-slate-200 text-sm rounded-lg w-full p-3 outline-none appearance-none font-sans ${isBloodMode ? 'border-red-900/50 focus:border-red-500' : 'border-slate-700 focus:border-violet-500 focus:shadow-[0_0_15px_rgba(139,92,246,0.2)]'}`}
                        >
                        {NPC_VOLUMES.map(v => <option key={v} value={v}>{getVolumeLabel(v)}</option>)}
                        </select>
                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={16} />
                    </div>
                </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
                {filtered.map(char => (
                    <div 
                        key={char.id} 
                        onClick={() => onSelect(char.id)}
                        className={`
                            group relative overflow-hidden rounded-xl cursor-pointer transition-all duration-300
                            bg-slate-900/40 backdrop-blur-md border border-white/5 hover:-translate-y-1
                            ${theme.border} ${theme.glow}
                            content-visibility-auto
                        `}
                    >
                        {/* Card Background Glow */}
                        <div className={`absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 bg-gradient-to-br ${theme.bg} to-transparent pointer-events-none`}></div>

                        <div className="p-4 relative z-10 flex flex-col h-full gap-3">

                            {/* Header: Avatar & Name */}
                            <div className="flex items-start gap-3">
                                <div className="relative shrink-0">
                                    <div className="w-12 h-12 rounded-lg bg-black/50 border border-white/10 overflow-hidden flex items-center justify-center group-hover:border-white/30 transition-colors">
                                        {char.meta.avatar_url ? (
                                            <img src={char.meta.avatar_url} className="w-full h-full object-cover" loading="lazy" decoding="async" />
                                        ) : (
                                            <UserIcon size={20} className="text-slate-600" />
                                        )}
                                    </div>
                                    <div className={`absolute -bottom-1 -right-1 bg-black text-white text-[9px] font-bold px-1.5 rounded border ${isBloodMode ? 'border-red-900' : 'border-white/20'}`}>
                                        {char.profile.level}
                                    </div>
                                </div>

                                <div className="flex-1 min-w-0">
                                    <h3 className={`font-fantasy font-bold text-lg leading-tight truncate ${theme.text} group-hover:text-white transition-colors`}>
                                        {char.profile.name}
                                    </h3>

                                    {/* Subtext: Save Status */}
                                    <div className="flex items-center gap-2 mt-1">
                                        {char.profile.faction === Faction.GRAVEYARD ? (
                                            <span className="text-[10px] text-slate-500 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {char.meta.save_status_reason || t('meta_death_unknown', "Почил")}
                                            </span>
                                        ) : char.meta.save_status ? (
                                            <span className={`text-[10px] uppercase tracking-wide flex items-center gap-1 ${isBloodMode ? 'text-red-400' : 'text-emerald-500/80'}`}>
                                                <ShieldCheck size={10} /> {t('meta_save_ok', 'Сейв есть')}
                                            </span>
                                        ) : (
                                            <span className="text-[10px] text-red-500/80 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {t('meta_save_lost', 'Без сейва')}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Master Link */}
                            {char.meta.master_id && char.profile.faction === Faction.NPC && (
                                <div className="text-[10px] bg-white/5 rounded px-2 py-1 text-violet-300 border border-violet-500/20 flex items-center gap-2">
                                    <LinkIcon size={10} /> 
                                    <span>{t('lbl_linked', 'Связан узами')}</span>
                                </div>
                            )}

                            {/* Stats Grid - Minimalist */}
                            <div className="grid grid-cols-3 gap-1 mt-auto pt-2 border-t border-white/5">
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Sword size={10} className="text-red-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.phys}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Wand2 size={10} className="text-blue-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.magic}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Crown size={10} className="text-purple-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.unique}</span>
                                </div>
                            </div>

                            {/* Equipment Line */}
                            <div className="text-[9px] text-slate-500 truncate h-4">
                                {char.equipment.wearable.filter(w => w.is_equipped).map(w => w.name).join(", ") || ""}
                            </div>
                        </div>
                    </div>
                ))}

                {filtered.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-600 border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/20">
                        <Ghost size={48} className="mb-4 opacity-20"/>
                        <span className="text-sm font-bold uppercase tracking-widest font-serif">{t('msg_empty', 'Лишь ветер гуляет')}</span>
                    </div>
                )}
                </div>
            </div>
      </div>

      {/* [DIALECT] Easter Egg Input Window */}
      {isInputMode && (
          <div className="fixed inset-0 md:absolute md:inset-auto md:bottom-4 md:left-1/2 md:-translate-x-1/2 md:bottom-8 z-[100] animate-fadeIn flex items-center justify-center pointer-events-none p-4">
              <div className="bg-black/95 border border-violet-900 rounded-lg p-4 shadow-[0_0_40px_rgba(139,92,246,0.4)] backdrop-blur-md pointer-events-auto w-full max-w-sm relative">
                <div className="flex items-center gap-2 mb-2 justify-between">
                  <div className="flex items-center gap-2">
                      <Terminal size={14} className="text-violet-500 animate-pulse"/>
                      <span className="text-[10px] font-mono text-violet-300 uppercase tracking-widest">Input Sequence</span>
                  </div>
                </div>
                <div className="bg-slate-950 border border-slate-800 rounded p-3 min-h-[3rem] flex items-center justify-center overflow-hidden">
                    <span className="font-serif text-sm md:text-base text-violet-400 tracking-[0.1em] md:tracking-[0.2em] uppercase drop-shadow-[0_0_5px_rgba(167,139,250,0.8)] break-all text-center">
                      {inputBuffer || <span className="opacity-20">_ _ _ _ _ _</span>}
                    </span>
                </div>
                <div className="text-center mt-2">
                    <span className="text-[9px] text-slate-600 uppercase font-bold tracking-widest">Tap title letters & slashes</span>
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Roster;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_CHARACTER, DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from './constants';
import { CharacterData, InjuryDefinition, TimeUnit, Faction } from './types';
import * as SupabaseService from './utils/supabaseService';
import Roster from './components/Roster';
import SheetHeader from './components/SheetHeader';
import TabEquipment from './components/TabEquipment';
import TabAbilities from './components/TabAbilities';
import TabPassives from './components/TabPassives';
import TabDebuffs from './components/TabDebuffs';
import TabUnits from './components/TabUnits';
import TabMedCard from './components/TabMedCard';
import GlobalSettingsModal from './components/GlobalSettingsModal';
import { TagHintsModal } from './components/TagHintsModal';
import { Button } from './components/Shared';
import { Save, ChevronLeft, ChevronRight, Edit3, Trash2, RotateCcw, Settings, BookOpen, Calculator, ScrollText, Loader2, Tag } from 'lucide-react';
import { DialectProvider, useDialect } from './dialect_module/DialectContext';
import { UIProvider, useUI } from './context/UIContext';
import { TrainingPage } from './pages/TrainingPage';
import { useAuth } from '../../context/AuthContext';

export type DisplayMode = 'lore' | 'mech';

interface RosterModuleProps {
  isAdmin?: boolean;
}

const RosterContent: React.FC<RosterModuleProps> = ({ isAdmin = false }) => {
  const { toggleDialect, isOldSlavonic, isDialectUnlocked, t } = useDialect();
  const { showAlert, showConfirm } = useUI();
  const { user } = useAuth();

  const [view, setView] = useState<'roster' | 'sheet' | 'training'>('roster');
  const [characters, setCharacters] = useState<CharacterData[]>([]);
  const [rosterList, setRosterList] = useState<CharacterData[]>([]);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [charStack, setCharStack] = useState<string[]>([]);

  const [displayMode, setDisplayMode] = useState<DisplayMode>('lore');
  const [isEditMode, setIsEditMode] = useState(false);
  const [activeTab, setActiveTab] = useState<'equipment' | 'abilities' | 'passives' | 'debuffs' | 'units' | 'medcard'>('equipment');

  const [triggersMap, setTriggersMap] = useState<Record<string, string>>({});
  const [injuryDefinitions, setInjuryDefinitions] = useState<InjuryDefinition[]>(DEFAULT_INJURIES);
  const [timeUnits, setTimeUnits] = useState<TimeUnit[]>(DEFAULT_TIME_UNITS);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isTagHintsOpen, setIsTagHintsOpen] = useState(false);

  const SHEET_TABS = useMemo(() => [
    { id: 'equipment', label: t('tab_eq', 'Снаряжение') },
    { id: 'abilities', label: t('tab_ab', 'Способности') },
    { id: 'passives', label: t('tab_ps', 'Пассивки') },
    { id: 'debuffs', label: t('tab_db', 'Дебаффы') },
    { id: 'units', label: t('tab_un', 'Юниты') },
    { id: 'medcard', label: t('tab_mc', 'Мед.Карта') },
  ], [t]);

  const initRef = useRef(false);

  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;
    const init = async () => {
      setIsLoadingData(true);
      try {
        const [chars, trigs, inj, units] = await Promise.all([
          SupabaseService.getAllCharacters(),
          SupabaseService.getGlobalTriggers(),
          SupabaseService.getInjuries(),
          SupabaseService.getTimeUnits()
        ]);
        setCharacters(chars);
        setRosterList(chars);
        setTriggersMap(trigs);
        setInjuryDefinitions(inj);
        setTimeUnits(units);
      } catch (e) { console.error("Failed to init app", e); } finally { setIsLoadingData(false); }
    };
    init();
  }, []);

  const handleCreate = async () => {
    const newChar: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
    newChar.id = crypto.randomUUID();
    newChar.profile.name = "Новая Душа";
    if (user && !isAdmin) newChar.meta.uid = user.id;

    // Inject basic actions right away for new character, hidden by default
    const basicActions = await SupabaseService.getBasicActions();
    if (basicActions && basicActions.length > 0) {
        newChar.ability_groups = [{
            name: "Базовые Действия",
            tags: [],
            abilities: basicActions,
            is_hidden: true
        }];
    }

    const updated = [...characters, newChar];
    setCharacters(updated);
    setRosterList(updated);

    try {
      await SupabaseService.saveCharacter(newChar, isAdmin);
      setActiveCharId(newChar.id);
      setCharStack([newChar.id]);
      setView('sheet');
      setIsEditMode(true);
    } catch (e) {
      showAlert("Ошибка создания: " + e, "Сбой базы данных");
      const reverted = characters.filter(c => c.id !== newChar.id);
      setCharacters(reverted);
      setRosterList(reverted);
    }
  };

  const handleImportCharacter = async (data: CharacterData) => {
      // Ensure we fill missing defaults using INITIAL_CHARACTER
      const merged: CharacterData = {
          ...INITIAL_CHARACTER,
          ...data,
          meta: { ...INITIAL_CHARACTER.meta, ...data.meta, uid: user?.id || 'system' }, // Reset ownership to current user
          id: data.id // Use the generated ID from Roster
      };

      const updated = [...characters, merged];
      setCharacters(updated);
      setRosterList(updated);

      try {
          await SupabaseService.saveCharacter(merged, isAdmin);
      } catch (e) {
          showAlert("Ошибка сохранения импорта: " + e, "Сбой");
          const reverted = characters.filter(c => c.id !== merged.id);
          setCharacters(reverted);
          setRosterList(reverted);
          throw e; // Re-throw to let Roster component handle UI feedback
      }
  };

  const handleSelect = (id: string) => {
    setActiveCharId(id);
    setCharStack([id]);
    setView('sheet');
    setIsEditMode(false);
    window.scrollTo(0,0);
  };

  const handleNavigateToUnit = (unitId: string) => {
    setCharStack(prev => [...prev, unitId]);
    setActiveCharId(unitId);
    window.scrollTo(0,0);
  };

  const handleBack = () => {
    if (charStack.length > 1) {
      const newStack = [...charStack];
      newStack.pop();
      setCharStack(newStack);
      setActiveCharId(newStack[newStack.length - 1]);
    } else {
      setView('roster');
      setActiveCharId(null);
      setCharStack([]);
    }
  };

  const handleNextTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const nextId = SHEET_TABS[(idx + 1) % SHEET_TABS.length].id;
      setActiveTab(nextId as any);
  };

  const handlePrevTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const prevId = SHEET_TABS[(idx - 1 + SHEET_TABS.length) % SHEET_TABS.length].id;
      setActiveTab(prevId as any);
  };

  const activeChar = characters.find(c => c.id === activeCharId);
  const isOwner = user && activeChar && activeChar.meta.uid === user.id;
  const canEdit = isAdmin || isOwner;

  const updateActiveChar = (updates: Partial<CharacterData>) => {
    if (!activeChar) return;
    const updated = { ...activeChar, ...updates };
    setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
  };

  const handleSave = async () => {
    if (!activeChar) return;
    try {
      await SupabaseService.saveCharacter(activeChar, isAdmin);
      setIsEditMode(false);
      setRosterList(characters);
    } catch (e) { showAlert("Ошибка сохранения: " + e, "Ошибка"); }
  };

  const handleInstantUpdate = async (eq: CharacterData['equipment']) => {
      if (!activeChar) return;
      const updated = { ...activeChar, equipment: eq };
      const newChars = characters.map(c => c.id === activeChar.id ? updated : c);
      setCharacters(newChars);
      await SupabaseService.saveCharacter(updated, isAdmin);
      setRosterList(newChars);
  };

  const handleDelete = async (idToDelete?: string) => {
    const targetId = idToDelete || activeChar?.id;
    if (!targetId) return;
    showConfirm("Вы уверены? Это действие необратимо уничтожит сущность.", async () => {
        try {
          await SupabaseService.deleteCharacter(targetId);
          const updated = characters.filter(c => c.id !== targetId);
          setCharacters(updated);
          setRosterList(updated);
          if (targetId === activeCharId) handleBack();
        } catch (e) { showAlert("Ошибка удаления: " + e, "Ошибка"); }
    }, "Уничтожение");
  };

  const createUnit = async () => {
      if (!activeChar) return;
      const unit: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
      unit.id = crypto.randomUUID();
      unit.profile.name = "Новый Юнит";
      unit.meta.master_id = activeChar.id;
      unit.meta.uid = activeChar.meta.uid; 

      const basicActions = await SupabaseService.getBasicActions();
      if (basicActions && basicActions.length > 0) {
          unit.ability_groups = [{
              name: "Базовые Действия",
              tags: [],
              abilities: basicActions,
              is_hidden: true // Hidden by default
          }];
      }

      try {
        await SupabaseService.saveCharacter(unit, isAdmin);
        const updated = [...characters, unit];
        setCharacters(updated);
        setRosterList(updated);
        handleNavigateToUnit(unit.id);
        setIsEditMode(true);
      } catch (e) { showAlert("Cannot create unit: " + e, "Ошибка"); }
  };

  const getSheetBackground = (faction: Faction) => {
      if (faction === Faction.LIGHT) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Light_bg.jpg';
      if (faction === Faction.DARK) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Dark_bg.jpg';
      if (faction === Faction.NPC) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Bestiary_bg.jpg';
      if (faction === Faction.GRAVEYARD) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/graveyard_bg.jpg';
      return null;
  };

  if (isLoadingData) {
    return (
      <div className="min-h-full flex items-center justify-center text-violet-500">
        <Loader2 size={48} className="animate-spin" />
      </div>
    );
  }

  if (view === 'training') return <TrainingPage characters={characters} onBack={() => setView('roster')} />;

  return (
    <div className="font-sans text-slate-300 selection:bg-violet-900/40 selection:text-white h-full relative">
      {view === 'sheet' && activeChar && (
          <>
            {getSheetBackground(activeChar.profile.faction) ? (
                <div className="fixed inset-0 z-0 overflow-hidden">
                    <div className="absolute inset-0 bg-cover bg-center bg-no-repeat bg-fixed blur-[5px] scale-105" style={{ backgroundImage: `url(${getSheetBackground(activeChar.profile.faction)})` }}></div>
                    <div className="absolute inset-0 bg-black/50"></div>
                </div>
            ) : ( <div className="fixed inset-0 bg-gradient-to-b from-slate-900 to-black z-0 pointer-events-none"></div> )}
          </>
      )}

      {view === 'roster' && (
        <>
          <Roster characters={rosterList} onSelect={handleSelect} onCreate={handleCreate} onImport={handleImportCharacter} onOpenSettings={() => setIsSettingsOpen(true)} onOpenTraining={() => setView('training')} />
          {isSettingsOpen && isAdmin && (
             <GlobalSettingsModal onClose={() => setIsSettingsOpen(false)} triggersMap={triggersMap} onSaveTriggers={async (t) => { await SupabaseService.saveGlobalTriggers(t); setTriggersMap(t); }} injuryDefinitions={injuryDefinitions} onSaveInjuries={async (inj) => { await SupabaseService.saveInjuries(inj); setInjuryDefinitions(inj); }} timeUnits={timeUnits} onSaveTimeUnits={async (units) => { await SupabaseService.saveTimeUnits(units); setTimeUnits(units); }} />
          )}
        </>
      )}

      {view === 'sheet' && activeChar && (
        <div className="relative z-10 max-w-5xl mx-auto p-4 md:p-6 animate-fade-in pb-32">
          <div className="flex items-center justify-between mb-6 bg-[#020617]/80 backdrop-blur-md p-3 border-b border-violet-900/30 sticky top-12 min-[1150px]:top-0 z-50 shadow-lg rune-clip-r">
            <div className="flex items-center gap-2">
               <Button variant="secondary" size="sm" onClick={handleBack} className="bg-[#0f172a] border-slate-700 hover:bg-slate-800 text-slate-200 hover:text-white shadow-md z-10 font-serif tracking-wide">
                 <ChevronLeft size={18} /> {t('act_back', "Назад")}
               </Button>
               {charStack.length > 1 && ( <span className="text-xs text-slate-500 font-serif uppercase tracking-wider hidden md:inline ml-2 border-l border-slate-700 pl-3"> {t('lbl_depth', 'Глубина')}: {charStack.length} </span> )}
            </div>
            <div className="flex items-center gap-2">
               {isDialectUnlocked && ( <button onClick={toggleDialect} className={`p-2 rounded border transition-all ${isOldSlavonic ? 'bg-amber-900/20 text-amber-500 border-amber-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`} title="Old Slavonic Dialect"> <ScrollText size={18} /> </button> )}
               <div className="h-6 w-px bg-slate-800 mx-1"></div>
               <div className="flex bg-[#0f172a] p-1 rounded-sm border border-slate-800">
                  <button onClick={() => setDisplayMode('lore')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'lore' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Lore Mode"> <BookOpen size={16} /> </button>
                  <button onClick={() => setDisplayMode('mech')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'mech' ? 'bg-violet-900/50 text-violet-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Mechanic Mode"> <Calculator size={16} /> </button>
               </div>

               {/* Tag Hints - Visible to All */}
               <button onClick={() => setIsTagHintsOpen(true)} className="p-2 text-slate-500 hover:text-violet-300 transition-colors ml-1" title="Справочник Тегов"> <Tag size={18} /> </button>

               {canEdit && (
                 <>
                   <div className="h-6 w-px bg-slate-800 mx-1"></div>
                   {isEditMode ? (
                     <>
                        {isAdmin && ( <Button variant="danger" size="sm" onClick={() => handleDelete(activeChar.id)} title="Delete"> <Trash2 size={16} /> </Button> )}
                        <Button variant="secondary" size="sm" onClick={() => { showConfirm("Отменить несохраненные изменения?", () => { const original = rosterList.find(c => c.id === activeChar.id); if (original) updateActiveChar(original); setIsEditMode(false); }); }}> <RotateCcw size={16} /> </Button>
                        <Button className="bg-emerald-900/80 hover:bg-emerald-800 border-emerald-500/50" size="sm" onClick={handleSave}> <Save size={16} /> {t('act_save', "Сохранить")} </Button>
                     </>
                   ) : ( <Button variant="secondary" size="sm" onClick={() => setIsEditMode(true)}> <Edit3 size={16} /> {t('act_edit', "Ред.")} </Button> )}
                 </>
               )}
            </div>
          </div>

          <SheetHeader character={activeChar} isEditMode={isEditMode} onChange={updateActiveChar} displayMode={displayMode} setDisplayMode={setDisplayMode} characters={characters} onNavigate={handleNavigateToUnit} onDelete={isAdmin ? handleDelete : undefined} injuryDefinitions={injuryDefinitions} />

          <div className="hidden md:flex sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 px-0 md:px-0">
             <div className="flex overflow-x-auto no-scrollbar gap-1 pb-1">
                {SHEET_TABS.map(tab => (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 text-sm font-serif font-bold uppercase tracking-widest transition-all whitespace-nowrap relative group flex-shrink-0 ${ activeTab === tab.id ? 'text-violet-300' : 'text-slate-600 hover:text-slate-300' }`} >
                    {tab.label}
                    {activeTab === tab.id && ( <div className="absolute bottom-0 left-0 w-full h-0.5 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div> )}
                  </button>
                ))}
             </div>
          </div>

          <div className="md:hidden sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 -mx-4 px-4 py-2 flex items-center justify-between">
              <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronLeft size={24} /> </button>
              <div className="font-serif font-bold uppercase tracking-widest text-violet-300 text-sm"> {SHEET_TABS.find(t => t.id === activeTab)?.label} </div>
              <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronRight size={24} /> </button>
          </div>

          <div>
            {activeTab === 'equipment' && ( <TabEquipment character={activeChar} isEditMode={isEditMode} onChange={(eq) => updateActiveChar({ equipment: eq })} displayMode={displayMode} onInstantUpdate={(eq) => handleInstantUpdate(eq)} /> )}
            {activeTab === 'abilities' && ( <TabAbilities character={activeChar} isEditMode={isEditMode} onChange={(groups) => updateActiveChar({ ability_groups: groups })} displayMode={displayMode} timeUnits={timeUnits} /> )}
            {activeTab === 'passives' && ( <TabPassives character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} /> )}
            {activeTab === 'debuffs' && ( <TabDebuffs character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} /> )}
            {activeTab === 'units' && ( <TabUnits master={activeChar} units={characters} onCreateUnit={createUnit} onNavigateToUnit={handleNavigateToUnit} isEditMode={isEditMode} /> )}
            {activeTab === 'medcard' && ( <TabMedCard character={activeChar} isEditMode={isEditMode} onChange={(mc) => updateActiveChar({ medcard: mc })} injuryDefinitions={injuryDefinitions} /> )}
          </div>
        </div>
      )}

      {isTagHintsOpen && ( <TagHintsModal isOpen={isTagHintsOpen} onClose={() => setIsTagHintsOpen(false)} isAdmin={isAdmin} /> )}
    </div>
  );
};

export const RosterAdminContainer: React.FC = () => { return null; };
const RosterModule: React.FC<RosterModuleProps> = (props) => ( <DialectProvider> <UIProvider> <RosterContent {...props} /> </UIProvider> </DialectProvider> );
export default RosterModule;

import React, { useRef, useState, useMemo } from 'react';
import { CharacterData, Faction, StatType, InjuryDefinition } from '../types';
import { NPC_VOLUMES } from '../constants';
import { StyledInput, StyledTextarea, StyledSelect, StatIcons, StatColors, StatBg, Button } from './Shared';
import { downloadCharacterFile } from '../utils/storage';
import { Coins, User, Download, Plus, Trash2, Skull, GitBranch, ShieldCheck, Upload, Loader2, Link2, Link2Off, ChevronLeft, ScrollText, BookOpen, Calculator, RotateCcw, Save, Edit3, FileJson, X, Check } from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';
import { DisplayMode } from '../App';
import { uploadAvatar } from '../utils/supabaseService';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';
import { useUI } from '../context/UIContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  onChange: (u: Partial<CharacterData>) => void;
  displayMode: DisplayMode;
  setDisplayMode: (m: DisplayMode) => void;
  characters: CharacterData[];
  onNavigate: (id: string) => void;
  onDelete?: (id: string) => void;
  injuryDefinitions?: InjuryDefinition[];
}

// Memoized Chart Component for Header
const HeaderRadarChart = React.memo(({ data }: { data: any[] }) => {
  return (
    <ResponsiveContainer width="100%" height="100%">
      <RadarChart cx="50%" cy="50%" outerRadius="65%" data={data}>
        <PolarGrid stroke="#334155" strokeOpacity={0.5} />
        <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 9, fontWeight: '900', fontFamily: 'Cinzel' }} />
        <PolarRadiusAxis angle={30} domain={[0, 25]} tick={false} axisLine={false} />
        <Radar
          name="Stats"
          dataKey="A"
          stroke="#8b5cf6"
          strokeWidth={2}
          fill="#8b5cf6"
          fillOpacity={0.3}
          isAnimationActive={false} 
        />
      </RadarChart>
    </ResponsiveContainer>
  );
}, (prev, next) => JSON.stringify(prev.data) === JSON.stringify(next.data));

const SheetHeader: React.FC<Props> = ({ character, isEditMode, onChange, displayMode, setDisplayMode, characters, onNavigate, onDelete, injuryDefinitions = [] }) => {
  /* [DIALECT] */ const { t, isToggleVisible, toggleDialect, isOldSlavonic } = useDialect();
  const { showAlert, showConfirm } = useUI();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isUploading, setIsUploading] = useState(false);

  // Import State
  const [showImportModal, setShowImportModal] = useState(false);
  const [importText, setImportText] = useState("");
  const importFileRef = useRef<HTMLInputElement>(null);

  // New Structure: profile instead of identity
  const updateProfile = (field: keyof CharacterData['profile'], val: any) => {
    onChange({ profile: { ...character.profile, [field]: val } });
  };

  const updateMeta = (field: keyof CharacterData['meta'], val: any) => {
    onChange({ meta: { ...character.meta, [field]: val } });
  };

  const updateStats = (field: keyof CharacterData['stats'], val: any) => {
    onChange({ stats: { ...character.stats, [field]: val } });
  };

  const updateResources = (idx: number, field: string, val: any) => {
    const next = [...character.resources];
    next[idx] = { ...next[idx], [field]: val };
    onChange({ resources: next });
  };

  const addResource = () => {
    const next = [...character.resources, { label: "Ресурс", current: 0, max: 0 }];
    onChange({ resources: next });
  };

  const removeResource = (idx: number) => {
    showConfirm("Вы уверены, что хотите удалить этот ресурс?", () => {
      const next = character.resources.filter((_, i) => i !== idx);
      onChange({ resources: next });
    }, "Удаление ресурса");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const url = await uploadAvatar(file);
      updateMeta('avatar_url', url);
    } catch (error: any) {
      showAlert(error.message || "Ошибка загрузки файла", "Ошибка");
    } finally {
      setIsUploading(false);
      // Reset input so same file can be selected again if needed
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  // --- JSON Import Logic ---
  const processJsonImport = (jsonData: any) => {
      try {
          if (!jsonData.profile || !jsonData.stats) {
              throw new Error("Неверная структура JSON (нет profile или stats)");
          }

          // Safety merge: Keep ID and UID from current session to prevent overwriting ownership
          const safeData: Partial<CharacterData> = {
              ...jsonData,
              id: character.id, // FORCE KEEP CURRENT ID
              meta: {
                  ...jsonData.meta,
                  uid: character.meta.uid, // FORCE KEEP CURRENT OWNER
                  // Preserve existing avatar if new one is empty, or use new one
                  avatar_url: jsonData.meta?.avatar_url || character.meta.avatar_url,
                  master_id: jsonData.meta?.master_id || character.meta.master_id
              }
          };

          onChange(safeData);
          showAlert("Данные персонажа успешно загружены и применены.", "Импорт завершен");
          setShowImportModal(false);
          setImportText("");
      } catch (e: any) {
          showAlert("Ошибка обработки данных: " + e.message, "Ошибка");
      }
  };

  const handleImportText = () => {
      try {
          const parsed = JSON.parse(importText);
          processJsonImport(parsed);
      } catch (e) {
          showAlert("Невалидный JSON текст.", "Ошибка");
      }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (ev) => {
          try {
              const parsed = JSON.parse(ev.target?.result as string);
              processJsonImport(parsed);
          } catch (e) {
              showAlert("Ошибка чтения файла JSON.", "Ошибка");
          } finally {
              if (importFileRef.current) importFileRef.current.value = "";
          }
      };
      reader.readAsText(file);
  };

  // Calculate Trauma (Phys Penalty) - uses 'medcard'
  const getTraumaPenalty = () => {
    let penalty = 0;

    // Safety check for medcard/injuries existence
    const injuries = character.medcard?.injuries || [];

    const countsByTag: Record<string, number> = {};
    injuries.forEach(inj => {
      countsByTag[inj.template_id] = (countsByTag[inj.template_id] || 0) + (inj.count || 1);
    });

    Object.entries(countsByTag).forEach(([tag, totalCount]) => {
       const def = injuryDefinitions.find(d => d.tag === tag);
       if (def && def.type === 1) { // Type 1 is Physical
          const val = Math.abs(def.value);
          if (def.stack && def.stack > 1) {
             const appliedStacks = Math.floor(totalCount / def.stack);
             penalty += appliedStacks * val;
          } else {
             penalty += totalCount * val;
          }
       }
    });

    return penalty;
  };

  const trauma = getTraumaPenalty();
  const maxTrauma = 40; // Death threshold assumption
  const traumaPercent = Math.min(100, (trauma / maxTrauma) * 100);

  const chartData = useMemo(() => [
    // [DIALECT] Translate chart labels
    { subject: t('stat_phys_short', 'ФИЗ'), A: character.stats.phys, fullMark: 30 },
    { subject: t('stat_mag_short', 'МАГ'), A: character.stats.magic, fullMark: 30 },
    { subject: t('stat_uni_short', 'УНИК'), A: character.stats.unique, fullMark: 30 },
  ], [character.stats, t]);

  // Dynamic Styles based on Faction - Darker, more magical
  const getFactionColor = (f: Faction) => {
    switch (f) {
      case Faction.LIGHT: return "text-amber-300 border-amber-500/20 shadow-[0_0_15px_rgba(251,191,36,0.1)]";
      case Faction.DARK: return "text-violet-300 border-violet-500/20 shadow-[0_0_15px_rgba(139,92,246,0.1)]";
      case Faction.NPC: return "text-red-400 border-red-500/20 shadow-[0_0_15px_rgba(248,113,113,0.1)]";
      case Faction.GRAVEYARD: return "text-slate-400 border-slate-600/20";
      default: return "text-violet-300 border-violet-500/20";
    }
  };

  const factionColor = getFactionColor(character.profile.faction);

  // Companion Logic
  const COMPANION_VOLUME = "Спутники и Рабы";
  const master = character.meta.master_id ? characters.find(c => c.id === character.meta.master_id) : null;
  const isCompanion = character.profile.faction === Faction.NPC && character.profile.npc_volume === COMPANION_VOLUME;
  const isUnit = !!character.meta.master_id && !isCompanion;

  // [DIALECT] Helper for mapping
  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getFactionLabel = (f: Faction) => {
      switch(f) {
          case Faction.LIGHT: return t('fac_light', Faction.LIGHT);
          case Faction.DARK: return t('fac_dark', Faction.DARK);
          case Faction.NPC: return t('fac_npc', Faction.NPC);
          case Faction.GRAVEYARD: return t('fac_graveyard', Faction.GRAVEYARD);
          default: return f;
      }
  };

  return (
    <div className="space-y-6 mb-6">

      {/* 1. Header Controls & Trauma Bar */}
      <div className="bg-[#050b14] border border-violet-900/30 p-3 relative min-[1150px]:sticky min-[1150px]:top-16 z-40 shadow-2xl rune-clip-r">
        <div className="flex flex-col md:flex-row gap-4 items-center justify-between">

          {/* Trauma Bar (The "Health" Bar) */}
          <div className="flex-1 w-full px-2">
            <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500 mb-1 font-serif tracking-wider">
              {/* [DIALECT] */}
              <span>{t('mech_integrity', "Целостность Тела")}</span>
              <span className={trauma >= 40 ? "text-red-500 animate-pulse" : "text-slate-400"}>
                 -{trauma} / -{maxTrauma} {t('mech_injuries', 'Штраф')}
              </span>
            </div>
            <div className="h-2 w-full bg-[#020408] border border-slate-800 relative">
               {/* Markers */}
               <div className="absolute left-[25%] top-0 bottom-0 w-px bg-slate-800 z-10"></div>
               <div className="absolute left-[50%] top-0 bottom-0 w-px bg-slate-800 z-10"></div>
               <div className="absolute left-[75%] top-0 bottom-0 w-px bg-slate-800 z-10"></div>

               {/* Fill */}
               <div 
                 className={`h-full transition-all duration-500 ${trauma >= 35 ? 'bg-red-600 shadow-[0_0_10px_red]' : 'bg-red-900/80 shadow-[0_0_5px_red]'}`}
                 style={{ width: `${traumaPercent}%` }}
               ></div>
            </div>
          </div>

          {/* Quick Actions */}
          <div className="flex items-center gap-3">
             {/* Gold (Juhe) - Currencies now in profile */}
             <div className="flex items-center gap-2 text-amber-400 bg-amber-950/30 px-3 py-1 border border-amber-900/30 font-serif" title={t('meta_gold', "Джухе")}>
                <Coins size={14} />
                {isEditMode ? 
                  <input type="number" className="w-12 bg-transparent text-xs font-mono text-center focus:outline-none" value={character.profile.currencies.juhe || 0} onChange={e => updateProfile('currencies', {...character.profile.currencies, juhe: parseInt(e.target.value)})} /> 
                  : <span className="text-xs font-mono font-bold">{character.profile.currencies.juhe || 0}</span>
                }
             </div>

             {/* Silver (Jumi) */}
             <div className="flex items-center gap-2 text-slate-300 bg-slate-900/50 px-3 py-1 border border-slate-700 font-serif" title={t('meta_silver', "Джуми")}>
                <Coins size={14} />
                {isEditMode ? 
                  <input type="number" className="w-12 bg-transparent text-xs font-mono text-center focus:outline-none" value={character.profile.currencies.jumi || 0} onChange={e => updateProfile('currencies', {...character.profile.currencies, jumi: parseInt(e.target.value)})} /> 
                  : <span className="text-xs font-mono font-bold">{character.profile.currencies.jumi || 0}</span>
                }
             </div>

             {/* Import Button (Only in Edit Mode) */}
             {isEditMode && (
                 <button 
                    onClick={() => setShowImportModal(true)} 
                    className="text-slate-500 hover:text-white transition-colors bg-slate-800/50 p-1 rounded hover:bg-slate-700" 
                    title="Загрузить из JSON"
                 >
                    <FileJson size={18} />
                 </button>
             )}

             <button onClick={() => downloadCharacterFile(character)} className="text-slate-500 hover:text-white transition-colors" title="Скачать JSON"><Download size={18} /></button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Identity & Stats */}
        <div className="lg:col-span-2 space-y-4">

           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Avatar Column */}
              <div className="col-span-1 flex flex-col gap-2">
                 {/* Rune-shaped Avatar */}
                 <div className={`aspect-square bg-[#050b14] border border-violet-900/20 overflow-hidden relative group rune-clip ${factionColor.split(' ')[1]}`}>
                    {character.meta.avatar_url ? (
                      <img src={character.meta.avatar_url} alt="Avatar" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-slate-800"><User size={48}/></div>
                    )}

                    {/* Upload Overlay */}
                    {isEditMode && (
                      <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                         <button 
                           onClick={() => fileInputRef.current?.click()}
                           disabled={isUploading}
                           className="bg-violet-600 hover:bg-violet-500 text-white rounded-full p-3 shadow-lg flex items-center gap-2 font-bold text-xs"
                         >
                            {isUploading ? <Loader2 size={20} className="animate-spin" /> : <Upload size={20} />}
                         </button>
                      </div>
                    )}
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileUpload} 
                    />
                 </div>

                 {/* Master/Unit Link */}
                 {character.meta.master_id && (
                   <button 
                     onClick={() => onNavigate(character.meta.master_id!)}
                     className="flex items-center justify-center gap-1 bg-violet-900/10 text-violet-400 hover:bg-violet-900/30 hover:text-violet-200 transition-all text-[10px] font-bold py-2 px-2 border border-violet-800/30 w-full rune-clip-r font-serif uppercase tracking-widest"
                   >
                     <GitBranch size={12} /> 
                     {master ? `СВЯЗАН: ${master.profile.name}` : "ЮНИТ (СВЯЗАН)"}
                   </button>
                 )}

                 {isEditMode && (
                   <div className="flex flex-col gap-1">
                      <input 
                        type="text" 
                        placeholder="URL аватарки" 
                        className="bg-[#020408] border border-slate-800 text-xs p-1 rounded-sm w-full text-slate-500 focus:text-slate-200 outline-none" 
                        value={character.meta.avatar_url}
                        onChange={e => updateMeta('avatar_url', e.target.value)}
                      />
                      <button 
                         onClick={() => fileInputRef.current?.click()}
                         className="flex items-center justify-center gap-2 bg-slate-900 hover:bg-slate-800 border border-slate-800 text-slate-400 hover:text-white text-[10px] py-1 rounded-sm w-full uppercase font-bold tracking-wider font-serif"
                      >
                         {isUploading ? <Loader2 size={12} className="animate-spin" /> : <Upload size={12} />}
                         {/* [DIALECT] */}
                         {isUploading ? t('meta_uploading', "Загрузка...") : t('meta_upload_avatar', "Загрузить (10MB)")}
                      </button>
                   </div>
                 )}

                 {/* Save Status / Death Cause Toggle */}
                 <div className="flex flex-col gap-2 mt-2">
                   {character.profile.faction !== Faction.GRAVEYARD ? (
                     <>
                        <button 
                           onClick={() => isEditMode && updateMeta('save_status', !character.meta.save_status)}
                           className={`flex items-center justify-center gap-2 py-2 rounded-sm border w-full text-xs font-bold font-serif uppercase tracking-wider transition-all ${
                               character.meta.save_status 
                               ? 'bg-emerald-900/10 text-emerald-500 border-emerald-900/30 hover:bg-emerald-900/20' 
                               : 'bg-red-950/20 text-red-500 border-red-900/30 hover:bg-red-900/20'
                           }`}
                        >
                           {character.meta.save_status ? <ShieldCheck size={14} /> : <Skull size={14} />}
                           {/* [DIALECT] */}
                           {character.meta.save_status ? t('meta_save_ok', "Есть сейв") : t('meta_save_lost', "Сейв потерян")}
                        </button>

                        {!character.meta.save_status && (
                          <StyledTextarea
                            isEditMode={isEditMode}
                            value={character.meta.save_status_reason || ""}
                            onChange={e => updateMeta('save_status_reason', e.target.value)}
                            placeholder="Укажите причину потери сейва..."
                            className="text-[10px] text-red-300 bg-red-950/10 border-red-900/20 min-h-[50px] italic text-center font-serif"
                          />
                        )}
                     </>
                   ) : (
                     // Graveyard Logic
                     <div className="flex flex-col gap-1">
                        <div className="flex items-center justify-center gap-2 py-2 rounded-sm border w-full text-xs font-bold font-serif uppercase tracking-widest bg-slate-900/50 border-slate-700 text-slate-400">
                           <Skull size={14} />
                           {/* [DIALECT] */}
                           {t('meta_death_cause', "Причина Смерти")}
                        </div>
                        <StyledTextarea
                           isEditMode={isEditMode}
                           value={character.meta.save_status_reason || ""}
                           onChange={e => updateMeta('save_status_reason', e.target.value)}
                           placeholder="Укажите причину смерти..."
                           className="text-[10px] text-slate-400 bg-slate-950/50 border-slate-800 min-h-[60px] italic text-center font-serif"
                        />
                     </div>
                   )}
                 </div>
              </div>

              {/* Stats & Info Column */}
              <div className="col-span-2 space-y-4">

                 {/* Name & Faction */}
                 <div className="bg-[#050b14] p-4 border border-violet-900/20 relative rune-clip-r">
                     <div className="flex flex-col gap-2">
                        <StyledInput 
                           /* [DIALECT] */
                           label={t('lbl_name', "Имя персонажа")}
                           isEditMode={isEditMode} 
                           value={character.profile.name} 
                           onChange={e => updateProfile('name', e.target.value)} 
                           className={`text-2xl font-black font-gothic uppercase tracking-tight ${factionColor.split(' ')[0]} drop-shadow-md bg-transparent border-b border-white/5 pb-1`} 
                        />
                        <div className="flex flex-wrap items-end gap-4">
                           <div className="flex-1 min-w-[140px]">
                              <StyledSelect 
                                /* [DIALECT] */
                                label={t('lbl_faction', "Фракция")}
                                isEditMode={isEditMode} 
                                value={character.profile.faction} 
                                onChange={e => updateProfile('faction', e.target.value)}
                                // [DIALECT] Translate Options
                                options={Object.values(Faction).map(f => ({ label: getFactionLabel(f), value: f }))} 
                                className="text-sm font-medium text-slate-400 font-serif tracking-wide"
                              />
                           </div>

                           {character.profile.faction === Faction.NPC && (
                              <div className="flex-1 min-w-[140px]">
                                 <StyledSelect 
                                   // [DIALECT]
                                   label={t('lbl_npc_vol', "Том NPC")}
                                   isEditMode={isEditMode} 
                                   value={character.profile.npc_volume || NPC_VOLUMES[0]} 
                                   onChange={e => updateProfile('npc_volume', e.target.value)}
                                   // [DIALECT] Translate Options
                                   options={NPC_VOLUMES.map(v => ({ label: getVolumeLabel(v), value: v }))} 
                                   className="text-sm font-medium text-red-400 font-serif tracking-wide"
                                 />
                              </div>
                           )}

                           {/* Master Selector Logic: Show if isCompanion OR if it's a Unit (has master) */}
                           {isEditMode && (isCompanion || isUnit || character.meta.master_id) && (
                              <div className="flex-1 min-w-[140px]">
                                 <span className="text-[9px] uppercase font-bold text-slate-600 tracking-widest font-serif block mb-1">Привязка (Хозяин)</span>
                                 <div className="flex gap-2">
                                    <select 
                                      className="bg-[#0b0d10] border border-violet-900/30 text-slate-300 text-xs rounded-sm px-2 py-1.5 focus:border-violet-500 w-full outline-none font-serif"
                                      value={character.meta.master_id || ""}
                                      onChange={e => updateMeta('master_id', e.target.value || undefined)}
                                    >
                                        <option value="">-- Нет / Свободен --</option>
                                        {characters
                                          .filter(c => c.id !== character.id && c.profile.faction !== Faction.NPC) 
                                          .map(c => (
                                          <option key={c.id} value={c.id}>{c.profile.name}</option>
                                        ))}
                                    </select>

                                    {/* Unlink / Banish Button */}
                                    {character.meta.master_id && (
                                       <button 
                                          onClick={() => {
                                             if (isCompanion) {
                                                updateMeta('master_id', undefined);
                                             } else if (onDelete) {
                                                // It's a unit, confirm deletion
                                                onDelete(character.id);
                                             }
                                          }}
                                          title={isCompanion ? "Разорвать связь" : "Изгнать (Удалить Юнита)"}
                                          className="bg-red-900/20 border border-red-500/30 text-red-400 hover:text-white hover:bg-red-900/50 p-1.5 rounded-sm transition-all"
                                       >
                                          {isCompanion ? <Link2Off size={14}/> : <Trash2 size={14}/>}
                                       </button>
                                    )}
                                 </div>
                              </div>
                           )}

                           <div className="flex items-center gap-2 pb-1">
                             <span className="text-[10px] uppercase font-bold text-slate-600 font-serif tracking-widest">
                                {/* [DIALECT] */}
                                {t('lbl_level', 'Уровень')}
                             </span>
                             {isEditMode ? (
                               <select 
                                 className="bg-[#0b0d10] border border-violet-900/30 text-xs rounded-sm p-1 text-slate-300 focus:outline-none focus:border-violet-600 font-mono" 
                                 value={character.profile.level} 
                                 onChange={e => updateProfile('level', parseInt(e.target.value))}
                               >
                                 {[1,2,3,4,5].map(l => (
                                     <option key={l} value={l} disabled={l === 5 && character.profile.faction !== Faction.NPC}>
                                         {l}
                                     </option>
                                 ))}
                               </select>
                             ) : (
                               <span className="text-violet-400 font-bold font-mono text-lg drop-shadow-glow">{character.profile.level}</span>
                             )}
                           </div>
                        </div>
                     </div>
                 </div>

                 <div className="flex gap-4 h-48 relative">
                    {/* Compact Chart - ABSOLUTE positioning + flex-1 min-h-0 to prevent flex width calculation issues */}
                    {/* Optimization: Don't render chart in Edit Mode to improve typing performance */}
                    <div className="flex-1 relative min-w-0 h-full bg-slate-950/70 backdrop-blur-sm rounded-xl border border-violet-900/20 overflow-hidden">
                       <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
                           {!isEditMode && <HeaderRadarChart data={chartData} />}
                           {isEditMode && (
                               <div className="flex items-center justify-center h-full text-slate-600 text-xs font-serif uppercase tracking-widest opacity-50">
                                   Диаграмма скрыта при редактировании
                               </div>
                           )}
                       </div>
                    </div>

                    {/* Numeric Blocks */}
                    <div className="flex flex-col justify-between w-28 gap-1">
                        {[StatType.PHYS, StatType.MAGIC, StatType.UNIQUE].map(stat => (
                          <div key={stat} className={`relative px-2 py-1 rounded-sm border flex items-center justify-between gap-2 transition-all ${StatBg[stat]}`}>
                             <div className={`${StatColors[stat].split(' ')[0]}`}>{StatIcons[stat]}</div>
                             {isEditMode ? (
                               <input 
                                 type="number" 
                                 value={character.stats[stat as keyof CharacterData['stats']]} 
                                 onChange={(e) => updateStats(stat as keyof CharacterData['stats'], parseInt(e.target.value))}
                                 className="bg-transparent text-lg font-mono font-bold text-right w-full focus:outline-none text-slate-200"
                               />
                             ) : (
                               <span className="text-lg font-mono font-bold text-slate-200 drop-shadow-sm">{character.stats[stat as keyof CharacterData['stats']]}</span>
                             )}
                          </div>
                        ))}
                    </div>
                 </div>
              </div>
           </div>

           {/* Bio (Lore Mode Only or Edit) */}
           {(displayMode === 'lore' || isEditMode) && (
             <div className="bg-[#050b14] border border-violet-900/20 p-4 relative shadow-inner">
               <StyledTextarea 
                 /* [DIALECT] */
                 label={t('lbl_bio', "Биография")}
                 isEditMode={isEditMode} 
                 value={character.profile.bio} 
                 onChange={e => updateProfile('bio', e.target.value)} 
                 className="min-h-[80px] text-slate-400 italic font-serif" 
               />
             </div>
           )}
        </div>

        {/* Resources */}
        <div className="space-y-3">
          {character.resources.map((res, idx) => (
            <div key={idx} className="bg-[#050b14] border border-slate-800 p-3 relative overflow-hidden group flex gap-2 items-center rune-clip-r">
               <div className="flex-1">
                 <div className="flex justify-between items-center mb-1 relative z-10">
                   {isEditMode ? (
                     <input className="bg-transparent font-bold text-xs text-slate-300 w-1/2 uppercase tracking-wide font-serif" value={res.label} onChange={e => updateResources(idx, 'label', e.target.value)} />
                   ) : (
                     <span className="font-bold text-xs text-slate-400 uppercase tracking-wide font-serif">
                        {/* [DIALECT] Simple manual mapping for standard resources if they match default names */}
                        {res.label === "HP" ? t('res_hp', "HP") : res.label === "MP" ? t('res_mp', "MP") : res.label === "Усталость" ? t('res_fatigue', "Усталость") : res.label}
                     </span>
                   )}
                   <div className="flex items-center gap-1 font-mono text-sm">
                      {isEditMode ? (
                         <>
                           <input type="number" className="bg-slate-900 w-10 text-center rounded-sm border border-slate-700 text-xs text-slate-200" value={res.current} onChange={e => updateResources(idx, 'current', parseInt(e.target.value))} />
                           <span className="text-slate-600">/</span>
                           <input type="number" className="bg-slate-900 w-10 text-center rounded-sm border border-slate-700 text-xs text-slate-200" value={res.max} onChange={e => updateResources(idx, 'max', parseInt(e.target.value))} />
                         </>
                      ) : (
                         <span className="text-violet-400 font-bold">
                           {res.current}
                           {res.max > 0 && <span className="text-slate-600 text-xs ml-0.5">/{res.max}</span>}
                         </span>
                      )}
                   </div>
                 </div>

                 {!isEditMode && res.max > 0 && (
                   <div className="w-full bg-[#020408] h-1.5 rounded-full overflow-hidden mt-2 relative z-10 border border-slate-800">
                     <div 
                        className="h-full bg-violet-600 transition-all duration-500 shadow-[0_0_5px_#7c3aed]" 
                        style={{ width: `${Math.min(100, (res.current / res.max) * 100)}%` }}
                     ></div>
                   </div>
                 )}
               </div>

               {isEditMode && (
                  <button onClick={() => removeResource(idx)} className="text-slate-600 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={14} />
                  </button>
               )}
            </div>
          ))}

          {isEditMode && (
            <Button size="sm" variant="secondary" onClick={addResource} className="w-full border-dashed border-slate-700 text-slate-500 hover:text-white font-serif uppercase tracking-wider">
              {/* [DIALECT] */}
              <Plus size={14} /> {t('btn_add_res', 'Добавить')}
            </Button>
          )}
        </div>
      </div>

      {/* --- IMPORT MODAL --- */}
      {showImportModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-fade-in">
           <div className="relative w-full max-w-lg bg-[#0b0d12] border border-violet-500/30 rounded-lg shadow-[0_0_50px_-10px_rgba(139,92,246,0.2)] overflow-hidden">
                <div className="p-5 border-b border-violet-900/30 flex justify-between items-center bg-[#0b0d12]/80">
                    <h3 className="text-lg font-serif font-bold text-violet-100 uppercase tracking-widest flex items-center gap-2">
                        <FileJson size={18} className="text-violet-500" /> Импорт Сущности
                    </h3>
                    <button onClick={() => setShowImportModal(false)} className="text-slate-500 hover:text-white"><X size={20} /></button>
                </div>

                <div className="p-6 space-y-6">
                    <div className="p-3 bg-violet-900/10 border border-violet-500/20 rounded text-xs text-violet-200 font-serif leading-relaxed">
                        <strong className="text-violet-400 uppercase tracking-wide">Внимание:</strong> Это действие перезапишет все характеристики, инвентарь и способности текущего персонажа. Имя, ID и Владелец будут сохранены.
                    </div>

                    <div className="space-y-4">
                        <div>
                            <label className="block text-[10px] text-slate-500 uppercase font-bold mb-2 tracking-widest">Способ 1: Загрузка файла (.json)</label>
                            <div className="relative">
                                <input 
                                    type="file" 
                                    accept=".json" 
                                    onChange={handleImportFile}
                                    ref={importFileRef}
                                    className="hidden" 
                                    id="import-file-upload"
                                />
                                <label 
                                    htmlFor="import-file-upload" 
                                    className="flex items-center justify-center gap-3 w-full p-4 border-2 border-dashed border-slate-700 rounded-lg text-slate-400 hover:text-white hover:border-violet-500 hover:bg-violet-900/5 cursor-pointer transition-all"
                                >
                                    <Upload size={20} />
                                    <span className="text-xs font-bold uppercase">Выбрать файл</span>
                                </label>
                            </div>
                        </div>

                        <div className="relative flex py-2 items-center">
                            <div className="flex-grow border-t border-slate-800"></div>
                            <span className="flex-shrink-0 mx-4 text-slate-600 text-[10px] uppercase font-bold tracking-widest">ИЛИ</span>
                            <div className="flex-grow border-t border-slate-800"></div>
                        </div>

                        <div>
                            <label className="block text-[10px] text-slate-500 uppercase font-bold mb-2 tracking-widest">Способ 2: Вставка текста (JSON)</label>
                            <textarea 
                                className="w-full h-32 bg-[#020408] border border-slate-700 rounded p-3 text-[10px] font-mono text-emerald-400 focus:border-violet-500 focus:shadow-[0_0_15px_rgba(139,92,246,0.1)] outline-none resize-none custom-scrollbar"
                                placeholder='{ "profile": { "name": "..." }, "stats": { ... } }'
                                value={importText}
                                onChange={(e) => setImportText(e.target.value)}
                            />
                        </div>
                    </div>
                </div>

                <div className="p-4 bg-[#0b0d12]/50 border-t border-violet-900/30 flex justify-end gap-3">
                    <Button variant="secondary" size="sm" onClick={() => setShowImportModal(false)}>Отмена</Button>
                    <Button variant="primary" size="sm" onClick={handleImportText} disabled={!importText.trim()}>
                        <Check size={14} /> Применить
                    </Button>
                </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default SheetHeader;

import React, { useState } from 'react';
import { CharacterData, Faction } from '../types';
import { NPC_VOLUMES } from '../constants';
import { Button } from './Shared';
import { User as UserIcon, Skull, Sun, Moon, Ghost, Plus, ShieldCheck, Sword, Wand2, Crown, Link as LinkIcon, Terminal, Settings, ChevronLeft, ChevronRight, ChevronDown, Calendar } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  characters: CharacterData[];
  onSelect: (id: string) => void;
  onCreate: () => void;
  onOpenSettings?: () => void;
  onOpenTraining?: () => void;
}

const Roster: React.FC<Props> = ({ characters, onSelect, onCreate, onOpenSettings, onOpenTraining }) => {
  const { isAdmin } = useAuth();
  /* [DIALECT] */ const { t, handleLetterClick, handleSlashClick, isInputMode, inputBuffer, isBloodMode, trackTabChange } = useDialect();

  // Lazy initialize state from LocalStorage
  const [activeTab, setActiveTab] = useState<Faction>(() => {
      return (localStorage.getItem('roster_active_tab') as Faction) || Faction.LIGHT;
  });

  const [npcVolume, setNpcVolume] = useState<string>(() => {
      return localStorage.getItem('roster_npc_volume') || NPC_VOLUMES[0];
  });

  // Track tabs for secrets & persistence
  const handleTabChange = (faction: Faction) => {
      setActiveTab(faction);
      trackTabChange(faction);
      localStorage.setItem('roster_active_tab', faction);
  };

  const handleNpcVolumeChange = (vol: string) => {
      setNpcVolume(vol);
      localStorage.setItem('roster_npc_volume', vol);
  };

  // Tab ordering for navigation
  const tabs = [Faction.LIGHT, Faction.DARK, Faction.GRAVEYARD, Faction.NPC];

  const handleNextTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx + 1) % tabs.length]);
  };

  const handlePrevTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx - 1 + tabs.length) % tabs.length]);
  };

  const filtered = characters.filter(c => {
    if (!c.profile) return false;

    const isCompanion = c.profile.faction === Faction.NPC && c.profile.npc_volume === "Спутники и Рабы";
    if (c.meta.master_id && !isCompanion) return false;

    if (c.profile.faction !== activeTab) return false;
    if (activeTab === Faction.NPC && c.profile.npc_volume !== npcVolume) return false;
    return true;
  });

  // --- Theme Logic ---
  const getTheme = (f: Faction) => {
    // Blood Mode Override
    if (isBloodMode) {
        return {
            tab: "text-red-600 drop-shadow-[0_0_8px_rgba(220,38,38,0.8)] animate-pulse",
            border: "border-red-600/60",
            glow: "shadow-[0_0_30px_rgba(220,38,38,0.3)]",
            bg: "bg-red-950/40",
            text: "text-red-200",
            glowColor: "from-red-900/30"
        };
    }

    switch (f) {
      case Faction.LIGHT: 
        return {
          tab: "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]",
          border: "border-amber-500/30",
          glow: "shadow-[0_0_20px_rgba(251,191,36,0.1)]",
          bg: "bg-amber-950/20",
          text: "text-amber-100",
          // BRIGHTER LIGHT AMBIENCE
          glowColor: "from-amber-200/15" 
        };
      case Faction.DARK: 
        return {
          tab: "text-violet-400 drop-shadow-[0_0_8px_rgba(139,92,246,0.5)]",
          border: "border-violet-500/40",
          glow: "shadow-[0_0_20px_rgba(139,92,246,0.2)]",
          bg: "bg-violet-950/30",
          text: "text-violet-100",
          glowColor: "from-violet-900/20"
        };
      case Faction.NPC: 
        return {
          tab: "text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]",
          border: "border-red-500/30",
          glow: "shadow-[0_0_20px_rgba(239,68,68,0.1)]",
          bg: "bg-red-950/20",
          text: "text-red-100",
          glowColor: "from-red-900/20"
        };
      case Faction.GRAVEYARD: 
        return {
          tab: "text-slate-400 drop-shadow-[0_0_8px_rgba(148,163,184,0.5)]",
          border: "border-slate-500/30",
          glow: "shadow-[0_0_10px_rgba(148,163,184,0.1)]",
          bg: "bg-slate-900/20",
          text: "text-slate-300",
          glowColor: "from-slate-800/30"
        };
      default: 
        return { tab: "", border: "border-slate-700", glow: "", bg: "", text: "", glowColor: "from-slate-900/10" };
    }
  };

  const theme = getTheme(activeTab);

  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getLabelKey = (faction: Faction) => 
      faction === Faction.LIGHT ? 'fac_light' : 
      faction === Faction.DARK ? 'fac_dark' :
      faction === Faction.NPC ? 'fac_npc' : 'fac_graveyard';

  const TabButton = ({ faction, icon: Icon }: { faction: Faction, icon: any }) => {
    const isActive = activeTab === faction;
    const labelKey = getLabelKey(faction);
    const localTheme = getTheme(faction);

    return (
      <button
        onClick={() => handleTabChange(faction)}
        className={`relative flex items-center gap-2 px-6 py-3 font-serif font-bold uppercase tracking-widest text-[10px] md:text-xs transition-all whitespace-nowrap flex-shrink-0 ${
          isActive ? `${localTheme.tab} bg-white/5` : "text-slate-600 hover:text-slate-400 hover:bg-white/5"
        }`}
      >
        <Icon size={16} className={isBloodMode ? "text-red-500" : ""} />
        {t(labelKey, faction)}
        {isActive && (
           <div className={`absolute bottom-0 left-0 w-full h-0.5 bg-current shadow-[0_0_10px_currentColor]`}></div>
        )}
      </button>
    );
  };

  const renderInteractiveTitle = (text: string) => {
    return text.split('').map((char, i) => (
      <span 
        key={i} 
        onClick={(e) => {
           e.stopPropagation();
           handleLetterClick(char);
        }}
        className={`transition-colors cursor-pointer select-none active:scale-90 inline-block ${isBloodMode ? 'hover:text-red-500' : 'hover:text-violet-400'}`}
      >
        {char}
      </span>
    ));
  };

  // Main Background Image
  const rosterBg = "https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/character-roster-bg.jpg"; 

  return (
    <div className={`relative flex flex-col w-full h-[calc(100dvh-3rem)] md:h-[100dvh] overflow-hidden bg-transparent transition-all duration-1000 ${isBloodMode ? 'grayscale-[0.2] sepia-[0.3] hue-rotate-[-30deg]' : ''}`}>

      {/* Background Image Layer */}
      <div 
        className="absolute inset-0 bg-cover bg-center opacity-40 z-0 pointer-events-none mix-blend-screen"
        style={{ 
            backgroundImage: `url(${rosterBg})`,
            filter: 'contrast(1.2) brightness(0.6)' 
        }} 
      ></div>

      {/* Dark Overlay Gradient to ensure text legibility */}
      <div className="absolute inset-0 bg-gradient-to-br from-slate-950 via-slate-950/80 to-slate-950 pointer-events-none z-0"></div>

      {/* DYNAMIC ATMOSPHERIC LIGHTING LAYERS */}
      {/* Top ambient glow based on faction */}
      <div className={`fixed top-0 left-0 right-0 h-32 bg-gradient-to-b ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>
      {/* Bottom ambient glow based on faction */}
      <div className={`fixed bottom-0 left-0 right-0 h-32 bg-gradient-to-t ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>

      {/* Scrollable Content Layer */}
      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 md:px-12 pt-4 md:pt-8 pb-32 w-full relative z-10">

            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4 border-b border-white/10 pb-6">
                <div>
                    <h1 className={`text-4xl md:text-6xl font-gothic font-normal text-transparent bg-clip-text bg-gradient-to-r tracking-[0.05em] uppercase flex items-center gap-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)] ${isBloodMode ? 'from-red-300 via-red-100 to-red-500' : 'from-slate-200 via-white to-slate-400'}`}>
                        <div className="flex items-center gap-2">
                            <span className="flex">{renderInteractiveTitle(t('app_title_1', 'Летопись'))}</span> 
                            <span 
                            onClick={(e) => {
                                e.stopPropagation();
                                handleSlashClick();
                            }}
                            className={`px-1 rounded-sm ${isBloodMode ? 'text-red-600' : 'text-violet-500'} cursor-pointer hover:brightness-150 transition-colors select-none active:scale-90 inline-block`}
                            >
                            //
                            </span> 
                            <span className="flex">{renderInteractiveTitle(t('app_title_2', 'Душ'))}</span>
                        </div>
                    </h1>
                    <p className={`font-sans text-sm mt-2 max-w-xl ${isBloodMode ? 'text-red-400/70' : 'text-slate-500'}`}>
                       Реестр сущностей, героев и монстров. Управление характеристиками и судьбами.
                    </p>
                </div>

                {/* Actions Panel */}
                <div className="flex items-center gap-3">
                    {/* Public Training Log Button */}
                    {onOpenTraining && (
                        <Button onClick={onOpenTraining} size="sm" variant="ghost" className="text-slate-400 hover:text-white border border-slate-700/50">
                            <Calendar size={16} /> Журнал Тренировок
                        </Button>
                    )}

                    {/* Admin Only Buttons */}
                    {isAdmin && (
                        <>
                            {onOpenSettings && (
                            <Button onClick={onOpenSettings} size="sm" variant="ghost" className="text-slate-400 hover:text-white border border-slate-700/50">
                                <Settings size={16} />
                            </Button>
                            )}

                            <Button onClick={onCreate} size="sm" className="bg-violet-600/80 border-violet-500 hover:bg-violet-500 text-white shadow-[0_0_15px_rgba(139,92,246,0.3)]">
                            {/* [DIALECT] */}
                            <Plus size={14} /> {t('btn_new', 'Новый')}
                            </Button>
                        </>
                    )}
                </div>
            </div>

            {/* Tabs - Desktop */}
            <div className="hidden md:flex border-b border-white/5 mb-8">
                <TabButton faction={Faction.LIGHT} icon={Sun} />
                <TabButton faction={Faction.DARK} icon={Moon} />
                <TabButton faction={Faction.GRAVEYARD} icon={Skull} />
                <TabButton faction={Faction.NPC} icon={Ghost} />
            </div>

            {/* Tabs - Mobile */}
            <div className="md:hidden flex items-center justify-between border-b border-white/5 pb-4 mb-4">
                <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronLeft size={24} />
                </button>
                <div className={`font-serif font-bold uppercase tracking-widest text-lg ${theme.tab}`}>
                    {t(getLabelKey(activeTab), activeTab)}
                </div>
                <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronRight size={24} />
                </button>
            </div>

            {/* Content Area */}
            <div className="relative min-h-[500px]">

                {activeTab === Faction.NPC && (
                <div className="mb-6">
                    <label className="text-[10px] uppercase font-bold text-slate-500 mb-2 block tracking-widest font-serif">{t('lbl_npc_vol', "Архив Бестиария")}</label>
                    <div className="relative max-w-md">
                        <select 
                        value={npcVolume} 
                        onChange={(e) => handleNpcVolumeChange(e.target.value)}
                        className={`bg-slate-900/50 border text-slate-200 text-sm rounded-lg w-full p-3 outline-none appearance-none font-sans ${isBloodMode ? 'border-red-900/50 focus:border-red-500' : 'border-slate-700 focus:border-violet-500 focus:shadow-[0_0_15px_rgba(139,92,246,0.2)]'}`}
                        >
                        {NPC_VOLUMES.map(v => <option key={v} value={v}>{getVolumeLabel(v)}</option>)}
                        </select>
                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={16} />
                    </div>
                </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
                {filtered.map(char => (
                    <div 
                        key={char.id} 
                        onClick={() => onSelect(char.id)}
                        className={`
                            group relative overflow-hidden rounded-xl cursor-pointer transition-all duration-300
                            bg-slate-900/40 backdrop-blur-md border border-white/5 hover:-translate-y-1
                            ${theme.border} ${theme.glow}
                            content-visibility-auto
                        `}
                    >
                        {/* Card Background Glow */}
                        <div className={`absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 bg-gradient-to-br ${theme.bg} to-transparent pointer-events-none`}></div>

                        <div className="p-4 relative z-10 flex flex-col h-full gap-3">

                            {/* Header: Avatar & Name */}
                            <div className="flex items-start gap-3">
                                <div className="relative shrink-0">
                                    <div className="w-12 h-12 rounded-lg bg-black/50 border border-white/10 overflow-hidden flex items-center justify-center group-hover:border-white/30 transition-colors">
                                        {char.meta.avatar_url ? (
                                            <img src={char.meta.avatar_url} className="w-full h-full object-cover" loading="lazy" decoding="async" />
                                        ) : (
                                            <UserIcon size={20} className="text-slate-600" />
                                        )}
                                    </div>
                                    <div className={`absolute -bottom-1 -right-1 bg-black text-white text-[9px] font-bold px-1.5 rounded border ${isBloodMode ? 'border-red-900' : 'border-white/20'}`}>
                                        {char.profile.level}
                                    </div>
                                </div>

                                <div className="flex-1 min-w-0">
                                    <h3 className={`font-fantasy font-bold text-lg leading-tight truncate ${theme.text} group-hover:text-white transition-colors`}>
                                        {char.profile.name}
                                    </h3>

                                    {/* Subtext: Save Status */}
                                    <div className="flex items-center gap-2 mt-1">
                                        {char.profile.faction === Faction.GRAVEYARD ? (
                                            <span className="text-[10px] text-slate-500 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {char.meta.save_status_reason || t('meta_death_unknown', "Почил")}
                                            </span>
                                        ) : char.meta.save_status ? (
                                            <span className={`text-[10px] uppercase tracking-wide flex items-center gap-1 ${isBloodMode ? 'text-red-400' : 'text-emerald-500/80'}`}>
                                                <ShieldCheck size={10} /> {t('meta_save_ok', 'Сейв есть')}
                                            </span>
                                        ) : (
                                            <span className="text-[10px] text-red-500/80 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {t('meta_save_lost', 'Без сейва')}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Master Link */}
                            {char.meta.master_id && char.profile.faction === Faction.NPC && (
                                <div className="text-[10px] bg-white/5 rounded px-2 py-1 text-violet-300 border border-violet-500/20 flex items-center gap-2">
                                    <LinkIcon size={10} /> 
                                    <span>{t('lbl_linked', 'Связан узами')}</span>
                                </div>
                            )}

                            {/* Stats Grid - Minimalist */}
                            <div className="grid grid-cols-3 gap-1 mt-auto pt-2 border-t border-white/5">
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Sword size={10} className="text-red-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.phys}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Wand2 size={10} className="text-blue-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.magic}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Crown size={10} className="text-purple-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.unique}</span>
                                </div>
                            </div>

                            {/* Equipment Line */}
                            <div className="text-[9px] text-slate-500 truncate h-4">
                                {char.equipment.wearable.filter(w => w.is_equipped).map(w => w.name).join(", ") || ""}
                            </div>
                        </div>
                    </div>
                ))}

                {filtered.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-600 border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/20">
                        <Ghost size={48} className="mb-4 opacity-20"/>
                        <span className="text-sm font-bold uppercase tracking-widest font-serif">{t('msg_empty', 'Лишь ветер гуляет')}</span>
                    </div>
                )}
                </div>
            </div>
      </div>

      {/* [DIALECT] Easter Egg Input Window */}
      {isInputMode && (
          <div className="fixed inset-0 md:absolute md:inset-auto md:bottom-4 md:left-1/2 md:-translate-x-1/2 md:bottom-8 z-[100] animate-fadeIn flex items-center justify-center pointer-events-none p-4">
              <div className="bg-black/95 border border-violet-900 rounded-lg p-4 shadow-[0_0_40px_rgba(139,92,246,0.4)] backdrop-blur-md pointer-events-auto w-full max-w-sm relative">
                <div className="flex items-center gap-2 mb-2 justify-between">
                  <div className="flex items-center gap-2">
                      <Terminal size={14} className="text-violet-500 animate-pulse"/>
                      <span className="text-[10px] font-mono text-violet-300 uppercase tracking-widest">Input Sequence</span>
                  </div>
                </div>
                <div className="bg-slate-950 border border-slate-800 rounded p-3 min-h-[3rem] flex items-center justify-center overflow-hidden">
                    <span className="font-serif text-sm md:text-base text-violet-400 tracking-[0.1em] md:tracking-[0.2em] uppercase drop-shadow-[0_0_5px_rgba(167,139,250,0.8)] break-all text-center">
                      {inputBuffer || <span className="opacity-20">_ _ _ _ _ _</span>}
                    </span>
                </div>
                <div className="text-center mt-2">
                    <span className="text-[9px] text-slate-600 uppercase font-bold tracking-widest">Tap title letters & slashes</span>
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Roster;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_CHARACTER, DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from './constants';
import { CharacterData, InjuryDefinition, TimeUnit, Faction } from './types';
import * as SupabaseService from './utils/supabaseService';
import Roster from './components/Roster';
import SheetHeader from './components/SheetHeader';
import TabEquipment from './components/TabEquipment';
import TabAbilities from './components/TabAbilities';
import TabPassives from './components/TabPassives';
import TabDebuffs from './components/TabDebuffs';
import TabUnits from './components/TabUnits';
import TabMedCard from './components/TabMedCard';
import GlobalSettingsModal from './components/GlobalSettingsModal';
import { TagHintsModal } from './components/TagHintsModal';
import { Button } from './components/Shared';
import { Save, ChevronLeft, ChevronRight, Edit3, Trash2, RotateCcw, Settings, BookOpen, Calculator, ScrollText, Loader2, Tag } from 'lucide-react';
import { DialectProvider, useDialect } from './dialect_module/DialectContext';
import { UIProvider, useUI } from './context/UIContext';
import { TrainingPage } from './pages/TrainingPage';
import { useAuth } from '../../context/AuthContext';

export type DisplayMode = 'lore' | 'mech';

interface RosterModuleProps {
  isAdmin?: boolean;
}

const RosterContent: React.FC<RosterModuleProps> = ({ isAdmin = false }) => {
  const { toggleDialect, isOldSlavonic, isDialectUnlocked, t } = useDialect();
  const { showAlert, showConfirm } = useUI();
  const { user } = useAuth();

  const [view, setView] = useState<'roster' | 'sheet' | 'training'>('roster');
  const [characters, setCharacters] = useState<CharacterData[]>([]);
  const [rosterList, setRosterList] = useState<CharacterData[]>([]);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [charStack, setCharStack] = useState<string[]>([]);

  const [displayMode, setDisplayMode] = useState<DisplayMode>('lore');
  const [isEditMode, setIsEditMode] = useState(false);
  const [activeTab, setActiveTab] = useState<'equipment' | 'abilities' | 'passives' | 'debuffs' | 'units' | 'medcard'>('equipment');

  const [triggersMap, setTriggersMap] = useState<Record<string, string>>({});
  const [injuryDefinitions, setInjuryDefinitions] = useState<InjuryDefinition[]>(DEFAULT_INJURIES);
  const [timeUnits, setTimeUnits] = useState<TimeUnit[]>(DEFAULT_TIME_UNITS);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isTagHintsOpen, setIsTagHintsOpen] = useState(false);

  const SHEET_TABS = useMemo(() => [
    { id: 'equipment', label: t('tab_eq', 'Снаряжение') },
    { id: 'abilities', label: t('tab_ab', 'Способности') },
    { id: 'passives', label: t('tab_ps', 'Пассивки') },
    { id: 'debuffs', label: t('tab_db', 'Дебаффы') },
    { id: 'units', label: t('tab_un', 'Юниты') },
    { id: 'medcard', label: t('tab_mc', 'Мед.Карта') },
  ], [t]);

  const initRef = useRef(false);

  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;
    const init = async () => {
      setIsLoadingData(true);
      try {
        const [chars, trigs, inj, units] = await Promise.all([
          SupabaseService.getAllCharacters(),
          SupabaseService.getGlobalTriggers(),
          SupabaseService.getInjuries(),
          SupabaseService.getTimeUnits()
        ]);
        setCharacters(chars);
        setRosterList(chars);
        setTriggersMap(trigs);
        setInjuryDefinitions(inj);
        setTimeUnits(units);
      } catch (e) { console.error("Failed to init app", e); } finally { setIsLoadingData(false); }
    };
    init();
  }, []);

  const handleCreate = async () => {
    const newChar: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
    newChar.id = crypto.randomUUID();
    newChar.profile.name = "Новая Душа";
    if (user && !isAdmin) newChar.meta.uid = user.id;

    // Inject basic actions right away for new character, hidden by default
    const basicActions = await SupabaseService.getBasicActions();
    if (basicActions && basicActions.length > 0) {
        newChar.ability_groups = [{
            name: "Базовые Действия",
            tags: [],
            abilities: basicActions,
            is_hidden: true
        }];
    }

    const updated = [...characters, newChar];
    setCharacters(updated);
    setRosterList(updated);

    try {
      await SupabaseService.saveCharacter(newChar, isAdmin);
      setActiveCharId(newChar.id);
      setCharStack([newChar.id]);
      setView('sheet');
      setIsEditMode(true);
    } catch (e) {
      showAlert("Ошибка создания: " + e, "Сбой базы данных");
      const reverted = characters.filter(c => c.id !== newChar.id);
      setCharacters(reverted);
      setRosterList(reverted);
    }
  };

  const handleSelect = (id: string) => {
    setActiveCharId(id);
    setCharStack([id]);
    setView('sheet');
    setIsEditMode(false);
    window.scrollTo(0,0);
  };

  const handleNavigateToUnit = (unitId: string) => {
    setCharStack(prev => [...prev, unitId]);
    setActiveCharId(unitId);
    window.scrollTo(0,0);
  };

  const handleBack = () => {
    if (charStack.length > 1) {
      const newStack = [...charStack];
      newStack.pop();
      setCharStack(newStack);
      setActiveCharId(newStack[newStack.length - 1]);
    } else {
      setView('roster');
      setActiveCharId(null);
      setCharStack([]);
    }
  };

  const handleNextTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const nextId = SHEET_TABS[(idx + 1) % SHEET_TABS.length].id;
      setActiveTab(nextId as any);
  };

  const handlePrevTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const prevId = SHEET_TABS[(idx - 1 + SHEET_TABS.length) % SHEET_TABS.length].id;
      setActiveTab(prevId as any);
  };

  const activeChar = characters.find(c => c.id === activeCharId);
  const isOwner = user && activeChar && activeChar.meta.uid === user.id;
  const canEdit = isAdmin || isOwner;

  const updateActiveChar = (updates: Partial<CharacterData>) => {
    if (!activeChar) return;
    const updated = { ...activeChar, ...updates };
    setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
  };

  const handleSave = async () => {
    if (!activeChar) return;
    try {
      await SupabaseService.saveCharacter(activeChar, isAdmin);
      setIsEditMode(false);
      setRosterList(characters);
    } catch (e) { showAlert("Ошибка сохранения: " + e, "Ошибка"); }
  };

  const handleInstantUpdate = async (eq: CharacterData['equipment']) => {
      if (!activeChar) return;
      const updated = { ...activeChar, equipment: eq };
      const newChars = characters.map(c => c.id === activeChar.id ? updated : c);
      setCharacters(newChars);
      await SupabaseService.saveCharacter(updated, isAdmin);
      setRosterList(newChars);
  };

  const handleDelete = async (idToDelete?: string) => {
    const targetId = idToDelete || activeChar?.id;
    if (!targetId) return;
    showConfirm("Вы уверены? Это действие необратимо уничтожит сущность.", async () => {
        try {
          await SupabaseService.deleteCharacter(targetId);
          const updated = characters.filter(c => c.id !== targetId);
          setCharacters(updated);
          setRosterList(updated);
          if (targetId === activeCharId) handleBack();
        } catch (e) { showAlert("Ошибка удаления: " + e, "Ошибка"); }
    }, "Уничтожение");
  };

  const createUnit = async () => {
      if (!activeChar) return;
      const unit: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
      unit.id = crypto.randomUUID();
      unit.profile.name = "Новый Юнит";
      unit.meta.master_id = activeChar.id;
      unit.meta.uid = activeChar.meta.uid; 

      const basicActions = await SupabaseService.getBasicActions();
      if (basicActions && basicActions.length > 0) {
          unit.ability_groups = [{
              name: "Базовые Действия",
              tags: [],
              abilities: basicActions,
              is_hidden: true // Hidden by default
          }];
      }

      try {
        await SupabaseService.saveCharacter(unit, isAdmin);
        const updated = [...characters, unit];
        setCharacters(updated);
        setRosterList(updated);
        handleNavigateToUnit(unit.id);
        setIsEditMode(true);
      } catch (e) { showAlert("Cannot create unit: " + e, "Ошибка"); }
  };

  const getSheetBackground = (faction: Faction) => {
      if (faction === Faction.LIGHT) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Light_bg.jpg';
      if (faction === Faction.DARK) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Dark_bg.jpg';
      if (faction === Faction.NPC) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Bestiary_bg.jpg';
      if (faction === Faction.GRAVEYARD) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/graveyard_bg.jpg';
      return null;
  };

  if (isLoadingData) {
    return (
      <div className="min-h-full flex items-center justify-center text-violet-500">
        <Loader2 size={48} className="animate-spin" />
      </div>
    );
  }

  if (view === 'training') return <TrainingPage characters={characters} onBack={() => setView('roster')} />;

  return (
    <div className="font-sans text-slate-300 selection:bg-violet-900/40 selection:text-white h-full relative">
      {view === 'sheet' && activeChar && (
          <>
            {getSheetBackground(activeChar.profile.faction) ? (
                <div className="fixed inset-0 z-0 overflow-hidden">
                    <div className="absolute inset-0 bg-cover bg-center bg-no-repeat bg-fixed blur-[5px] scale-105" style={{ backgroundImage: `url(${getSheetBackground(activeChar.profile.faction)})` }}></div>
                    <div className="absolute inset-0 bg-black/50"></div>
                </div>
            ) : ( <div className="fixed inset-0 bg-gradient-to-b from-slate-900 to-black z-0 pointer-events-none"></div> )}
          </>
      )}

      {view === 'roster' && (
        <>
          <Roster characters={rosterList} onSelect={handleSelect} onCreate={handleCreate} onImport={async () => {}} onOpenSettings={() => setIsSettingsOpen(true)} onOpenTraining={() => setView('training')} />
          {isSettingsOpen && isAdmin && (
             <GlobalSettingsModal onClose={() => setIsSettingsOpen(false)} triggersMap={triggersMap} onSaveTriggers={async (t) => { await SupabaseService.saveGlobalTriggers(t); setTriggersMap(t); }} injuryDefinitions={injuryDefinitions} onSaveInjuries={async (inj) => { await SupabaseService.saveInjuries(inj); setInjuryDefinitions(inj); }} timeUnits={timeUnits} onSaveTimeUnits={async (units) => { await SupabaseService.saveTimeUnits(units); setTimeUnits(units); }} />
          )}
        </>
      )}

      {view === 'sheet' && activeChar && (
        <div className="relative z-10 max-w-5xl mx-auto p-4 md:p-6 animate-fade-in pb-32">
          <div className="flex items-center justify-between mb-6 bg-[#020617]/80 backdrop-blur-md p-3 border-b border-violet-900/30 sticky top-12 min-[1150px]:top-0 z-50 shadow-lg rune-clip-r">
            <div className="flex items-center gap-2">
               <Button variant="secondary" size="sm" onClick={handleBack} className="bg-[#0f172a] border-slate-700 hover:bg-slate-800 text-slate-200 hover:text-white shadow-md z-10 font-serif tracking-wide">
                 <ChevronLeft size={18} /> {t('act_back', "Назад")}
               </Button>
               {charStack.length > 1 && ( <span className="text-xs text-slate-500 font-serif uppercase tracking-wider hidden md:inline ml-2 border-l border-slate-700 pl-3"> {t('lbl_depth', 'Глубина')}: {charStack.length} </span> )}
            </div>
            <div className="flex items-center gap-2">
               {isDialectUnlocked && ( <button onClick={toggleDialect} className={`p-2 rounded border transition-all ${isOldSlavonic ? 'bg-amber-900/20 text-amber-500 border-amber-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`} title="Old Slavonic Dialect"> <ScrollText size={18} /> </button> )}
               <div className="h-6 w-px bg-slate-800 mx-1"></div>
               <div className="flex bg-[#0f172a] p-1 rounded-sm border border-slate-800">
                  <button onClick={() => setDisplayMode('lore')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'lore' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Lore Mode"> <BookOpen size={16} /> </button>
                  <button onClick={() => setDisplayMode('mech')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'mech' ? 'bg-violet-900/50 text-violet-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Mechanic Mode"> <Calculator size={16} /> </button>
               </div>

               {/* Tag Hints - Visible to All */}
               <button onClick={() => setIsTagHintsOpen(true)} className="p-2 text-slate-500 hover:text-violet-300 transition-colors ml-1" title="Справочник Тегов"> <Tag size={18} /> </button>

               {canEdit && (
                 <>
                   <div className="h-6 w-px bg-slate-800 mx-1"></div>
                   {isEditMode ? (
                     <>
                        {isAdmin && ( <Button variant="danger" size="sm" onClick={() => handleDelete(activeChar.id)} title="Delete"> <Trash2 size={16} /> </Button> )}
                        <Button variant="secondary" size="sm" onClick={() => { showConfirm("Отменить несохраненные изменения?", () => { const original = rosterList.find(c => c.id === activeChar.id); if (original) updateActiveChar(original); setIsEditMode(false); }); }}> <RotateCcw size={16} /> </Button>
                        <Button className="bg-emerald-900/80 hover:bg-emerald-800 border-emerald-500/50" size="sm" onClick={handleSave}> <Save size={16} /> {t('act_save', "Сохранить")} </Button>
                     </>
                   ) : ( <Button variant="secondary" size="sm" onClick={() => setIsEditMode(true)}> <Edit3 size={16} /> {t('act_edit', "Ред.")} </Button> )}
                 </>
               )}
            </div>
          </div>

          <SheetHeader character={activeChar} isEditMode={isEditMode} onChange={updateActiveChar} displayMode={displayMode} setDisplayMode={setDisplayMode} characters={characters} onNavigate={handleNavigateToUnit} onDelete={isAdmin ? handleDelete : undefined} injuryDefinitions={injuryDefinitions} />

          <div className="hidden md:flex sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 px-0 md:px-0">
             <div className="flex overflow-x-auto no-scrollbar gap-1 pb-1">
                {SHEET_TABS.map(tab => (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 text-sm font-serif font-bold uppercase tracking-widest transition-all whitespace-nowrap relative group flex-shrink-0 ${ activeTab === tab.id ? 'text-violet-300' : 'text-slate-600 hover:text-slate-300' }`} >
                    {tab.label}
                    {activeTab === tab.id && ( <div className="absolute bottom-0 left-0 w-full h-0.5 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div> )}
                  </button>
                ))}
             </div>
          </div>

          <div className="md:hidden sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 -mx-4 px-4 py-2 flex items-center justify-between">
              <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronLeft size={24} /> </button>
              <div className="font-serif font-bold uppercase tracking-widest text-violet-300 text-sm"> {SHEET_TABS.find(t => t.id === activeTab)?.label} </div>
              <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronRight size={24} /> </button>
          </div>

          <div>
            {activeTab === 'equipment' && ( <TabEquipment character={activeChar} isEditMode={isEditMode} onChange={(eq) => updateActiveChar({ equipment: eq })} displayMode={displayMode} onInstantUpdate={(eq) => handleInstantUpdate(eq)} /> )}
            {activeTab === 'abilities' && ( <TabAbilities character={activeChar} isEditMode={isEditMode} onChange={(groups) => updateActiveChar({ ability_groups: groups })} displayMode={displayMode} timeUnits={timeUnits} /> )}
            {activeTab === 'passives' && ( <TabPassives character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} /> )}
            {activeTab === 'debuffs' && ( <TabDebuffs character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} /> )}
            {activeTab === 'units' && ( <TabUnits master={activeChar} units={characters} onCreateUnit={createUnit} onNavigateToUnit={handleNavigateToUnit} isEditMode={isEditMode} /> )}
            {activeTab === 'medcard' && ( <TabMedCard character={activeChar} isEditMode={isEditMode} onChange={(mc) => updateActiveChar({ medcard: mc })} injuryDefinitions={injuryDefinitions} /> )}
          </div>
        </div>
      )}

      {isTagHintsOpen && ( <TagHintsModal isOpen={isTagHintsOpen} onClose={() => setIsTagHintsOpen(false)} isAdmin={isAdmin} /> )}
    </div>
  );
};

