  };

  const handlePrevTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const prevId = SHEET_TABS[(idx - 1 + SHEET_TABS.length) % SHEET_TABS.length].id;
      setActiveTab(prevId as any);
  };

  const activeChar = characters.find(c => c.id === activeCharId);
  const isOwner = user && activeChar && activeChar.meta.uid === user.id;
  const canEdit = isAdmin || isOwner;

  const updateActiveChar = (updates: Partial<CharacterData>) => {
    if (!activeChar) return;
    const updated = { ...activeChar, ...updates };
    setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
  };

  const handleSave = async () => {
    if (!activeChar) return;
    try {
      await SupabaseService.saveCharacter(activeChar, isAdmin);
      setIsEditMode(false);
      setRosterList(characters);
    } catch (e) { showAlert("Ошибка сохранения: " + e, "Ошибка"); }
  };

  const handleInstantUpdate = async (eq: CharacterData['equipment']) => {
      if (!activeChar) return;
      const updated = { ...activeChar, equipment: eq };
      const newChars = characters.map(c => c.id === activeChar.id ? updated : c);
      setCharacters(newChars);
      await SupabaseService.saveCharacter(updated, isAdmin);
      setRosterList(newChars);
  };

  const handleDelete = async (idToDelete?: string) => {
    const targetId = idToDelete || activeChar?.id;
    if (!targetId) return;
    showConfirm("Вы уверены? Это действие необратимо уничтожит сущность.", async () => {
        try {
          await SupabaseService.deleteCharacter(targetId);
          const updated = characters.filter(c => c.id !== targetId);
          setCharacters(updated);
          setRosterList(updated);
          if (targetId === activeCharId) handleBack();
        } catch (e) { showAlert("Ошибка удаления: " + e, "Ошибка"); }
    }, "Уничтожение");
  };

  const createUnit = async () => {
      if (!activeChar) return;
      const unit: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
      unit.id = crypto.randomUUID();
      unit.profile.name = "Новый Юнит";
      unit.meta.master_id = activeChar.id;
      unit.meta.uid = activeChar.meta.uid; 

      const basicActions = await SupabaseService.getBasicActions();
      if (basicActions && basicActions.length > 0) {
          unit.ability_groups = [{
              name: "Базовые Действия",
              tags: [],
              abilities: basicActions,
              is_hidden: true // Hidden by default
          }];
      }

      try {
        await SupabaseService.saveCharacter(unit, isAdmin);
        const updated = [...characters, unit];
        setCharacters(updated);
        setRosterList(updated);
        handleNavigateToUnit(unit.id);
        setIsEditMode(true);
      } catch (e) { showAlert("Cannot create unit: " + e, "Ошибка"); }
  };

  const getSheetBackground = (faction: Faction) => {
      if (faction === Faction.LIGHT) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Light_bg.jpg';
      if (faction === Faction.DARK) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Dark_bg.jpg';
      if (faction === Faction.NPC) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Bestiary_bg.jpg';
      if (faction === Faction.GRAVEYARD) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/graveyard_bg.jpg';
      return null;
  };

  if (isLoadingData) {
    return (
      <div className="min-h-full flex items-center justify-center text-violet-500">
        <Loader2 size={48} className="animate-spin" />
      </div>
    );
  }

  if (view === 'training') return <TrainingPage characters={characters} onBack={() => setView('roster')} />;

  return (
    <div className="font-sans text-slate-300 selection:bg-violet-900/40 selection:text-white h-full relative">
      {view === 'sheet' && activeChar && (
          <>
            {getSheetBackground(activeChar.profile.faction) ? (
                <div className="fixed inset-0 z-0 overflow-hidden">
                    <div className="absolute inset-0 bg-cover bg-center bg-no-repeat bg-fixed blur-[5px] scale-105" style={{ backgroundImage: `url(${getSheetBackground(activeChar.profile.faction)})` }}></div>
                    <div className="absolute inset-0 bg-black/50"></div>
                </div>
            ) : ( <div className="fixed inset-0 bg-gradient-to-b from-slate-900 to-black z-0 pointer-events-none"></div> )}
          </>
      )}

      {view === 'roster' && (
        <>
          <Roster characters={rosterList} onSelect={handleSelect} onCreate={handleCreate} onOpenSettings={() => setIsSettingsOpen(true)} onOpenTraining={() => setView('training')} />
          {isSettingsOpen && isAdmin && (
             <GlobalSettingsModal onClose={() => setIsSettingsOpen(false)} triggersMap={triggersMap} onSaveTriggers={async (t) => { await SupabaseService.saveGlobalTriggers(t); setTriggersMap(t); }} injuryDefinitions={injuryDefinitions} onSaveInjuries={async (inj) => { await SupabaseService.saveInjuries(inj); setInjuryDefinitions(inj); }} timeUnits={timeUnits} onSaveTimeUnits={async (units) => { await SupabaseService.saveTimeUnits(units); setTimeUnits(units); }} />
          )}
        </>
      )}

      {view === 'sheet' && activeChar && (
        <div className="relative z-10 max-w-5xl mx-auto p-4 md:p-6 animate-fade-in pb-32">
          <div className="flex items-center justify-between mb-6 bg-[#020617]/80 backdrop-blur-md p-3 border-b border-violet-900/30 sticky top-12 min-[1150px]:top-0 z-50 shadow-lg rune-clip-r">
            <div className="flex items-center gap-2">
               <Button variant="secondary" size="sm" onClick={handleBack} className="bg-[#0f172a] border-slate-700 hover:bg-slate-800 text-slate-200 hover:text-white shadow-md z-10 font-serif tracking-wide">
                 <ChevronLeft size={18} /> {t('act_back', "Назад")}
               </Button>
               {charStack.length > 1 && ( <span className="text-xs text-slate-500 font-serif uppercase tracking-wider hidden md:inline ml-2 border-l border-slate-700 pl-3"> {t('lbl_depth', 'Глубина')}: {charStack.length} </span> )}
            </div>
            <div className="flex items-center gap-2">
               {isDialectUnlocked && ( <button onClick={toggleDialect} className={`p-2 rounded border transition-all ${isOldSlavonic ? 'bg-amber-900/20 text-amber-500 border-amber-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`} title="Old Slavonic Dialect"> <ScrollText size={18} /> </button> )}
               <div className="h-6 w-px bg-slate-800 mx-1"></div>
               <div className="flex bg-[#0f172a] p-1 rounded-sm border border-slate-800">
                  <button onClick={() => setDisplayMode('lore')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'lore' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Lore Mode"> <BookOpen size={16} /> </button>
                  <button onClick={() => setDisplayMode('mech')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'mech' ? 'bg-violet-900/50 text-violet-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Mechanic Mode"> <Calculator size={16} /> </button>
               </div>

               {/* Tag Hints - Visible to All */}
               <button onClick={() => setIsTagHintsOpen(true)} className="p-2 text-slate-500 hover:text-violet-300 transition-colors ml-1" title="Справочник Тегов"> <Tag size={18} /> </button>

               {canEdit && (
                 <>
                   <div className="h-6 w-px bg-slate-800 mx-1"></div>
                   {isEditMode ? (
                     <>
                        {isAdmin && ( <Button variant="danger" size="sm" onClick={() => handleDelete(activeChar.id)} title="Delete"> <Trash2 size={16} /> </Button> )}
                        <Button variant="secondary" size="sm" onClick={() => { showConfirm("Отменить несохраненные изменения?", () => { const original = rosterList.find(c => c.id === activeChar.id); if (original) updateActiveChar(original); setIsEditMode(false); }); }}> <RotateCcw size={16} /> </Button>
                        <Button className="bg-emerald-900/80 hover:bg-emerald-800 border-emerald-500/50" size="sm" onClick={handleSave}> <Save size={16} /> {t('act_save', "Сохранить")} </Button>
                     </>
                   ) : ( <Button variant="secondary" size="sm" onClick={() => setIsEditMode(true)}> <Edit3 size={16} /> {t('act_edit', "Ред.")} </Button> )}
                 </>
               )}
            </div>
          </div>

          <SheetHeader character={activeChar} isEditMode={isEditMode} onChange={updateActiveChar} displayMode={displayMode} setDisplayMode={setDisplayMode} characters={characters} onNavigate={handleNavigateToUnit} onDelete={isAdmin ? handleDelete : undefined} injuryDefinitions={injuryDefinitions} />

          <div className="hidden md:flex sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 px-0 md:px-0">
             <div className="flex overflow-x-auto no-scrollbar gap-1 pb-1">
                {SHEET_TABS.map(tab => (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 text-sm font-serif font-bold uppercase tracking-widest transition-all whitespace-nowrap relative group flex-shrink-0 ${ activeTab === tab.id ? 'text-violet-300' : 'text-slate-600 hover:text-slate-300' }`} >
                    {tab.label}
                    {activeTab === tab.id && ( <div className="absolute bottom-0 left-0 w-full h-0.5 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div> )}
                  </button>
                ))}
             </div>
          </div>

          <div className="md:hidden sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 -mx-4 px-4 py-2 flex items-center justify-between">
              <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronLeft size={24} /> </button>
              <div className="font-serif font-bold uppercase tracking-widest text-violet-300 text-sm"> {SHEET_TABS.find(t => t.id === activeTab)?.label} </div>
              <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronRight size={24} /> </button>
          </div>

          <div>
            {activeTab === 'equipment' && ( <TabEquipment character={activeChar} isEditMode={isEditMode} onChange={(eq) => updateActiveChar({ equipment: eq })} displayMode={displayMode} onInstantUpdate={(eq) => handleInstantUpdate(eq)} /> )}
            {activeTab === 'abilities' && ( <TabAbilities character={activeChar} isEditMode={isEditMode} onChange={(groups) => updateActiveChar({ ability_groups: groups })} displayMode={displayMode} timeUnits={timeUnits} onCharacterUpdate={updateActiveChar} /> )}
            {activeTab === 'passives' && ( <TabPassives character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} onCharacterUpdate={updateActiveChar} /> )}
            {activeTab === 'debuffs' && ( <TabDebuffs character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} onCharacterUpdate={updateActiveChar} /> )}
            {activeTab === 'units' && ( <TabUnits master={activeChar} units={characters} onCreateUnit={createUnit} onNavigateToUnit={handleNavigateToUnit} isEditMode={isEditMode} /> )}
            {activeTab === 'medcard' && ( <TabMedCard character={activeChar} isEditMode={isEditMode} onChange={(mc) => updateActiveChar({ medcard: mc })} injuryDefinitions={injuryDefinitions} /> )}
          </div>
        </div>
      )}

      {isTagHintsOpen && ( <TagHintsModal isOpen={isTagHintsOpen} onClose={() => setIsTagHintsOpen(false)} isAdmin={isAdmin} /> )}
    </div>
  );
};

export const RosterAdminContainer: React.FC = () => { return null; };
const RosterModule: React.FC<RosterModuleProps> = (props) => ( <DialectProvider> <UIProvider> <RosterContent {...props} /> </UIProvider> </DialectProvider> );
export default RosterModule;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus, Ability } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, ChevronDown, ChevronRight, Eye, EyeOff, Hash, Check, X, Lock, Unlock, Sparkles, FolderInput } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (groups: CharacterData['ability_groups']) => void;
  timeUnits: TimeUnit[];
  onCharacterUpdate?: (u: Partial<CharacterData>) => void;
}

const TabAbilities: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, timeUnits, onCharacterUpdate }) => {
  const { ability_groups } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (idx: number, field: string, val: any) => {
    const next = [...ability_groups];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...ability_groups, { name: "Новая Школа", tags: [], abilities: [], is_hidden: false }]);

  const removeGroup = (idx: number) => {
     const next = ability_groups.filter((_, i) => i !== idx);
     onChange(next);

     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
     setDeleteConfirmGroupIdx(null);
  };

  const addAbility = (gIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...(group.abilities || [])];

    group.abilities.push({ 
      name: "Новый Навык", bonuses: [], tags: [], desc_lore: "", desc_mech: "",
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", limit: 0, limit_unit: "", is_blocked: false
    });

    next[gIdx] = group;
    onChange(next);
  };

  const updateAbility = (gIdx: number, aIdx: number, field: string, val: any) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities[aIdx] = { ...group.abilities[aIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeAbility = (gIdx: number, aIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities.splice(aIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const moveAbility = (fromGIdx: number, targetValue: string, aIdx: number) => {
      // Internal move
      if (targetValue.startsWith('group_')) {
          const toGIdx = parseInt(targetValue.split('_')[1]);
          const next = [...ability_groups];
          const sourceGroup = { ...next[fromGIdx] };
          const targetGroup = { ...next[toGIdx] };
          const ability = sourceGroup.abilities[aIdx];

          sourceGroup.abilities = sourceGroup.abilities.filter((_, i) => i !== aIdx);
          targetGroup.abilities = [...targetGroup.abilities, ability];

          next[fromGIdx] = sourceGroup;
          next[toGIdx] = targetGroup;
          onChange(next);
      } 
      // Cross-move to Passive
      else if (targetValue.startsWith('passive_') && onCharacterUpdate) {
          const toPIdx = parseInt(targetValue.split('_')[1]);
          const ability = ability_groups[fromGIdx].abilities[aIdx];

          // Convert Ability to Passive
          const newPassive = {
              name: ability.name,
              bonuses: ability.bonuses,
              tags: ability.tags,
              desc_lore: ability.desc_lore,
              desc_mech: ability.desc_mech,
              cd: ability.cd,
              cd_unit: ability.cd_unit,
              dur: ability.dur,
              dur_unit: ability.dur_unit,
              is_blocked: ability.is_blocked,
              trigger: "Always",
              is_flaw: false // Defaults to not flaw, will be adjusted by target group type usually
          };

          // 1. Remove from abilities
          const nextAbilities = [...ability_groups];
          nextAbilities[fromGIdx] = {
              ...nextAbilities[fromGIdx],
              abilities: nextAbilities[fromGIdx].abilities.filter((_, i) => i !== aIdx)
          };

          // 2. Add to passives
          const nextPassives = [...character.passives];
          // Ensure target group exists
          if (nextPassives[toPIdx]) {
              const targetGroup = { ...nextPassives[toPIdx] };
              // inherit is_flaw from group if possible, or keep default
              newPassive.is_flaw = !!targetGroup.is_flaw_group;
              targetGroup.items = [...targetGroup.items, newPassive];
              nextPassives[toPIdx] = targetGroup;
          }

          onCharacterUpdate({
              ability_groups: nextAbilities,
              passives: nextPassives
          });
      }
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
      if (isEditMode) return [];
      const data = ability_groups.map((g, i) => {
        const name = g.name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.abilities ? g.abilities.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [ability_groups, isEditMode]);

  const bonusData = useMemo(() => {
      if (isEditMode) return [];
      let phys = 0, magic = 0, unique = 0;
      ability_groups.forEach(g => {
        if (Array.isArray(g.abilities)) {
          g.abilities.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.max(0, v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [ability_groups, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} color="#06b6d4" t={t} />}

      {ability_groups.map((group, gIdx) => {
        const isBasic = group.name === "Базовые Действия";
        if (!isEditMode && (group.abilities.length === 0 || group.is_hidden)) return null;

        const isCollapsed = collapsedGroups[gIdx];
        const isHidden = group.is_hidden;
        const abilitiesWithIndex = group.abilities.map((ab, i) => ({ ...ab, originalIndex: i }));
        const sortedAbilities = abilitiesWithIndex.sort((a, b) => {
            if (a.is_blocked === b.is_blocked) return 0;
            return a.is_blocked ? 1 : -1;
        });

        return (
          <div key={gIdx} className={`space-y-4 transition-all ${isBasic ? 'border-l-4 border-emerald-500' : ''} ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className={`flex items-center gap-4 border-b border-gray-800 pb-2 ${isBasic ? 'bg-emerald-950/20' : 'bg-slate-900/90'} p-3 rounded-t-lg backdrop-blur-sm shadow-md`}>
               <button onClick={() => toggleGroup(gIdx)} className={`p-1 transition-colors ${isBasic ? 'text-emerald-400 hover:text-emerald-300' : 'text-gray-500 hover:text-cyan-400'}`}>
                  {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
               </button>
               <div className="flex-1 flex items-center gap-2">
                 {isBasic && <Sparkles size={18} className="text-emerald-500 shrink-0" />}
                 <StyledInput 
                   isEditMode={isEditMode && !isBasic} 
                   value={group.name} 
                   onChange={e => updateGroup(gIdx, 'name', e.target.value)} 
                   className={`text-xl font-bold uppercase tracking-widest bg-transparent border-none p-0 ${isBasic ? 'text-emerald-500' : 'text-cyan-500'}`} 
                 />
                 {isBasic && isEditMode && <span className="text-[9px] uppercase font-bold text-emerald-900 bg-emerald-500/20 px-2 py-0.5 rounded">Система</span>}
                 {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
               </div>

               {!isCollapsed && <TagInput isEditMode={isEditMode && !isBasic} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}

               {isEditMode && !isBasic && (
                 <>
                   <button 
                     onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} 
                     className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-cyan-600 hover:text-cyan-400'}`}
                     title={isHidden ? "Показать в листе" : "Скрыть из листа"}
                   >
                     {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                   </button>

                   {deleteConfirmGroupIdx === gIdx ? (
                     <div className="flex items-center gap-1">
                        <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                        <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                     </div>
                   ) : (
                     <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                   )}
                 </>
               )}
             </div>

             {!isCollapsed && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                 {sortedAbilities.map((abilityWrapper) => {
                   const { originalIndex, ...ability } = abilityWrapper;
                   const isBlocked = ability.is_blocked;

                   return (
                   <Card key={originalIndex} className={`hover:border-gray-700 transition-colors bg-[#0b0d10] border-gray-800 ${isBlocked ? 'opacity-60 grayscale-[0.8] hover:opacity-100 hover:grayscale-0' : ''} ${isBasic ? 'border-l-2 border-emerald-900/50' : ''}`}>
                      <div className="flex justify-between items-start mb-2 overflow-hidden">
                         <div className="flex-1 min-w-0 mr-2" title={ability.name}>
                           <StyledInput 
                              isEditMode={isEditMode && !isBlocked && !isBasic} 
                              disabled={isBlocked || isBasic}
                              value={ability.name} 
                              onChange={e => updateAbility(gIdx, originalIndex, 'name', e.target.value)} 
                              className={`font-bold text-lg truncate block w-full ${isBlocked ? 'text-slate-500' : (isBasic ? 'text-emerald-300' : '')}`} 
                              placeholder={t('ph_ability_name', "Название навыка")}
                           />
                         </div>
                         {isEditMode && !isBasic && (
                             <div className="flex items-center gap-1 flex-shrink-0">
                                <div className="relative group">
                                    <button className="p-1 rounded text-slate-600 hover:text-cyan-400 transition-colors" title="Перенести...">
                                        <FolderInput size={14} />
                                    </button>
                                    <select 
                                        className="absolute inset-0 opacity-0 cursor-pointer"
                                        value={"default"}
                                        onChange={(e) => moveAbility(gIdx, e.target.value, originalIndex)}
                                    >
                                        <option value="default" disabled>Перенести в...</option>
                                        <optgroup label="Школы">
                                            {ability_groups.map((grp, i) => (
                                                <option key={"g"+i} value={"group_"+i} disabled={i === gIdx}>{grp.name}</option>
                                            ))}
                                        </optgroup>
                                        {character.passives && character.passives.length > 0 && (
                                            <optgroup label="Пассивки/Дебаффы">
                                                {character.passives.map((grp, i) => (
                                                    <option key={"p"+i} value={"passive_"+i}>{grp.group_name || 'Группа ' + (i+1)}</option>
                                                ))}
                                            </optgroup>
                                        )}
                                    </select>
                                </div>
                                <button 
                                    onClick={() => updateAbility(gIdx, originalIndex, 'is_blocked', !isBlocked)}
                                    className={`p-1 rounded transition-colors ${isBlocked ? 'text-amber-500 bg-amber-900/20' : 'text-slate-600 hover:text-amber-400'}`}
                                    title={isBlocked ? "Разблокировать" : "Заблокировать (Архивировать)"}
                                >
                                    {isBlocked ? <Lock size={14} /> : <Unlock size={14} />}
                                </button>
                                {!isBlocked && (
                                    <button onClick={() => removeAbility(gIdx, originalIndex)} className="text-red-900 hover:text-red-500 transition-colors">
                                        <Trash2 size={14}/>
                                    </button>
                                )}
                             </div>
                         )}
                      </div>

                      {(shouldShowMech || isEditMode) && (
                        <div className={`flex flex-wrap gap-2 mb-2 ${isBlocked ? 'pointer-events-none' : ''}`}>
                          <BonusInput isEditMode={isEditMode && !isBlocked && !isBasic} bonuses={ability.bonuses} onChange={b => updateAbility(gIdx, originalIndex, 'bonuses', b)} />
                          <TimeInput 
                            icon={Clock} label="КД" isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.cd} unit={ability.cd_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'cd', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'cd_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hourglass} label="Длит." isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.dur} unit={ability.dur_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'dur', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'dur_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hash} label="Лимит" isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.limit || 0} unit={ability.limit_unit || ""} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'limit', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'limit_unit', u)} 
                            options={timeUnits}
                          />
                        </div>
                      )}

                      <div className={`mb-3 ${isBlocked ? 'pointer-events-none' : ''}`}>
                         <TagInput isEditMode={isEditMode && !isBlocked && !isBasic} tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />
                         {isEditMode && !isBlocked && !isBasic && <CommonTagToggles tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />}
                      </div>

                      {(shouldShowLore || isEditMode) && (
                        <StyledTextarea 
                          isEditMode={isEditMode && !isBlocked && !isBasic} 
                          disabled={isBlocked || isBasic}
                          value={ability.desc_lore} 
                          onChange={e => updateAbility(gIdx, originalIndex, 'desc_lore', e.target.value)} 
                          className="text-sm text-gray-400 italic mb-2" 
                          placeholder={t('ph_ability_lore', "Худ. описание")}
                        />
                      )}

                      {(shouldShowMech || isEditMode) && (isEditMode || ability.desc_mech) && (
                        <div className={`pt-2 ${!isEditMode && shouldShowLore ? 'border-t border-gray-800' : ''}`}>
                          <StyledTextarea 
                            isEditMode={isEditMode && !isBlocked && !isBasic} 
                            disabled={isBlocked || isBasic}
                            value={ability.desc_mech} 
                            onChange={e => updateAbility(gIdx, originalIndex, 'desc_mech', e.target.value)} 
                            className={`text-xs font-mono leading-relaxed ${isEditMode ? 'text-green-400' : (isBasic ? 'text-emerald-500/70' : 'text-green-500/80')} ${isBlocked ? 'text-slate-500' : ''}`} 
                            placeholder={t('ph_ability_mech', "Механика")} 
                          />
                        </div>
                      )}
                   </Card>
                 )})}

                 {isEditMode && !isBasic && (
                   <button onClick={() => addAbility(gIdx)} className="border-2 border-dashed border-gray-800 rounded-lg flex items-center justify-center text-gray-700 hover:text-cyan-500 hover:border-cyan-900 transition-all min-h-[150px] bg-slate-900/50 backdrop-blur-sm">
                     <Plus size={24} />
                   </button>
                 )}
               </div>
             )}
          </div>
        );
      })}

      {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">
         {t('btn_add_school', "Создать новую школу")}
      </Button>}
    </div>
  );
};

export default TabAbilities;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, Check, X, ChevronRight, ChevronDown, Eye, EyeOff, Lock, Unlock, Zap, AlertCircle, Link, FolderInput } from 'lucide-react';
import { DisplayMode } from '../App';
import { AbilityLinkModal } from './AbilityLinkModal';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (p: CharacterData['passives']) => void;
  triggersMap: Record<string, string>;
  timeUnits: TimeUnit[];
  onCharacterUpdate?: (u: Partial<CharacterData>) => void;
}

const TabPassives: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, triggersMap, timeUnits, onCharacterUpdate }) => {
  const { passives } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);

  // State for linking modal
  const [linkingState, setLinkingState] = useState<{gIdx: number, iIdx: number} | null>(null);

  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (gIdx: number, field: string, val: any) => {
    const next = [...passives];
    next[gIdx] = { ...next[gIdx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...passives, { group_name: "Классовые", tags: [], items: [], is_flaw_group: false }]);

  const removeGroup = (idx: number) => { 
     const next = passives.filter((_, i) => i !== idx);
     onChange(next);
     setDeleteConfirmGroupIdx(null);
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
  };

  const addItem = (gIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...(group.items || [])];
    group.items.push({ 
      name: "Новая черта", 
      bonuses: [], 
      trigger: "Always", 
      tags: [], 
      desc_lore: "", 
      desc_mech: "", 
      is_flaw: false,
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", is_blocked: false
    });
    next[gIdx] = group;
    onChange(next);
  };

  const updateItem = (gIdx: number, iIdx: number, field: string, val: any) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items[iIdx] = { ...group.items[iIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeItem = (gIdx: number, iIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.splice(iIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const moveItem = (fromGIdx: number, targetValue: string, iIdx: number) => {
      // Internal Move
      if (targetValue.startsWith('group_')) {
          const toGIdx = parseInt(targetValue.split('_')[1]);
          const next = [...passives];
          const sourceGroup = { ...next[fromGIdx] };
          const targetGroup = { ...next[toGIdx] };
          const item = sourceGroup.items[iIdx];

          // Update flag based on target group type (allows moving to Debuffs and vice-versa)
          item.is_flaw = !!targetGroup.is_flaw_group;

          sourceGroup.items = sourceGroup.items.filter((_, i) => i !== iIdx);
          targetGroup.items = [...targetGroup.items, item];

          next[fromGIdx] = sourceGroup;
          next[toGIdx] = targetGroup;
          onChange(next);
      }
      // Cross-move to Active Ability
      else if (targetValue.startsWith('active_') && onCharacterUpdate) {
          const toAIdx = parseInt(targetValue.split('_')[1]);
          const item = passives[fromGIdx].items[iIdx];

          const newAbility = {
              name: item.name,
              bonuses: item.bonuses,
              tags: item.tags,
              desc_lore: item.desc_lore,
              desc_mech: item.desc_mech,
              cd: item.cd,
              cd_unit: item.cd_unit,
              dur: item.dur,
              dur_unit: item.dur_unit,
              is_blocked: item.is_blocked,
              limit: 0,
              limit_unit: ''
          };

          // 1. Remove from passives
          const nextPassives = [...passives];
          nextPassives[fromGIdx] = {
              ...nextPassives[fromGIdx],
              items: nextPassives[fromGIdx].items.filter((_, i) => i !== iIdx)
          };

          // 2. Add to active
          const nextAbilities = [...character.ability_groups];
          if (nextAbilities[toAIdx]) {
              const targetGroup = { ...nextAbilities[toAIdx] };
              targetGroup.abilities = [...targetGroup.abilities, newAbility];
              nextAbilities[toAIdx] = targetGroup;
          }

          onCharacterUpdate({
              ability_groups: nextAbilities,
              passives: nextPassives
          });
      }
  };

  const handleAbilitySelect = (abilityName: string) => {
      if (!linkingState) return;
      const { gIdx, iIdx } = linkingState;

      const next = [...passives];
      const group = { ...next[gIdx] };
      group.items = [...group.items];

      // Auto-set trigger to 'ability' and set the ID
      group.items[iIdx] = { 
          ...group.items[iIdx], 
          trigger: 'ability',
          trigger_ability_id: abilityName
      };

      next[gIdx] = group;
      onChange(next);
      setLinkingState(null);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
    if (isEditMode) return [];
      const positiveGroups = passives.filter(g => !g.is_flaw_group);
      const data = positiveGroups.map((g, i) => {
        const name = g.group_name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.items ? g.items.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [passives, isEditMode]);

  const bonusData = useMemo(() => {
    if (isEditMode) return [];
      let phys = 0, magic = 0, unique = 0;
      passives.filter(g => !g.is_flaw_group).forEach(g => {
        if (Array.isArray(g.items)) {
          g.items.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.max(0, v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [passives, t, isEditMode]);

  // --- TRIGGER OPTIONS LOGIC ---
  const triggerOptions = useMemo(() => {
    const baseline = [
        { key: 'Always', label: 'Пассивно / Всегда' },
        { key: 'ability', label: 'От способности' },
        { key: 'on_hit', label: 'При попадании' },
        { key: 'on_defense', label: 'При защите' }
    ];

    // Normalize keys from integrated map for comparison
    const integratedEntries = Object.entries(triggersMap);
    const integratedKeysLower = integratedEntries.map(([k]) => k.toLowerCase());

    const result = baseline.map(base => {
        const fromDb = integratedEntries.find(([k]) => k.toLowerCase() === base.key.toLowerCase());
        return fromDb ? { key: fromDb[0], label: fromDb[1] } : base;
    });

    const baselineKeysLower = baseline.map(b => b.key.toLowerCase());
    integratedEntries.forEach(([key, label]) => {
        if (!baselineKeysLower.includes(key.toLowerCase())) {
            result.push({ key, label });
        }
    });

    return result;
  }, [triggersMap]);

  return (
    <div className="space-y-8 animate-fade-in relative">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} color="#10b981" t={t} />}

      <AbilityLinkModal 
        isOpen={!!linkingState}
        onClose={() => setLinkingState(null)}
        abilityGroups={character.ability_groups}
        onSelect={handleAbilitySelect}
      />

      {passives.map((group, gIdx) => {
         if (group.is_flaw_group) return null;
         const isHidden = (group as any).is_hidden;
         const visibleItems = group.items; 
         if (!isEditMode && (visibleItems.length === 0 || isHidden)) return null;
         const isCollapsed = collapsedGroups[gIdx];
         const itemsWithIndex = visibleItems.map((item, i) => ({ ...item, originalIndex: i }));
         const sortedItems = itemsWithIndex.sort((a, b) => {
             if (!!a.is_blocked === !!b.is_blocked) return 0;
             return a.is_blocked ? 1 : -1;
         });

         return (
           <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className="border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
                <div className="flex items-center justify-between mb-2 gap-4">
                   <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-emerald-400 transition-colors p-1">
                      {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
                   </button>
                   <div className="flex-1">
                       <StyledInput isEditMode={isEditMode} value={group.group_name} onChange={e => updateGroup(gIdx, 'group_name', e.target.value)} className="text-xl font-bold text-emerald-500 uppercase tracking-widest bg-transparent border-none p-0" />
                       {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
                   </div>
                   {isEditMode && (
                     <div className="flex items-center gap-2">
                        <button onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-emerald-600 hover:text-emerald-400'}`} title={isHidden ? "Показать в листе" : "Скрыть из листа"}>
                            {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                        </button>
                        {deleteConfirmGroupIdx === gIdx ? (
                           <div className="flex items-center gap-1">
                              <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                              <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                           </div>
                         ) : (
                           <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                         )}
                     </div>
                   )}
                </div>
                {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}
             </div>

             {!isCollapsed && (
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {sortedItems.map((itemWrapper) => {
                     const { originalIndex, ...item } = itemWrapper;
                     const isBlocked = !!item.is_blocked;
                     const rawTrigger = String(item.trigger || '').toLowerCase().trim();
                     const isAbilityTrigger = rawTrigger === 'ability' || rawTrigger.includes('способнос');

                     return (
                     <Card key={originalIndex} className={`relative bg-[#0b0d10] border-gray-800 border-l-4 border-l-emerald-500 ${isBlocked ? 'opacity-60 grayscale-[0.8] hover:opacity-100 hover:grayscale-0' : ''}`}>
                        <div className="flex justify-between items-start mb-2 overflow-hidden">
                          <div className="flex-1 min-w-0 mr-2" title={item.name}>
                            <StyledInput isEditMode={isEditMode && !isBlocked} disabled={isBlocked} value={item.name} onChange={e => updateItem(gIdx, originalIndex, 'name', e.target.value)} className={`font-bold text-lg truncate block w-full ${isBlocked ? 'text-slate-500' : 'text-emerald-300'}`} />
                          </div>
                          <div className="flex items-center gap-1 flex-shrink-0">
                            {isEditMode && (
                                <>
                                    {passives.length > 1 && (
                                        <div className="relative group">
                                            <button className="p-1 rounded text-slate-600 hover:text-emerald-400 transition-colors" title="Перенести в другую группу">
                                                <FolderInput size={14} />
                                            </button>
                                            <select 
                                                className="absolute inset-0 opacity-0 cursor-pointer"
                                                value="default"
                                                onChange={(e) => moveItem(gIdx, e.target.value, originalIndex)}
                                            >
                                                <option value="default" disabled>Перенести в...</option>
                                                <optgroup label="Пассивные Группы">
                                                    {passives.map((grp, i) => (
                                                        <option key={"p"+i} value={"group_"+i} disabled={i === gIdx}>{grp.group_name || 'Group ' + (i+1)}</option>
                                                    ))}
                                                </optgroup>
                                                {character.ability_groups && character.ability_groups.length > 0 && (
                                                    <optgroup label="Активные Способности">
                                                        {character.ability_groups.map((grp, i) => (
                                                            <option key={"a"+i} value={"active_"+i}>{grp.name}</option>
                                                        ))}
                                                    </optgroup>
                                                )}
                                            </select>
                                        </div>
                                    )}
                                    <button onClick={() => updateItem(gIdx, originalIndex, 'is_blocked', !isBlocked)} className={`p-1 rounded transition-colors ${isBlocked ? 'text-amber-500 bg-amber-900/20' : 'text-slate-600 hover:text-amber-400'}`} title={isBlocked ? "Разблокировать" : "Заблокировать (Архивировать)"}>
                                        {isBlocked ? <Lock size={14} /> : <Unlock size={14} />}
                                    </button>
                                    {!isBlocked && <button onClick={() => removeItem(gIdx, originalIndex)} className="text-red-900 hover:text-red-500"><Trash2 size={14}/></button>}
                                </>
                            )}
                          </div>
                        </div>

                        <div className={isBlocked ? 'pointer-events-none' : ''}>
                            {(shouldShowMech || isEditMode) && (
                            <div className="space-y-2 mb-2">
                                <div className="flex flex-wrap items-center gap-2">
                                    {isEditMode ? (
                                    <>
                                        <select 
                                            value={item.trigger} 
                                            onChange={e => updateItem(gIdx, originalIndex, 'trigger', e.target.value)} 
                                            className="bg-gray-800 text-xs border border-gray-700 rounded p-1 max-w-[200px] text-emerald-400 font-bold outline-none focus:border-emerald-500"
                                        >
                                            {triggerOptions.map(opt => (
                                                <option key={opt.key} value={opt.key}>{opt.label}</option>
                                            ))}
                                        </select>
                                        <button 
                                            onClick={() => setLinkingState({ gIdx, iIdx: originalIndex })}
                                            className="bg-violet-900/30 hover:bg-violet-800 text-violet-300 border border-violet-700/50 rounded px-2 py-1 text-[10px] flex items-center gap-1 uppercase font-bold tracking-wider transition-colors"
                                            title="Выбрать способность из списка"
                                        >
                                            <Link size={12} /> Привязать
                                        </button>
                                    </>
                                    ) : (
                                    <span className="text-[10px] font-bold uppercase bg-gray-800 px-2 py-0.5 rounded border border-gray-700 text-emerald-400">
                                        {isAbilityTrigger ? 'Активируется способностью' : (triggerOptions.find(o => o.key === item.trigger)?.label || item.trigger)}
                                    </span>
                                    )}
                                    <BonusInput isEditMode={isEditMode} bonuses={item.bonuses} onChange={b => updateItem(gIdx, originalIndex, 'bonuses', b)} />
                                </div>
                                {isAbilityTrigger && (
                                    <div className={`text-[10px] flex items-center gap-2 font-bold px-2 py-1 rounded bg-black/40 border border-emerald-900/30 ${!item.trigger_ability_id ? 'text-red-400' : 'text-emerald-400'}`}>
                                        <Zap size={12} />
                                        {item.trigger_ability_id ? `Связь: ${item.trigger_ability_id}` : "Связь не выбрана"}
                                    </div>
                                )}
                            </div>
                            )}

                            {(shouldShowMech || isEditMode) && (
                            <div className="flex flex-wrap gap-2 mb-2">
                                <TimeInput icon={Clock} label="КД" isEditMode={isEditMode} val={item.cd} unit={item.cd_unit} onChangeVal={v => updateItem(gIdx, originalIndex, 'cd', v)} onChangeUnit={u => updateItem(gIdx, originalIndex, 'cd_unit', u)} options={timeUnits} />
                                <TimeInput icon={Hourglass} label="Длит." isEditMode={isEditMode} val={item.dur} unit={item.dur_unit} onChangeVal={v => updateItem(gIdx, originalIndex, 'dur', v)} onChangeUnit={u => updateItem(gIdx, originalIndex, 'dur_unit', u)} options={timeUnits} />
                            </div>
                            )}

                            <div className="mb-2">
                                <TagInput isEditMode={isEditMode} tags={item.tags || []} onChange={t => updateItem(gIdx, originalIndex, 'tags', t)} />
                                {isEditMode && <CommonTagToggles tags={item.tags || []} onChange={t => updateItem(gIdx, originalIndex, 'tags', t)} />}
                            </div>

                            {(shouldShowLore || isEditMode) && <StyledTextarea isEditMode={isEditMode} value={item.desc_lore} onChange={e => updateItem(gIdx, originalIndex, 'desc_lore', e.target.value)} className="text-sm text-gray-400 italic mb-2" placeholder={t('ph_lore_generic', "Худ. описание")} />}
                            {(shouldShowMech || isEditMode) && (isEditMode || item.desc_mech) && <StyledTextarea isEditMode={isEditMode} value={item.desc_mech} onChange={e => updateItem(gIdx, originalIndex, 'desc_mech', e.target.value)} className={`text-xs font-mono ${isEditMode ? 'text-green-400' : 'text-green-500/80'}`} placeholder={t('ph_mech_generic', "Механика (Эффект)")} />}
                        </div>
                     </Card>
                   )})}
                   {isEditMode && <Button onClick={() => addItem(gIdx)} variant="secondary" className="border-dashed"><Plus size={14} /> {t('btn_add_passive', "Добавить черту")}</Button>}
                 </div>
             )}
           </div>
         );
      })}
       {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">{t('btn_add_passive_group', "Создать группу пассивок")}</Button>}
    </div>
  );
};

export default TabPassives;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, Check, X, ChevronRight, ChevronDown, Eye, EyeOff, Zap, AlertCircle, Link, FolderInput } from 'lucide-react';
import { DisplayMode } from '../App';
import { AbilityLinkModal } from './AbilityLinkModal';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (p: CharacterData['passives']) => void;
  triggersMap: Record<string, string>;
  timeUnits: TimeUnit[];
  onCharacterUpdate?: (u: Partial<CharacterData>) => void;
}

const TabDebuffs: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, triggersMap, timeUnits, onCharacterUpdate }) => {
  const { passives } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);

  const [linkingState, setLinkingState] = useState<{gIdx: number, iIdx: number} | null>(null);

  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (gIdx: number, field: string, val: any) => {
    const next = [...passives];
    next[gIdx] = { ...next[gIdx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...passives, { group_name: "Группа Дебаффов", tags: [], items: [], is_flaw_group: true }]);
  const removeGroup = (idx: number) => { 
     const next = passives.filter((_, i) => i !== idx);
     onChange(next);
     setDeleteConfirmGroupIdx(null);
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
  };

  const addItem = (gIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.push({ 
      name: "Новый Дебафф", 
      bonuses: [], 
      trigger: "Always", 
      tags: [], 
      desc_lore: "", 
      desc_mech: "", 
      is_flaw: true,
      cd: 0, cd_unit: "", dur: 0, dur_unit: ""
    });
    next[gIdx] = group;
    onChange(next);
  };

  const updateItem = (gIdx: number, iIdx: number, field: string, val: any) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items[iIdx] = { ...group.items[iIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeItem = (gIdx: number, iIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.splice(iIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const moveItem = (fromGIdx: number, targetValue: string, iIdx: number) => {
      // Internal Move
      if (targetValue.startsWith('group_')) {
          const toGIdx = parseInt(targetValue.split('_')[1]);
          const next = [...passives];
          const sourceGroup = { ...next[fromGIdx] };
          const targetGroup = { ...next[toGIdx] };
          const item = sourceGroup.items[iIdx];

          // Update flag based on target group type (allows moving to Passives and vice-versa)
          item.is_flaw = !!targetGroup.is_flaw_group;

          sourceGroup.items = sourceGroup.items.filter((_, i) => i !== iIdx);
          targetGroup.items = [...targetGroup.items, item];

          next[fromGIdx] = sourceGroup;
          next[toGIdx] = targetGroup;
          onChange(next);
      }
      // Cross-move to Active Ability
      else if (targetValue.startsWith('active_') && onCharacterUpdate) {
          const toAIdx = parseInt(targetValue.split('_')[1]);
          const item = passives[fromGIdx].items[iIdx];

          const newAbility = {
              name: item.name,
              bonuses: item.bonuses,
              tags: item.tags,
              desc_lore: item.desc_lore,
              desc_mech: item.desc_mech,
              cd: item.cd,
              cd_unit: item.cd_unit,
              dur: item.dur,
              dur_unit: item.dur_unit,
              is_blocked: item.is_blocked,
              limit: 0,
              limit_unit: ''
          };

          // 1. Remove from passives (debuffs)
          const nextPassives = [...passives];
          nextPassives[fromGIdx] = {
              ...nextPassives[fromGIdx],
              items: nextPassives[fromGIdx].items.filter((_, i) => i !== iIdx)
          };

          // 2. Add to active
          const nextAbilities = [...character.ability_groups];
          if (nextAbilities[toAIdx]) {
              const targetGroup = { ...nextAbilities[toAIdx] };
              targetGroup.abilities = [...targetGroup.abilities, newAbility];
              nextAbilities[toAIdx] = targetGroup;
          }

          onCharacterUpdate({
              ability_groups: nextAbilities,
              passives: nextPassives
          });
      }
  };

  const handleAbilitySelect = (abilityName: string) => {
      if (!linkingState) return;
      const { gIdx, iIdx } = linkingState;

      const next = [...passives];
      const group = { ...next[gIdx] };
      group.items = [...group.items];

      group.items[iIdx] = { 
          ...group.items[iIdx], 
          trigger: 'ability',
          trigger_ability_id: abilityName
      };

      next[gIdx] = group;
      onChange(next);
      setLinkingState(null);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
      const flaws = passives.filter(g => g.is_flaw_group);
      const data = flaws.map((g, i) => {
        const name = g.group_name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.items ? g.items.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [passives]);

  const bonusData = useMemo(() => {
      let phys = 0, magic = 0, unique = 0;
      passives.filter(g => g.is_flaw_group).forEach(g => {
        if (Array.isArray(g.items)) {
          g.items.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.abs(v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [passives, t]);

  const triggerOptions = useMemo(() => {
    const baseline = [
        { key: 'Always', label: 'Пассивно / Всегда' },
        { key: 'ability', label: 'От способности' },
        { key: 'on_hit', label: 'При попадании' },
        { key: 'on_defense', label: 'При защите' }
    ];
    const integratedEntries = Object.entries(triggersMap);
    const result = baseline.map(base => {
        const fromDb = integratedEntries.find(([k]) => k.toLowerCase() === base.key.toLowerCase());
        return fromDb ? { key: fromDb[0], label: fromDb[1] } : base;
    });
    const baselineKeysLower = baseline.map(b => b.key.toLowerCase());
    integratedEntries.forEach(([key, label]) => {
        if (!baselineKeysLower.includes(key.toLowerCase())) {
            result.push({ key, label });
        }
    });
    return result;
  }, [triggersMap]);

  return (
    <div className="space-y-8 animate-fade-in relative">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} isDebuff={true} t={t} />}

      <AbilityLinkModal 
        isOpen={!!linkingState}
        onClose={() => setLinkingState(null)}
        abilityGroups={character.ability_groups}
        onSelect={handleAbilitySelect}
      />

      {passives.map((group, gIdx) => {
         if (!group.is_flaw_group) return null;
         const isHidden = (group as any).is_hidden;
         const visibleItems = group.items;
         if (!isEditMode && (visibleItems.length === 0 || isHidden)) return null;
         const isCollapsed = collapsedGroups[gIdx];

         return (
           <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className="border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
                <div className="flex items-center justify-between mb-2 gap-4">
                   <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-red-400 transition-colors p-1">
                      {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
                   </button>
                   <div className="flex-1">
                       <StyledInput isEditMode={isEditMode} value={group.group_name} onChange={e => updateGroup(gIdx, 'group_name', e.target.value)} className="text-xl font-bold text-red-500 uppercase tracking-widest bg-transparent border-none p-0" />
                       {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
                   </div>
                   {isEditMode && (
                     <div className="flex items-center gap-2">
                       <button onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-red-600 hover:text-red-400'}`} title={isHidden ? "Показать в листе" : "Скрыть из листа"}>
                            {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                        </button>
                       {deleteConfirmGroupIdx === gIdx ? (
                         <div className="flex items-center gap-1">
                            <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                            <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                         </div>
                       ) : (
                         <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                       )}
                     </div>
                   )}
                </div>
                {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}
             </div>

             {!isCollapsed && (
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {visibleItems.map((item, iIdx) => {
                     const rawTrigger = String(item.trigger || '').toLowerCase().trim();
                     const isAbilityTrigger = rawTrigger === 'ability' || rawTrigger.includes('способнос');

                     return (
                     <Card key={iIdx} className="relative bg-[#0b0d10] border-gray-800 border-l-4 border-l-red-500 bg-red-900/5">
                        <div className="flex justify-between items-start mb-2 overflow-hidden">
                          <div className="flex-1 min-w-0 mr-2" title={item.name}>
                            <StyledInput isEditMode={isEditMode} value={item.name} onChange={e => updateItem(gIdx, iIdx, 'name', e.target.value)} className="font-bold text-lg truncate block w-full text-red-300" />
                          </div>
                          <div className="flex items-center gap-2 flex-shrink-0">
                            {isEditMode && (
                                <>
                                    {passives.length > 1 && (
                                        <div className="relative group">
                                            <button className="p-1 rounded text-slate-600 hover:text-red-400 transition-colors" title="Перенести в другую группу">
                                                <FolderInput size={14} />
                                            </button>
                                            <select 
                                                className="absolute inset-0 opacity-0 cursor-pointer"
                                                value="default"
                                                onChange={(e) => moveItem(gIdx, e.target.value, iIdx)}
                                            >
                                                <option value="default" disabled>Перенести в...</option>
                                                <optgroup label="Группы Дебаффов/Пассивок">
                                                    {passives.map((grp, i) => (
                                                        <option key={"p"+i} value={"group_"+i} disabled={i === gIdx}>{grp.group_name || 'Group ' + (i+1)}</option>
                                                    ))}
                                                </optgroup>
                                                {character.ability_groups && character.ability_groups.length > 0 && (
                                                    <optgroup label="Активные Способности">
                                                        {character.ability_groups.map((grp, i) => (
                                                            <option key={"a"+i} value={"active_"+i}>{grp.name}</option>
                                                        ))}
                                                    </optgroup>
                                                )}
                                            </select>
                                        </div>
                                    )}
                                    <button onClick={() => removeItem(gIdx, iIdx)} className="text-red-900 hover:text-red-500"><Trash2 size={14}/></button>
                                </>
                            )}
                          </div>
                        </div>

                        {(shouldShowMech || isEditMode) && (
                          <div className="space-y-2 mb-2">
                             <div className="flex flex-wrap items-center gap-2">
                                {isEditMode ? (
                                <>
                                    <select 
                                        value={item.trigger} 
                                        onChange={e => updateItem(gIdx, iIdx, 'trigger', e.target.value)} 
                                        className="bg-gray-800 text-xs border border-gray-700 rounded p-1 max-w-[200px] text-red-400 font-bold outline-none focus:border-red-500"
                                    >
                                        {triggerOptions.map(opt => (
                                            <option key={opt.key} value={opt.key}>{opt.label}</option>
                                        ))}
                                    </select>
                                    <button 
                                        onClick={() => setLinkingState({ gIdx, iIdx })}
                                        className="bg-red-900/30 hover:bg-red-800 text-red-300 border border-red-700/50 rounded px-2 py-1 text-[10px] flex items-center gap-1 uppercase font-bold tracking-wider transition-colors"
                                        title="Выбрать способность из списка"
                                    >
                                        <Link size={12} /> Привязать
                                    </button>
                                </>
                                ) : (
                                <span className="text-[10px] font-bold uppercase bg-gray-800 px-2 py-0.5 rounded border border-gray-700 text-red-400">
                                    {isAbilityTrigger ? 'Бремя способности' : (triggerOptions.find(o => o.key === item.trigger)?.label || item.trigger)}
                                </span>
                                )}
                                <BonusInput isEditMode={isEditMode} bonuses={item.bonuses} onChange={b => updateItem(gIdx, iIdx, 'bonuses', b)} />
                             </div>
                             {isAbilityTrigger && (
                                <div className={`text-[10px] flex items-center gap-2 font-bold px-2 py-1 rounded bg-black/40 border border-red-900/30 ${!item.trigger_ability_id ? 'text-orange-400' : 'text-red-400'}`}>
                                    <Zap size={12} />
                                    {item.trigger_ability_id ? `Связь: ${item.trigger_ability_id}` : "Связь не выбрана"}
                                </div>
                             )}
                          </div>
                        )}

                        {(shouldShowMech || isEditMode) && (
                          <div className="flex flex-wrap gap-2 mb-2">
                             <TimeInput icon={Clock} label="КД" isEditMode={isEditMode} val={item.cd} unit={item.cd_unit} onChangeVal={v => updateItem(gIdx, iIdx, 'cd', v)} onChangeUnit={u => updateItem(gIdx, iIdx, 'cd_unit', u)} options={timeUnits} />
                            <TimeInput icon={Hourglass} label="Длит." isEditMode={isEditMode} val={item.dur} unit={item.dur_unit} onChangeVal={v => updateItem(gIdx, iIdx, 'dur', v)} onChangeUnit={u => updateItem(gIdx, iIdx, 'dur_unit', u)} options={timeUnits} />
                          </div>
                        )}

                        <div className="mb-2">
                           <TagInput isEditMode={isEditMode} tags={item.tags || []} onChange={t => updateItem(gIdx, iIdx, 'tags', t)} />
                           {isEditMode && <CommonTagToggles tags={item.tags || []} onChange={t => updateItem(gIdx, iIdx, 'tags', t)} />}
                        </div>

                        {(shouldShowLore || isEditMode) && <StyledTextarea isEditMode={isEditMode} value={item.desc_lore} onChange={e => updateItem(gIdx, iIdx, 'desc_lore', e.target.value)} className="text-sm text-gray-400 italic mb-2" placeholder="Худ. описание" />}
                        {(shouldShowMech || isEditMode) && (isEditMode || item.desc_mech) && <StyledTextarea isEditMode={isEditMode} value={item.desc_mech} onChange={e => updateItem(gIdx, iIdx, 'desc_mech', e.target.value)} className={`text-xs font-mono ${isEditMode ? 'text-green-400' : 'text-green-500/80'}`} placeholder="Механика (Эффект)" />}
                     </Card>
                   )})}
                   {isEditMode && <Button onClick={() => addItem(gIdx)} variant="secondary" className="border-dashed"><Plus size={14} /> {t('mech_debuffs', "Добавить Дебафф")}</Button>}
                 </div>
             )}
           </div>
         );
      })}
       {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">{t('mech_debuffs', "Создать группу дебаффов")}</Button>}
    </div>
  );
};

export default TabDebuffs;

import React, { useState, useMemo, useEffect } from 'react';
import { Bonus, StatType, TimeUnit } from '../types';
import { 
  Trash2, Plus, Sword, Wand2, Crown, Shield, Heart, Coins, 
  User, Ghost, Skull, Book, Link as LinkIcon, Edit3, Eye, Save, Clock, Hourglass, Target
} from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

// --- Reusable Icons Map ---
export const StatIcons: Record<string, React.ReactNode> = {
  [StatType.PHYS]: <Sword size={16} />,
  [StatType.MAGIC]: <Wand2 size={16} />,
  [StatType.UNIQUE]: <Crown size={16} />,
  [StatType.CLEAN]: <Target size={16} />
};

export const Icons = {
  Plus,
  Trash: Trash2
};

// Updated Palette according to request: Phys(Red), Mag(Blue), Unique(Purple)
export const StatColors: Record<string, string> = {
  [StatType.PHYS]: "text-red-400 drop-shadow-[0_0_8px_rgba(248,113,113,0.5)]",
  [StatType.MAGIC]: "text-blue-400 drop-shadow-[0_0_8px_rgba(96,165,250,0.5)]",
  [StatType.UNIQUE]: "text-purple-400 drop-shadow-[0_0_8px_rgba(192,132,252,0.5)]",
  [StatType.CLEAN]: "text-slate-100 drop-shadow-[0_0_8px_rgba(255,255,255,0.5)]"
};

export const StatBg: Record<string, string> = {
  [StatType.PHYS]: "bg-red-950/30 border-red-900/40",
  [StatType.MAGIC]: "bg-blue-950/30 border-blue-900/40",
  [StatType.UNIQUE]: "bg-purple-950/30 border-purple-900/40",
  [StatType.CLEAN]: "bg-slate-800 border-slate-600"
};

// Helper to safely get color class (prevents crash on .split)
const getStatColorClass = (stat: string) => {
  const colorStr = StatColors[stat] || "text-slate-400"; // Fallback color
  return colorStr.split(' ')[0] || "text-slate-400";
};

const getStatBgClass = (stat: string) => {
  return StatBg[stat] || "bg-slate-900 border-slate-700";
};

// --- Components ---

export const Card = ({ children, className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  // Rune-like card: Dark bg, slight border, sharp corners or rune-clip
  <div className={`bg-[#050b14] border border-violet-900/20 shadow-lg p-4 relative overflow-hidden group ${className}`} {...props}>
    {/* Subtle gradient overlay */}
    <div className="absolute inset-0 bg-gradient-to-br from-violet-900/5 to-transparent pointer-events-none" />
    <div className="relative z-10">
      {children}
    </div>
  </div>
);

export const SectionHeader = ({ title, children }: { title: string, children?: React.ReactNode }) => (
  <div className="flex items-center justify-between mb-4 border-b border-violet-900/30 pb-2">
    <h3 className="text-lg font-serif font-bold text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 uppercase tracking-widest drop-shadow-sm flex items-center gap-2">
      {title}
    </h3>
    <div className="flex gap-2">{children}</div>
  </div>
);

export const Button = ({ 
  children, variant = 'primary', size = 'md', className = "", type = "button", ...props 
}: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'danger' | 'secondary' | 'ghost', size?: 'sm' | 'md' | 'icon' }) => {
  const base = "font-serif font-bold transition-all flex items-center justify-center gap-2 focus:outline-none relative overflow-hidden group rune-clip";
  const sizes = { sm: "px-3 py-1 text-xs", md: "px-6 py-2 text-sm", icon: "p-2" };

  const variants = {
    primary: "bg-violet-900/80 border border-violet-500/50 text-violet-100 hover:bg-violet-800 hover:shadow-glow hover:border-violet-400",
    danger: "bg-red-950/50 border border-red-800 text-red-200 hover:bg-red-900 hover:shadow-glow-red",
    secondary: "bg-slate-900 border border-slate-700 text-slate-300 hover:bg-slate-800 hover:border-slate-500",
    ghost: "bg-transparent text-slate-500 hover:text-violet-300 hover:bg-violet-900/20"
  };

  return (
    <button type={type} className={`${base} ${sizes[size]} ${variants[variant]} ${className}`} {...props}>
      {/* Shine effect */}
      <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-700" />
      <span className="relative z-10 flex items-center gap-2">{children}</span>
    </button>
  );
};

// --- Advanced Inputs (Optimized for Performance) ---

// Optimized Input: Updates parent state ONLY onBlur to prevent re-rendering entire tree on every keystroke
export const StyledInput = ({ label, isEditMode, className = "", value, onChange, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { label?: string, isEditMode: boolean }) => {
  const [localValue, setLocalValue] = useState(value);

  // Sync local state if parent value changes externally
  useEffect(() => {
    setLocalValue(value);
  }, [value]);

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    if (onChange && localValue !== value) {
      onChange(e);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setLocalValue(e.target.value);
  };

  if (!isEditMode) return (
    <div className="flex flex-col gap-1 w-full">
      {label && <span className="text-[9px] uppercase font-serif font-bold text-slate-600 tracking-widest">{label}</span>}
      <div className={`text-slate-200 border-b border-violet-900/20 py-1 min-h-[1.5rem] ${className}`}>{value}</div>
    </div>
  );

  return (
    <div className="flex flex-col gap-1 w-full">
      {label && <span className="text-[9px] uppercase font-serif font-bold text-slate-500 tracking-widest">{label}</span>}
      <input 
        className={`bg-[#020408] border border-violet-900/40 text-slate-200 text-sm px-3 py-1.5 focus:border-violet-500 focus:shadow-glow focus:outline-none transition-all placeholder:text-slate-700 rune-clip-r ${className}`} 
        value={localValue}
        onChange={handleChange}
        onBlur={handleBlur}
        {...props} 
      />
    </div>
  );
};

// Optimized Textarea: Same logic as Input
export const StyledTextarea = ({ label, isEditMode, className = "", value, onChange, ...props }: React.TextareaHTMLAttributes<HTMLTextAreaElement> & { label?: string, isEditMode: boolean }) => {
  const [localValue, setLocalValue] = useState(value);

  useEffect(() => {
    setLocalValue(value);
  }, [value]);

  const handleBlur = (e: React.FocusEvent<HTMLTextAreaElement>) => {
    if (onChange && localValue !== value) {
      onChange(e);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setLocalValue(e.target.value);
  };

  if (!isEditMode) return (
    <div className="flex flex-col gap-1 w-full">
      {label && <span className="text-[9px] uppercase font-serif font-bold text-slate-600 tracking-widest">{label}</span>}
      <div className={`text-slate-300 whitespace-pre-wrap text-sm ${className}`}>{value || "—"}</div>
    </div>
  );

  return (
    <div className="flex flex-col gap-1 w-full">
      {label && <span className="text-[9px] uppercase font-serif font-bold text-slate-500 tracking-widest">{label}</span>}
      <textarea 
        className={`bg-[#020408] border border-violet-900/40 text-slate-200 text-sm px-3 py-2 focus:border-violet-500 focus:shadow-glow focus:outline-none transition-all min-h-[80px] rune-clip-r ${className}`} 
        value={localValue}
        onChange={handleChange}
        onBlur={handleBlur}
        {...props} 
      />
    </div>
  );
};

export const StyledSelect = ({ 
  label, 
  isEditMode, 
  options, 
  className = "", 
  ...props 
}: React.SelectHTMLAttributes<HTMLSelectElement> & { label?: string, isEditMode: boolean, options: { label: string, value: string | number }[] }) => {
  if (!isEditMode) return (
    <div className="flex flex-col gap-1 w-full">
      {label && <span className="text-[9px] uppercase font-serif font-bold text-slate-600 tracking-widest">{label}</span>}
      <div className={`text-slate-200 border-b border-violet-900/20 py-1 min-h-[1.5rem] ${className}`}>
        {options.find(o => String(o.value) === String(props.value))?.label || props.value}
      </div>
    </div>
  );
  return (
    <div className="flex flex-col gap-1 w-full">
      {label && <span className="text-[9px] uppercase font-serif font-bold text-slate-500 tracking-widest">{label}</span>}
      <select className={`bg-[#020408] border border-violet-900/40 text-slate-200 text-sm px-2 py-1.5 focus:border-violet-500 focus:shadow-glow focus:outline-none rune-clip-r ${className}`} {...props}>
        {options.map(o => (
          <option key={o.value} value={o.value} className="bg-[#020408] text-slate-200">{o.label}</option>
        ))}
      </select>
    </div>
  );
};

export const TimeInput = ({ 
  label, val, unit, onChangeVal, onChangeUnit, isEditMode, icon: Icon, options = []
}: { label: string, val: number, unit: string, onChangeVal: (v: number) => void, onChangeUnit: (u: string) => void, isEditMode: boolean, icon: any, options?: TimeUnit[] }) => {

  /* [DIALECT] */ const { t } = useDialect();

  if (!isEditMode && (!val && !unit)) return null;

  const displayLabel = options.find(o => o.tag === unit)?.label || unit;
  const translatedLabel = label === 'КД' ? t('lbl_cd', 'КД') : 
                          label === 'Длит.' ? t('lbl_dur', 'Длит.') : 
                          label === 'Лимит' ? t('lbl_limit', 'Лимит') : label;

  return (
    <div className="flex items-center gap-2 text-xs bg-[#0f172a] rounded-sm border border-violet-900/30 px-2 py-1 shadow-sm">
      <Icon size={12} className="text-violet-500" />
      {isEditMode ? (
        <>
          <span className="text-slate-500 text-[10px] font-serif uppercase mr-1">{translatedLabel}:</span>
          <input type="number" value={val || ""} onChange={e => onChangeVal(parseFloat(e.target.value) || 0)} className="w-8 bg-transparent border-b border-slate-700 text-center text-slate-200 focus:border-violet-500 outline-none" placeholder="0" />
          <select value={unit} onChange={e => onChangeUnit(e.target.value)} className="bg-transparent text-slate-400 border-none p-0 focus:ring-0 max-w-[80px] text-[10px]">
            <option value="" className="bg-[#020408]">Ед.</option>
            {options.map(u => <option key={u.tag} value={u.tag} className="bg-[#020408]">{u.label}</option>)}
          </select>
        </>
      ) : (
        <span className="text-slate-400 font-medium">
          {translatedLabel}: <span className="text-violet-200">{val} {displayLabel}</span>
        </span>
      )}
    </div>
  );
};

// --- Complex Components ---

export const TagInput = ({ tags, onChange, isEditMode }: { tags: string[], onChange: (t: string[]) => void, isEditMode: boolean }) => {
  /* [DIALECT] */ const { t } = useDialect();
  if (!isEditMode) return null;

  const [input, setInput] = useState("");
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && input.trim()) {
      e.preventDefault();
      // Ensure lower case for better matching
      const newTag = input.trim().toLowerCase();
      if (!tags.includes(newTag)) {
          onChange([...tags, newTag]);
      }
      setInput("");
    }
  };
  const removeTag = (idx: number) => onChange(tags.filter((_, i) => i !== idx));

  return (
    <div className="flex flex-wrap gap-2 items-center">
      {tags.map((t, i) => (
        <span key={i} className="bg-violet-950/50 text-violet-300 border border-violet-800/50 px-2 py-0.5 rounded-sm text-[10px] uppercase font-bold flex items-center gap-1">
          {t}
          {isEditMode && <button onClick={() => removeTag(i)}><Trash2 size={10} /></button>}
        </span>
      ))}
      {isEditMode && (
        <input 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={t('ph_tag_add', "+Тег")}
          className="bg-transparent border-b border-slate-700 text-xs py-0.5 w-16 focus:w-24 transition-all focus:border-violet-500 outline-none text-slate-400 placeholder:text-slate-700"
        />
      )}
    </div>
  );
};

export const CommonTagToggles = ({ tags = [], onChange }: { tags: string[], onChange: (t: string[]) => void }) => {
  /* [DIALECT] */ const { t } = useDialect();

  const toggle = (tag: string) => {
    if (tags.includes(tag)) {
      onChange(tags.filter(curr => curr !== tag));
    } else {
      onChange([...tags, tag]);
    }
  };

  const checkboxes = [
    { key: 'buff', label: t('tag_buff', 'Бафф?') },
    { key: 'form', label: t('tag_form', 'Форма?') },
    { key: 'no_war', label: t('tag_no_war', 'Небоевое?') },
  ];

  return (
    <div className="flex gap-4 items-center mt-2 border-t border-violet-900/20 pt-2">
      {checkboxes.map(cb => (
        <label key={cb.key} className="flex items-center gap-1.5 cursor-pointer text-xs group select-none">
          <input 
            type="checkbox" 
            checked={tags.includes(cb.key)} 
            onChange={() => toggle(cb.key)}
            className="w-3.5 h-3.5 rounded-sm border-slate-600 bg-slate-900 text-violet-600 focus:ring-offset-0 focus:ring-0 cursor-pointer"
          />
          <span className={`font-bold font-serif transition-colors ${tags.includes(cb.key) ? 'text-violet-400' : 'text-slate-600 group-hover:text-slate-400'}`}>
            {cb.label}
          </span>
        </label>
      ))}
    </div>
  );
};

export const BonusInput = ({ bonuses, onChange, isEditMode }: { bonuses: Bonus[], onChange: (b: Bonus[]) => void, isEditMode: boolean }) => {
  const addBonus = () => onChange([...bonuses, { stat: StatType.PHYS, val: 1 }]);
  /* [DIALECT] */ const { t } = useDialect();

  const updateBonus = (idx: number, field: keyof Bonus, val: any) => {
    const next = [...bonuses];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };
  const removeBonus = (idx: number) => onChange(bonuses.filter((_, i) => i !== idx));

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap gap-2">
        {bonuses.map((b, i) => (
          <div key={i} className={`flex items-center gap-1 px-2 py-0.5 rounded-sm text-xs border ${getStatBgClass(b.stat)} ${getStatColorClass(b.stat)}`}>
            {isEditMode ? (
              <>
                 <select 
                   value={b.stat} 
                   onChange={(e) => updateBonus(i, 'stat', e.target.value)}
                   className="bg-transparent border-none p-0 text-[10px] font-bold focus:ring-0 cursor-pointer text-slate-300 uppercase"
                 >
                   <option value={StatType.PHYS} className="bg-[#020408]">{t('stat_phys_short', 'ФИЗ')}</option>
                   <option value={StatType.MAGIC} className="bg-[#020408]">{t('stat_mag_short', 'МАГ')}</option>
                   <option value={StatType.UNIQUE} className="bg-[#020408]">{t('stat_uni_short', 'УНИК')}</option>
                   <option value={StatType.CLEAN} className="bg-[#020408]">{t('stat_clean_short', 'ЧИСТ')}</option>
                 </select>
                 <span className="text-slate-500">:</span>
                 <input 
                   type="number" 
                   value={b.val} 
                   onChange={(e) => updateBonus(i, 'val', parseInt(e.target.value))}
                   className="w-8 bg-transparent border-b border-slate-600 text-center font-mono text-slate-200"
                 />
                 <button onClick={() => removeBonus(i)} className="text-red-400 hover:text-red-300 ml-1"><Trash2 size={10} /></button>
              </>
            ) : (
              <span className="flex items-center gap-1 font-mono font-bold">
                {StatIcons[b.stat] || <Sword size={12}/>} {b.val > 0 ? '+' : ''}{b.val}
              </span>
            )}
          </div>
        ))}
        {isEditMode && (
          <button onClick={addBonus} className="text-xs bg-slate-800 hover:bg-slate-700 border border-slate-600 rounded px-2 py-0.5 flex items-center gap-1">
            <Plus size={10} /> {t('lbl_bonus', 'Бонус')}
          </button>
        )}
      </div>
    </div>
  );
};

// --- Visualization Charts ---

interface ChartProps {
  structureData: { subject: string, value: number }[];
  bonusData: { subject: string, value: number }[];
  isDebuff?: boolean;
  color?: string;
  t: (key: string, def: string) => string;
}

const TabRadarChartsImpl = React.memo(({ structureData, bonusData, isDebuff = false, color, t }: ChartProps) => {
  if (structureData.length === 0 || structureData.every(d => d.value === 0)) {
      return (
        <div className="flex flex-col items-center justify-center h-32 border border-violet-900/20 border-dashed rounded-lg bg-violet-900/5 mb-6 text-slate-600 gap-2">
            <Ghost size={24} className="opacity-30" />
            <span className="text-[10px] uppercase font-bold tracking-widest">{t('msg_chart_empty', 'Пусто')}</span>
        </div>
      );
  }

  const maxStructureVal = Math.max(...structureData.map(d => d.value), 3);
  const maxBonusVal = Math.max(...bonusData.map(d => d.value), 5);

  const defaultColor = isDebuff ? "#ef4444" : "#8b5cf6"; // Red or Violet
  const mainColor = color || defaultColor;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6 h-48">

       <div className="bg-[#050b14] border border-violet-900/20 shadow-md p-2 relative flex flex-col rune-clip-r h-full">
          <div className="absolute top-2 left-3 text-[9px] font-bold text-slate-500 uppercase tracking-widest z-10 font-serif">
             {t('viz_structure', 'Структура')}
          </div>
          {/* Robust container for Recharts */}
          <div className="flex-1 min-h-0 relative">
            <div className="absolute inset-0">
                <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="65%" data={structureData}>
                    <PolarGrid stroke="#334155" strokeOpacity={0.4} />
                    <PolarAngleAxis 
                    dataKey="subject" 
                    tick={{ fill: '#64748b', fontSize: 9, fontFamily: 'Cinzel' }} 
                    />
                    <PolarRadiusAxis 
                    angle={30} 
                    domain={[0, maxStructureVal]} 
                    tick={false} 
                    axisLine={false} 
                    />
                    <Radar
                    name="Count"
                    dataKey="value"
                    stroke={mainColor}
                    strokeWidth={2}
                    fill={mainColor}
                    fillOpacity={0.2}
                    isAnimationActive={false}
                    />
                </RadarChart>
                </ResponsiveContainer>
            </div>
          </div>
       </div>

       <div className="bg-[#050b14] border border-violet-900/20 shadow-md p-2 relative flex flex-col rune-clip-r h-full">
          <div className="absolute top-2 left-3 text-[9px] font-bold text-slate-500 uppercase tracking-widest z-10 font-serif">
             {isDebuff ? t('viz_penalties', "Штрафы") : t('viz_bonuses', "Бонусы")}
          </div>
          <div className="flex-1 min-h-0 relative">
            <div className="absolute inset-0">
                <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="65%" data={bonusData}>
                    <PolarGrid stroke="#334155" strokeOpacity={0.4} />
                    <PolarAngleAxis 
                    dataKey="subject" 
                    tick={{ fill: mainColor, fontSize: 10, fontWeight: 'bold', fontFamily: 'Cinzel' }} 
                    />
                    <PolarRadiusAxis 
                    angle={30} 
                    domain={[0, maxBonusVal]} 
                    tick={false} 
                    axisLine={false} 
                    />
                    <Radar
                    name="Sum"
                    dataKey="value"
                    stroke={mainColor}
                    strokeWidth={2}
                    fill={mainColor}
                    fillOpacity={0.2}
                    isAnimationActive={false}
                    />
                </RadarChart>
                </ResponsiveContainer>
            </div>
          </div>
       </div>
    </div>
  );
}, (prev, next) => {
    return (
        prev.color === next.color &&
        prev.isDebuff === next.isDebuff &&
        JSON.stringify(prev.structureData) === JSON.stringify(next.structureData) &&
        JSON.stringify(prev.bonusData) === JSON.stringify(next.bonusData)
    );
});

export const TabRadarCharts = (props: ChartProps) => <TabRadarChartsImpl {...props} />;

import React, { useState } from 'react';
import { CharacterData, Faction } from '../types';
import { NPC_VOLUMES } from '../constants';
import { Button } from './Shared';
import { User as UserIcon, Skull, Sun, Moon, Ghost, Plus, ShieldCheck, Sword, Wand2, Crown, Link as LinkIcon, Terminal, Settings, ChevronLeft, ChevronRight, ChevronDown, Calendar } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  characters: CharacterData[];
  onSelect: (id: string) => void;
  onCreate: () => void;
  onOpenSettings?: () => void;
  onOpenTraining?: () => void;
}

const Roster: React.FC<Props> = ({ characters, onSelect, onCreate, onOpenSettings, onOpenTraining }) => {
  const { isAdmin } = useAuth();
  /* [DIALECT] */ const { t, handleLetterClick, handleSlashClick, isInputMode, inputBuffer, isBloodMode, trackTabChange } = useDialect();

  // Lazy initialize state from LocalStorage
  const [activeTab, setActiveTab] = useState<Faction>(() => {
      return (localStorage.getItem('roster_active_tab') as Faction) || Faction.LIGHT;
  });

  const [npcVolume, setNpcVolume] = useState<string>(() => {
      return localStorage.getItem('roster_npc_volume') || NPC_VOLUMES[0];
  });

  // Track tabs for secrets & persistence
  const handleTabChange = (faction: Faction) => {
      setActiveTab(faction);
      trackTabChange(faction);
      localStorage.setItem('roster_active_tab', faction);
  };

  const handleNpcVolumeChange = (vol: string) => {
      setNpcVolume(vol);
      localStorage.setItem('roster_npc_volume', vol);
  };

  // Tab ordering for navigation
  const tabs = [Faction.LIGHT, Faction.DARK, Faction.GRAVEYARD, Faction.NPC];

  const handleNextTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx + 1) % tabs.length]);
  };

  const handlePrevTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx - 1 + tabs.length) % tabs.length]);
  };

  const filtered = characters.filter(c => {
    if (!c.profile) return false;

    const isCompanion = c.profile.faction === Faction.NPC && c.profile.npc_volume === "Спутники и Рабы";
    if (c.meta.master_id && !isCompanion) return false;

    if (c.profile.faction !== activeTab) return false;
    if (activeTab === Faction.NPC && c.profile.npc_volume !== npcVolume) return false;
    return true;
  });

  // --- Theme Logic ---
  const getTheme = (f: Faction) => {
    // Blood Mode Override
    if (isBloodMode) {
        return {
            tab: "text-red-600 drop-shadow-[0_0_8px_rgba(220,38,38,0.8)] animate-pulse",
            border: "border-red-600/60",
            glow: "shadow-[0_0_30px_rgba(220,38,38,0.3)]",
            bg: "bg-red-950/40",
            text: "text-red-200",
            glowColor: "from-red-900/30"
        };
    }

    switch (f) {
      case Faction.LIGHT: 
        return {
          tab: "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]",
          border: "border-amber-500/30",
          glow: "shadow-[0_0_20px_rgba(251,191,36,0.1)]",
          bg: "bg-amber-950/20",
          text: "text-amber-100",
          // BRIGHTER LIGHT AMBIENCE
          glowColor: "from-amber-200/15" 
        };
      case Faction.DARK: 
        return {
          tab: "text-violet-400 drop-shadow-[0_0_8px_rgba(139,92,246,0.5)]",
          border: "border-violet-500/40",
          glow: "shadow-[0_0_20px_rgba(139,92,246,0.2)]",
          bg: "bg-violet-950/30",
          text: "text-violet-100",
          glowColor: "from-violet-900/20"
        };
      case Faction.NPC: 
        return {
          tab: "text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]",
          border: "border-red-500/30",
          glow: "shadow-[0_0_20px_rgba(239,68,68,0.1)]",
          bg: "bg-red-950/20",
          text: "text-red-100",
          glowColor: "from-red-900/20"
        };
      case Faction.GRAVEYARD: 
        return {
          tab: "text-slate-400 drop-shadow-[0_0_8px_rgba(148,163,184,0.5)]",
          border: "border-slate-500/30",
          glow: "shadow-[0_0_10px_rgba(148,163,184,0.1)]",
          bg: "bg-slate-900/20",
          text: "text-slate-300",
          glowColor: "from-slate-800/30"
        };
      default: 
        return { tab: "", border: "border-slate-700", glow: "", bg: "", text: "", glowColor: "from-slate-900/10" };
    }
  };

  const theme = getTheme(activeTab);

  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getLabelKey = (faction: Faction) => 
      faction === Faction.LIGHT ? 'fac_light' : 
      faction === Faction.DARK ? 'fac_dark' :
      faction === Faction.NPC ? 'fac_npc' : 'fac_graveyard';

  const TabButton = ({ faction, icon: Icon }: { faction: Faction, icon: any }) => {
    const isActive = activeTab === faction;
    const labelKey = getLabelKey(faction);
    const localTheme = getTheme(faction);

    return (
      <button
        onClick={() => handleTabChange(faction)}
        className={`relative flex items-center gap-2 px-6 py-3 font-serif font-bold uppercase tracking-widest text-[10px] md:text-xs transition-all whitespace-nowrap flex-shrink-0 ${
          isActive ? `${localTheme.tab} bg-white/5` : "text-slate-600 hover:text-slate-400 hover:bg-white/5"
        }`}
      >
        <Icon size={16} className={isBloodMode ? "text-red-500" : ""} />
        {t(labelKey, faction)}
        {isActive && (
           <div className={`absolute bottom-0 left-0 w-full h-0.5 bg-current shadow-[0_0_10px_currentColor]`}></div>
        )}
      </button>
    );
  };

  const renderInteractiveTitle = (text: string) => {
    return text.split('').map((char, i) => (
      <span 
        key={i} 
        onClick={(e) => {
           e.stopPropagation();
           handleLetterClick(char);
        }}
        className={`transition-colors cursor-pointer select-none active:scale-90 inline-block ${isBloodMode ? 'hover:text-red-500' : 'hover:text-violet-400'}`}
      >
        {char}
      </span>
    ));
  };

  // Main Background Image
  const rosterBg = "https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/character-roster-bg.jpg"; 

  return (
    <div className={`relative flex flex-col w-full h-[calc(100dvh-3rem)] md:h-[100dvh] overflow-hidden bg-transparent transition-all duration-1000 ${isBloodMode ? 'grayscale-[0.2] sepia-[0.3] hue-rotate-[-30deg]' : ''}`}>

      {/* Background Image Layer */}
      <div 
        className="absolute inset-0 bg-cover bg-center opacity-40 z-0 pointer-events-none mix-blend-screen"
        style={{ 
            backgroundImage: `url(${rosterBg})`,
            filter: 'contrast(1.2) brightness(0.6)' 
        }} 
      ></div>

      {/* Dark Overlay Gradient to ensure text legibility */}
      <div className="absolute inset-0 bg-gradient-to-br from-slate-950 via-slate-950/80 to-slate-950 pointer-events-none z-0"></div>

      {/* DYNAMIC ATMOSPHERIC LIGHTING LAYERS */}
      {/* Top ambient glow based on faction */}
      <div className={`fixed top-0 left-0 right-0 h-32 bg-gradient-to-b ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>
      {/* Bottom ambient glow based on faction */}
      <div className={`fixed bottom-0 left-0 right-0 h-32 bg-gradient-to-t ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>

      {/* Scrollable Content Layer */}
      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 md:px-12 pt-4 md:pt-8 pb-32 w-full relative z-10">

            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4 border-b border-white/10 pb-6">
                <div>
                    <h1 className={`text-4xl md:text-6xl font-gothic font-normal text-transparent bg-clip-text bg-gradient-to-r tracking-[0.05em] uppercase flex items-center gap-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)] ${isBloodMode ? 'from-red-300 via-red-100 to-red-500' : 'from-slate-200 via-white to-slate-400'}`}>
                        <div className="flex items-center gap-2">
                            <span className="flex">{renderInteractiveTitle(t('app_title_1', 'Летопись'))}</span> 
