export default SheetHeader;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus, Ability } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, ChevronDown, ChevronRight, Eye, EyeOff, Hash, Check, X, Lock, Unlock, Sparkles, FolderInput } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (groups: CharacterData['ability_groups']) => void;
  timeUnits: TimeUnit[];
  onCharacterUpdate?: (u: Partial<CharacterData>) => void;
}

const TabAbilities: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, timeUnits, onCharacterUpdate }) => {
  const { ability_groups } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (idx: number, field: string, val: any) => {
    const next = [...ability_groups];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...ability_groups, { name: "Новая Школа", tags: [], abilities: [], is_hidden: false }]);

  const removeGroup = (idx: number) => {
     const next = ability_groups.filter((_, i) => i !== idx);
     onChange(next);

     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
     setDeleteConfirmGroupIdx(null);
  };

  const addAbility = (gIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...(group.abilities || [])];

    group.abilities.push({ 
      name: "Новый Навык", bonuses: [], tags: [], desc_lore: "", desc_mech: "",
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", limit: 0, limit_unit: "", is_blocked: false
    });

    next[gIdx] = group;
    onChange(next);
  };

  const updateAbility = (gIdx: number, aIdx: number, field: string, val: any) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities[aIdx] = { ...group.abilities[aIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeAbility = (gIdx: number, aIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities.splice(aIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const moveAbility = (fromGIdx: number, targetValue: string, aIdx: number) => {
      // Internal move
      if (targetValue.startsWith('group_')) {
          const toGIdx = parseInt(targetValue.split('_')[1]);
          const next = [...ability_groups];
          const sourceGroup = { ...next[fromGIdx] };
          const targetGroup = { ...next[toGIdx] };
          const ability = sourceGroup.abilities[aIdx];

          sourceGroup.abilities = sourceGroup.abilities.filter((_, i) => i !== aIdx);
          targetGroup.abilities = [...targetGroup.abilities, ability];

          next[fromGIdx] = sourceGroup;
          next[toGIdx] = targetGroup;
          onChange(next);
      } 
      // Cross-move to Passive
      else if (targetValue.startsWith('passive_') && onCharacterUpdate) {
          const toPIdx = parseInt(targetValue.split('_')[1]);
          const ability = ability_groups[fromGIdx].abilities[aIdx];

          // Convert Ability to Passive
          const newPassive = {
              name: ability.name,
              bonuses: ability.bonuses,
              tags: ability.tags,
              desc_lore: ability.desc_lore,
              desc_mech: ability.desc_mech,
              cd: ability.cd,
              cd_unit: ability.cd_unit,
              dur: ability.dur,
              dur_unit: ability.dur_unit,
              is_blocked: ability.is_blocked,
              trigger: "Always",
              is_flaw: false // Defaults to not flaw, will be adjusted by target group type usually
          };

          // 1. Remove from abilities
          const nextAbilities = [...ability_groups];
          nextAbilities[fromGIdx] = {
              ...nextAbilities[fromGIdx],
              abilities: nextAbilities[fromGIdx].abilities.filter((_, i) => i !== aIdx)
          };

          // 2. Add to passives
          const nextPassives = [...character.passives];
          // Ensure target group exists
          if (nextPassives[toPIdx]) {
              const targetGroup = { ...nextPassives[toPIdx] };
              // inherit is_flaw from group if possible, or keep default
              newPassive.is_flaw = !!targetGroup.is_flaw_group;
              targetGroup.items = [...targetGroup.items, newPassive];
              nextPassives[toPIdx] = targetGroup;
          }

          onCharacterUpdate({
              ability_groups: nextAbilities,
              passives: nextPassives
          });
      }
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
      if (isEditMode) return [];
      const data = ability_groups.map((g, i) => {
        const name = g.name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.abilities ? g.abilities.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [ability_groups, isEditMode]);

  const bonusData = useMemo(() => {
      if (isEditMode) return [];
      let phys = 0, magic = 0, unique = 0;
      ability_groups.forEach(g => {
        if (Array.isArray(g.abilities)) {
          g.abilities.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.max(0, v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [ability_groups, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} color="#06b6d4" t={t} />}

      {ability_groups.map((group, gIdx) => {
        const isBasic = group.name === "Базовые Действия";
        if (!isEditMode && (group.abilities.length === 0 || group.is_hidden)) return null;

        const isCollapsed = collapsedGroups[gIdx];
        const isHidden = group.is_hidden;
        const abilitiesWithIndex = group.abilities.map((ab, i) => ({ ...ab, originalIndex: i }));
        const sortedAbilities = abilitiesWithIndex.sort((a, b) => {
            if (a.is_blocked === b.is_blocked) return 0;
            return a.is_blocked ? 1 : -1;
        });

        return (
          <div key={gIdx} className={`space-y-4 transition-all ${isBasic ? 'border-l-4 border-emerald-500' : ''} ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className={`flex items-center gap-4 border-b border-gray-800 pb-2 ${isBasic ? 'bg-emerald-950/20' : 'bg-slate-900/90'} p-3 rounded-t-lg backdrop-blur-sm shadow-md`}>
               <button onClick={() => toggleGroup(gIdx)} className={`p-1 transition-colors ${isBasic ? 'text-emerald-400 hover:text-emerald-300' : 'text-gray-500 hover:text-cyan-400'}`}>
                  {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
               </button>
               <div className="flex-1 flex items-center gap-2">
                 {isBasic && <Sparkles size={18} className="text-emerald-500 shrink-0" />}
                 <StyledInput 
                   isEditMode={isEditMode && !isBasic} 
                   value={group.name} 
                   onChange={e => updateGroup(gIdx, 'name', e.target.value)} 
                   className={`text-xl font-bold uppercase tracking-widest bg-transparent border-none p-0 ${isBasic ? 'text-emerald-500' : 'text-cyan-500'}`} 
                 />
                 {isBasic && isEditMode && <span className="text-[9px] uppercase font-bold text-emerald-900 bg-emerald-500/20 px-2 py-0.5 rounded">Система</span>}
                 {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
               </div>

               {!isCollapsed && <TagInput isEditMode={isEditMode && !isBasic} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}

               {isEditMode && !isBasic && (
                 <>
                   <button 
                     onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} 
                     className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-cyan-600 hover:text-cyan-400'}`}
                     title={isHidden ? "Показать в листе" : "Скрыть из листа"}
                   >
                     {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                   </button>

                   {deleteConfirmGroupIdx === gIdx ? (
                     <div className="flex items-center gap-1">
                        <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                        <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                     </div>
                   ) : (
                     <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                   )}
                 </>
               )}
             </div>

             {!isCollapsed && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                 {sortedAbilities.map((abilityWrapper) => {
                   const { originalIndex, ...ability } = abilityWrapper;
                   const isBlocked = ability.is_blocked;

                   return (
                   <Card key={originalIndex} className={`hover:border-gray-700 transition-colors bg-[#0b0d10] border-gray-800 ${isBlocked ? 'opacity-60 grayscale-[0.8] hover:opacity-100 hover:grayscale-0' : ''} ${isBasic ? 'border-l-2 border-emerald-900/50' : ''}`}>
                      <div className="flex justify-between items-start mb-2 overflow-hidden">
                         <div className="flex-1 min-w-0 mr-2" title={ability.name}>
                           <StyledInput 
                              isEditMode={isEditMode && !isBlocked && !isBasic} 
                              disabled={isBlocked || isBasic}
                              value={ability.name} 
                              onChange={e => updateAbility(gIdx, originalIndex, 'name', e.target.value)} 
                              className={`font-bold text-lg truncate block w-full ${isBlocked ? 'text-slate-500' : (isBasic ? 'text-emerald-300' : '')}`} 
                              placeholder={t('ph_ability_name', "Название навыка")}
                           />
                         </div>
                         {isEditMode && !isBasic && (
                             <div className="flex items-center gap-1 flex-shrink-0">
                                <div className="relative group">
                                    <button className="p-1 rounded text-slate-600 hover:text-cyan-400 transition-colors" title="Перенести...">
                                        <FolderInput size={14} />
                                    </button>
                                    <select 
                                        className="absolute inset-0 opacity-0 cursor-pointer"
                                        value={"default"}
                                        onChange={(e) => moveAbility(gIdx, e.target.value, originalIndex)}
                                    >
                                        <option value="default" disabled className="bg-[#0b0d10]">Перенести в...</option>
                                        <optgroup label="Школы" className="bg-[#0b0d10]">
                                            {ability_groups.map((grp, i) => (
                                                <option key={"g"+i} value={"group_"+i} disabled={i === gIdx} className="bg-[#0b0d10]">{grp.name}</option>
                                            ))}
                                        </optgroup>
                                        {character.passives && character.passives.length > 0 && (
                                            <optgroup label="Пассивки/Дебаффы" className="bg-[#0b0d10]">
                                                {character.passives.map((grp, i) => (
                                                    <option key={"p"+i} value={"passive_"+i} className="bg-[#0b0d10]">{grp.group_name || 'Группа ' + (i+1)}</option>
                                                ))}
                                            </optgroup>
                                        )}
                                    </select>
                                </div>
                                <button 
                                    onClick={() => updateAbility(gIdx, originalIndex, 'is_blocked', !isBlocked)}
                                    className={`p-1 rounded transition-colors ${isBlocked ? 'text-amber-500 bg-amber-900/20' : 'text-slate-600 hover:text-amber-400'}`}
                                    title={isBlocked ? "Разблокировать" : "Заблокировать (Архивировать)"}
                                >
                                    {isBlocked ? <Lock size={14} /> : <Unlock size={14} />}
                                </button>
                                {!isBlocked && (
                                    <button onClick={() => removeAbility(gIdx, originalIndex)} className="text-red-900 hover:text-red-500 transition-colors">
                                        <Trash2 size={14}/>
                                    </button>
                                )}
                             </div>
                         )}
                      </div>

                      {(shouldShowMech || isEditMode) && (
                        <div className={`flex flex-wrap gap-2 mb-2 ${isBlocked ? 'pointer-events-none' : ''}`}>
                          <BonusInput isEditMode={isEditMode && !isBlocked && !isBasic} bonuses={ability.bonuses} onChange={b => updateAbility(gIdx, originalIndex, 'bonuses', b)} />
                          <TimeInput 
                            icon={Clock} label="КД" isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.cd} unit={ability.cd_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'cd', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'cd_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hourglass} label="Длит." isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.dur} unit={ability.dur_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'dur', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'dur_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hash} label="Лимит" isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.limit || 0} unit={ability.limit_unit || ""} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'limit', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'limit_unit', u)} 
                            options={timeUnits}
                          />
                        </div>
                      )}

                      <div className={`mb-3 ${isBlocked ? 'pointer-events-none' : ''}`}>
                         <TagInput isEditMode={isEditMode && !isBlocked && !isBasic} tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />
                         {isEditMode && !isBlocked && !isBasic && <CommonTagToggles tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />}
                      </div>

                      {(shouldShowLore || isEditMode) && (
                        <StyledTextarea 
                          isEditMode={isEditMode && !isBlocked && !isBasic} 
                          disabled={isBlocked || isBasic}
                          value={ability.desc_lore} 
                          onChange={e => updateAbility(gIdx, originalIndex, 'desc_lore', e.target.value)} 
                          className="text-sm text-gray-400 italic mb-2" 
                          placeholder={t('ph_ability_lore', "Худ. описание")}
                        />
                      )}

                      {(shouldShowMech || isEditMode) && (isEditMode || ability.desc_mech) && (
                        <div className={`pt-2 ${!isEditMode && shouldShowLore ? 'border-t border-gray-800' : ''}`}>
                          <StyledTextarea 
                            isEditMode={isEditMode && !isBlocked && !isBasic} 
                            disabled={isBlocked || isBasic}
                            value={ability.desc_mech} 
                            onChange={e => updateAbility(gIdx, originalIndex, 'desc_mech', e.target.value)} 
                            className={`text-xs font-mono leading-relaxed ${isEditMode ? 'text-green-400' : (isBasic ? 'text-emerald-500/70' : 'text-green-500/80')} ${isBlocked ? 'text-slate-500' : ''}`} 
                            placeholder={t('ph_ability_mech', "Механика")} 
                          />
                        </div>
                      )}
                   </Card>
                 )})}

                 {isEditMode && !isBasic && (
                   <button onClick={() => addAbility(gIdx)} className="border-2 border-dashed border-gray-800 rounded-lg flex items-center justify-center text-gray-700 hover:text-cyan-500 hover:border-cyan-900 transition-all min-h-[150px] bg-slate-900/50 backdrop-blur-sm">
                     <Plus size={24} />
                   </button>
                 )}
               </div>
             )}
          </div>
        );
      })}

      {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">
         {t('btn_add_school', "Создать новую школу")}
      </Button>}
    </div>
  );
};

export default TabAbilities;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, Check, X, ChevronRight, ChevronDown, Eye, EyeOff, Lock, Unlock, Zap, AlertCircle, Link, FolderInput } from 'lucide-react';
import { DisplayMode } from '../App';
import { AbilityLinkModal } from './AbilityLinkModal';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (p: CharacterData['passives']) => void;
  triggersMap: Record<string, string>;
  timeUnits: TimeUnit[];
  onCharacterUpdate?: (u: Partial<CharacterData>) => void;
}

const TabPassives: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, triggersMap, timeUnits, onCharacterUpdate }) => {
  const { passives } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);

  // State for linking modal
  const [linkingState, setLinkingState] = useState<{gIdx: number, iIdx: number} | null>(null);

  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (gIdx: number, field: string, val: any) => {
    const next = [...passives];
    next[gIdx] = { ...next[gIdx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...passives, { group_name: "Классовые", tags: [], items: [], is_flaw_group: false }]);

  const removeGroup = (idx: number) => { 
     const next = passives.filter((_, i) => i !== idx);
     onChange(next);
     setDeleteConfirmGroupIdx(null);
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
  };

  const addItem = (gIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...(group.items || [])];
    group.items.push({ 
      name: "Новая черта", 
      bonuses: [], 
      trigger: "Always", 
      tags: [], 
      desc_lore: "", 
      desc_mech: "", 
      is_flaw: false,
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", is_blocked: false
    });
    next[gIdx] = group;
    onChange(next);
  };

  const updateItem = (gIdx: number, iIdx: number, field: string, val: any) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items[iIdx] = { ...group.items[iIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeItem = (gIdx: number, iIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.splice(iIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const moveItem = (fromGIdx: number, targetValue: string, iIdx: number) => {
      // Internal Move
      if (targetValue.startsWith('group_')) {
          const toGIdx = parseInt(targetValue.split('_')[1]);
          const next = [...passives];
          const sourceGroup = { ...next[fromGIdx] };
          const targetGroup = { ...next[toGIdx] };
          const item = sourceGroup.items[iIdx];

          // Update flag based on target group type (allows moving to Debuffs and vice-versa)
          item.is_flaw = !!targetGroup.is_flaw_group;

          sourceGroup.items = sourceGroup.items.filter((_, i) => i !== iIdx);
          targetGroup.items = [...targetGroup.items, item];

          next[fromGIdx] = sourceGroup;
          next[toGIdx] = targetGroup;
          onChange(next);
      }
      // Cross-move to Active Ability
      else if (targetValue.startsWith('active_') && onCharacterUpdate) {
          const toAIdx = parseInt(targetValue.split('_')[1]);
          const item = passives[fromGIdx].items[iIdx];

          const newAbility = {
              name: item.name,
              bonuses: item.bonuses,
              tags: item.tags,
              desc_lore: item.desc_lore,
              desc_mech: item.desc_mech,
              cd: item.cd,
              cd_unit: item.cd_unit,
              dur: item.dur,
              dur_unit: item.dur_unit,
              is_blocked: item.is_blocked,
              limit: 0,
              limit_unit: ''
          };

          // 1. Remove from passives
          const nextPassives = [...passives];
          nextPassives[fromGIdx] = {
              ...nextPassives[fromGIdx],
              items: nextPassives[fromGIdx].items.filter((_, i) => i !== iIdx)
          };

          // 2. Add to active
          const nextAbilities = [...character.ability_groups];
          if (nextAbilities[toAIdx]) {
              const targetGroup = { ...nextAbilities[toAIdx] };
              targetGroup.abilities = [...targetGroup.abilities, newAbility];
              nextAbilities[toAIdx] = targetGroup;
          }

          onCharacterUpdate({
              ability_groups: nextAbilities,
              passives: nextPassives
          });
      }
  };

  const handleAbilitySelect = (abilityName: string) => {
      if (!linkingState) return;
      const { gIdx, iIdx } = linkingState;

      const next = [...passives];
      const group = { ...next[gIdx] };
      group.items = [...group.items];

      // Auto-set trigger to 'ability' and set the ID
      group.items[iIdx] = { 
          ...group.items[iIdx], 
          trigger: 'ability',
          trigger_ability_id: abilityName
      };

      next[gIdx] = group;
      onChange(next);
      setLinkingState(null);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
    if (isEditMode) return [];
      const positiveGroups = passives.filter(g => !g.is_flaw_group);
      const data = positiveGroups.map((g, i) => {
        const name = g.group_name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.items ? g.items.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [passives, isEditMode]);

  const bonusData = useMemo(() => {
    if (isEditMode) return [];
      let phys = 0, magic = 0, unique = 0;
      passives.filter(g => !g.is_flaw_group).forEach(g => {
        if (Array.isArray(g.items)) {
          g.items.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.max(0, v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [passives, t, isEditMode]);

  // --- TRIGGER OPTIONS LOGIC ---
  const triggerOptions = useMemo(() => {
    const baseline = [
        { key: 'Always', label: 'Пассивно / Всегда' },
        { key: 'ability', label: 'От способности' },
        { key: 'on_hit', label: 'При попадании' },
        { key: 'on_defense', label: 'При защите' }
    ];

    // Normalize keys from integrated map for comparison
    const integratedEntries = Object.entries(triggersMap);
    const integratedKeysLower = integratedEntries.map(([k]) => k.toLowerCase());

    const result = baseline.map(base => {
        const fromDb = integratedEntries.find(([k]) => k.toLowerCase() === base.key.toLowerCase());
        return fromDb ? { key: fromDb[0], label: fromDb[1] } : base;
    });

    const baselineKeysLower = baseline.map(b => b.key.toLowerCase());
    integratedEntries.forEach(([key, label]) => {
        if (!baselineKeysLower.includes(key.toLowerCase())) {
            result.push({ key, label });
        }
    });

    return result;
  }, [triggersMap]);

  return (
    <div className="space-y-8 animate-fade-in relative">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} color="#10b981" t={t} />}

      <AbilityLinkModal 
        isOpen={!!linkingState}
        onClose={() => setLinkingState(null)}
        abilityGroups={character.ability_groups}
        onSelect={handleAbilitySelect}
      />

      {passives.map((group, gIdx) => {
         if (group.is_flaw_group) return null;
         const isHidden = (group as any).is_hidden;
         const visibleItems = group.items; 
         if (!isEditMode && (visibleItems.length === 0 || isHidden)) return null;
         const isCollapsed = collapsedGroups[gIdx];
         const itemsWithIndex = visibleItems.map((item, i) => ({ ...item, originalIndex: i }));
         const sortedItems = itemsWithIndex.sort((a, b) => {
             if (!!a.is_blocked === !!b.is_blocked) return 0;
             return a.is_blocked ? 1 : -1;
         });

         return (
           <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className="border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
                <div className="flex items-center justify-between mb-2 gap-4">
                   <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-emerald-400 transition-colors p-1">
                      {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
                   </button>
                   <div className="flex-1">
                       <StyledInput isEditMode={isEditMode} value={group.group_name} onChange={e => updateGroup(gIdx, 'group_name', e.target.value)} className="text-xl font-bold text-emerald-500 uppercase tracking-widest bg-transparent border-none p-0" />
                       {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
                   </div>
                   {isEditMode && (
                     <div className="flex items-center gap-2">
                        <button onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-emerald-600 hover:text-emerald-400'}`} title={isHidden ? "Показать в листе" : "Скрыть из листа"}>
                            {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                        </button>
                        {deleteConfirmGroupIdx === gIdx ? (
                           <div className="flex items-center gap-1">
                              <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                              <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                           </div>
                         ) : (
                           <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                         )}
                     </div>
                   )}
                </div>
                {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}
             </div>

             {!isCollapsed && (
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {sortedItems.map((itemWrapper) => {
                     const { originalIndex, ...item } = itemWrapper;
                     const isBlocked = !!item.is_blocked;
                     const rawTrigger = String(item.trigger || '').toLowerCase().trim();
                     const isAbilityTrigger = rawTrigger === 'ability' || rawTrigger.includes('способнос');

                     return (
                     <Card key={originalIndex} className={`relative bg-[#0b0d10] border-gray-800 border-l-4 border-l-emerald-500 ${isBlocked ? 'opacity-60 grayscale-[0.8] hover:opacity-100 hover:grayscale-0' : ''}`}>
                        <div className="flex justify-between items-start mb-2 overflow-hidden">
                          <div className="flex-1 min-w-0 mr-2" title={item.name}>
                            <StyledInput isEditMode={isEditMode && !isBlocked} disabled={isBlocked} value={item.name} onChange={e => updateItem(gIdx, originalIndex, 'name', e.target.value)} className={`font-bold text-lg truncate block w-full ${isBlocked ? 'text-slate-500' : 'text-emerald-300'}`} />
                          </div>
                          <div className="flex items-center gap-1 flex-shrink-0">
                            {isEditMode && (
                                <>
                                    {passives.length > 1 && (
                                        <div className="relative group">
                                            <button className="p-1 rounded text-slate-600 hover:text-emerald-400 transition-colors" title="Перенести в другую группу">
                                                <FolderInput size={14} />
                                            </button>
                                            <select 
                                                className="absolute inset-0 opacity-0 cursor-pointer"
                                                value="default"
                                                onChange={(e) => moveItem(gIdx, e.target.value, originalIndex)}
                                            >
                                                <option value="default" disabled className="bg-[#0b0d10]">Перенести в...</option>
                                                <optgroup label="Пассивные Группы" className="bg-[#0b0d10]">
                                                    {passives.map((grp, i) => (
                                                        <option key={"p"+i} value={"group_"+i} disabled={i === gIdx} className="bg-[#0b0d10]">{grp.group_name || 'Group ' + (i+1)}</option>
                                                    ))}
                                                </optgroup>
                                                {character.ability_groups && character.ability_groups.length > 0 && (
                                                    <optgroup label="Активные Способности" className="bg-[#0b0d10]">
                                                        {character.ability_groups.map((grp, i) => (
                                                            <option key={"a"+i} value={"active_"+i} className="bg-[#0b0d10]">{grp.name}</option>
                                                        ))}
                                                    </optgroup>
                                                )}
                                            </select>
                                        </div>
                                    )}
                                    <button onClick={() => updateItem(gIdx, originalIndex, 'is_blocked', !isBlocked)} className={`p-1 rounded transition-colors ${isBlocked ? 'text-amber-500 bg-amber-900/20' : 'text-slate-600 hover:text-amber-400'}`} title={isBlocked ? "Разблокировать" : "Заблокировать (Архивировать)"}>
                                        {isBlocked ? <Lock size={14} /> : <Unlock size={14} />}
                                    </button>
                                    {!isBlocked && <button onClick={() => removeItem(gIdx, originalIndex)} className="text-red-900 hover:text-red-500"><Trash2 size={14}/></button>}
                                </>
                            )}
                          </div>
                        </div>

                        <div className={isBlocked ? 'pointer-events-none' : ''}>
                            {(shouldShowMech || isEditMode) && (
                            <div className="space-y-2 mb-2">
                                <div className="flex flex-wrap items-center gap-2">
                                    {isEditMode ? (
                                    <>
                                        <select 
                                            value={item.trigger} 
                                            onChange={e => updateItem(gIdx, originalIndex, 'trigger', e.target.value)} 
                                            className="bg-gray-800 text-xs border border-gray-700 rounded p-1 max-w-[200px] text-emerald-400 font-bold outline-none focus:border-emerald-500"
                                        >
                                            {triggerOptions.map(opt => (
                                                <option key={opt.key} value={opt.key} className="bg-[#0b0d10]">{opt.label}</option>
                                            ))}
                                        </select>
                                        <button 
                                            onClick={() => setLinkingState({ gIdx, iIdx: originalIndex })}
                                            className="bg-violet-900/30 hover:bg-violet-800 text-violet-300 border border-violet-700/50 rounded px-2 py-1 text-[10px] flex items-center gap-1 uppercase font-bold tracking-wider transition-colors"
                                            title="Выбрать способность из списка"
                                        >
                                            <Link size={12} /> Привязать
                                        </button>
                                    </>
                                    ) : (
                                    <span className="text-[10px] font-bold uppercase bg-gray-800 px-2 py-0.5 rounded border border-gray-700 text-emerald-400">
                                        {isAbilityTrigger ? 'Активируется способностью' : (triggerOptions.find(o => o.key === item.trigger)?.label || item.trigger)}
                                    </span>
                                    )}
                                    <BonusInput isEditMode={isEditMode} bonuses={item.bonuses} onChange={b => updateItem(gIdx, originalIndex, 'bonuses', b)} />
                                </div>
                                {isAbilityTrigger && (
                                    <div className={`text-[10px] flex items-center gap-2 font-bold px-2 py-1 rounded bg-black/40 border border-emerald-900/30 ${!item.trigger_ability_id ? 'text-red-400' : 'text-emerald-400'}`}>
                                        <Zap size={12} />
                                        {item.trigger_ability_id ? `Связь: ${item.trigger_ability_id}` : "Связь не выбрана"}
                                    </div>
                                )}
                            </div>
                            )}

                            {(shouldShowMech || isEditMode) && (
                            <div className="flex flex-wrap gap-2 mb-2">
                                <TimeInput icon={Clock} label="КД" isEditMode={isEditMode} val={item.cd} unit={item.cd_unit} onChangeVal={v => updateItem(gIdx, originalIndex, 'cd', v)} onChangeUnit={u => updateItem(gIdx, originalIndex, 'cd_unit', u)} options={timeUnits} />
                                <TimeInput icon={Hourglass} label="Длит." isEditMode={isEditMode} val={item.dur} unit={item.dur_unit} onChangeVal={v => updateItem(gIdx, originalIndex, 'dur', v)} onChangeUnit={u => updateItem(gIdx, originalIndex, 'dur_unit', u)} options={timeUnits} />
                            </div>
                            )}

                            <div className="mb-2">
                                <TagInput isEditMode={isEditMode} tags={item.tags || []} onChange={t => updateItem(gIdx, originalIndex, 'tags', t)} />
                                {isEditMode && <CommonTagToggles tags={item.tags || []} onChange={t => updateItem(gIdx, originalIndex, 'tags', t)} />}
                            </div>

                            {(shouldShowLore || isEditMode) && <StyledTextarea isEditMode={isEditMode} value={item.desc_lore} onChange={e => updateItem(gIdx, originalIndex, 'desc_lore', e.target.value)} className="text-sm text-gray-400 italic mb-2" placeholder={t('ph_lore_generic', "Худ. описание")} />}
                            {(shouldShowMech || isEditMode) && (isEditMode || item.desc_mech) && <StyledTextarea isEditMode={isEditMode} value={item.desc_mech} onChange={e => updateItem(gIdx, originalIndex, 'desc_mech', e.target.value)} className={`text-xs font-mono ${isEditMode ? 'text-green-400' : 'text-green-500/80'}`} placeholder={t('ph_mech_generic', "Механика (Эффект)")} />}
                        </div>
                     </Card>
                   )})}
                   {isEditMode && <Button onClick={() => addItem(gIdx)} variant="secondary" className="border-dashed"><Plus size={14} /> {t('btn_add_passive', "Добавить черту")}</Button>}
                 </div>
             )}
           </div>
         );
      })}
       {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">{t('btn_add_passive_group', "Создать группу пассивок")}</Button>}
    </div>
  );
};

export default TabPassives;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, Check, X, ChevronRight, ChevronDown, Eye, EyeOff, Zap, AlertCircle, Link, FolderInput } from 'lucide-react';
import { DisplayMode } from '../App';
import { AbilityLinkModal } from './AbilityLinkModal';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (p: CharacterData['passives']) => void;
  triggersMap: Record<string, string>;
  timeUnits: TimeUnit[];
  onCharacterUpdate?: (u: Partial<CharacterData>) => void;
}

const TabDebuffs: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, triggersMap, timeUnits, onCharacterUpdate }) => {
  const { passives } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);

  const [linkingState, setLinkingState] = useState<{gIdx: number, iIdx: number} | null>(null);

  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (gIdx: number, field: string, val: any) => {
    const next = [...passives];
    next[gIdx] = { ...next[gIdx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...passives, { group_name: "Группа Дебаффов", tags: [], items: [], is_flaw_group: true }]);
  const removeGroup = (idx: number) => { 
     const next = passives.filter((_, i) => i !== idx);
     onChange(next);
     setDeleteConfirmGroupIdx(null);
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
  };

  const addItem = (gIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.push({ 
      name: "Новый Дебафф", 
      bonuses: [], 
      trigger: "Always", 
      tags: [], 
      desc_lore: "", 
      desc_mech: "", 
      is_flaw: true,
      cd: 0, cd_unit: "", dur: 0, dur_unit: ""
    });
    next[gIdx] = group;
    onChange(next);
  };

  const updateItem = (gIdx: number, iIdx: number, field: string, val: any) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items[iIdx] = { ...group.items[iIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeItem = (gIdx: number, iIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.splice(iIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const moveItem = (fromGIdx: number, targetValue: string, iIdx: number) => {
      // Internal Move
      if (targetValue.startsWith('group_')) {
          const toGIdx = parseInt(targetValue.split('_')[1]);
          const next = [...passives];
          const sourceGroup = { ...next[fromGIdx] };
          const targetGroup = { ...next[toGIdx] };
          const item = sourceGroup.items[iIdx];

          // Update flag based on target group type (allows moving to Passives and vice-versa)
          item.is_flaw = !!targetGroup.is_flaw_group;

          sourceGroup.items = sourceGroup.items.filter((_, i) => i !== iIdx);
          targetGroup.items = [...targetGroup.items, item];

          next[fromGIdx] = sourceGroup;
          next[toGIdx] = targetGroup;
          onChange(next);
      }
      // Cross-move to Active Ability
      else if (targetValue.startsWith('active_') && onCharacterUpdate) {
          const toAIdx = parseInt(targetValue.split('_')[1]);
          const item = passives[fromGIdx].items[iIdx];

          const newAbility = {
              name: item.name,
              bonuses: item.bonuses,
              tags: item.tags,
              desc_lore: item.desc_lore,
              desc_mech: item.desc_mech,
              cd: item.cd,
              cd_unit: item.cd_unit,
              dur: item.dur,
              dur_unit: item.dur_unit,
              is_blocked: item.is_blocked,
              limit: 0,
              limit_unit: ''
          };

          // 1. Remove from passives (debuffs)
          const nextPassives = [...passives];
          nextPassives[fromGIdx] = {
              ...nextPassives[fromGIdx],
              items: nextPassives[fromGIdx].items.filter((_, i) => i !== iIdx)
          };

          // 2. Add to active
          const nextAbilities = [...character.ability_groups];
          if (nextAbilities[toAIdx]) {
              const targetGroup = { ...nextAbilities[toAIdx] };
              targetGroup.abilities = [...targetGroup.abilities, newAbility];
              nextAbilities[toAIdx] = targetGroup;
          }

          onCharacterUpdate({
              ability_groups: nextAbilities,
              passives: nextPassives
          });
      }
  };

  const handleAbilitySelect = (abilityName: string) => {
      if (!linkingState) return;
      const { gIdx, iIdx } = linkingState;

      const next = [...passives];
      const group = { ...next[gIdx] };
      group.items = [...group.items];

      group.items[iIdx] = { 
          ...group.items[iIdx], 
          trigger: 'ability',
          trigger_ability_id: abilityName
      };

      next[gIdx] = group;
      onChange(next);
      setLinkingState(null);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
      const flaws = passives.filter(g => g.is_flaw_group);
      const data = flaws.map((g, i) => {
        const name = g.group_name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.items ? g.items.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [passives]);

  const bonusData = useMemo(() => {
      let phys = 0, magic = 0, unique = 0;
      passives.filter(g => g.is_flaw_group).forEach(g => {
        if (Array.isArray(g.items)) {
          g.items.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.abs(v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [passives, t]);

  const triggerOptions = useMemo(() => {
    const baseline = [
        { key: 'Always', label: 'Пассивно / Всегда' },
        { key: 'ability', label: 'От способности' },
        { key: 'on_hit', label: 'При попадании' },
        { key: 'on_defense', label: 'При защите' }
    ];
    const integratedEntries = Object.entries(triggersMap);
    const result = baseline.map(base => {
        const fromDb = integratedEntries.find(([k]) => k.toLowerCase() === base.key.toLowerCase());
        return fromDb ? { key: fromDb[0], label: fromDb[1] } : base;
    });
    const baselineKeysLower = baseline.map(b => b.key.toLowerCase());
    integratedEntries.forEach(([key, label]) => {
        if (!baselineKeysLower.includes(key.toLowerCase())) {
            result.push({ key, label });
        }
    });
    return result;
  }, [triggersMap]);

  return (
    <div className="space-y-8 animate-fade-in relative">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} isDebuff={true} t={t} />}

      <AbilityLinkModal 
        isOpen={!!linkingState}
        onClose={() => setLinkingState(null)}
        abilityGroups={character.ability_groups}
        onSelect={handleAbilitySelect}
      />

      {passives.map((group, gIdx) => {
         if (!group.is_flaw_group) return null;
         const isHidden = (group as any).is_hidden;
         const visibleItems = group.items;
         if (!isEditMode && (visibleItems.length === 0 || isHidden)) return null;
         const isCollapsed = collapsedGroups[gIdx];

         return (
           <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className="border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
                <div className="flex items-center justify-between mb-2 gap-4">
                   <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-red-400 transition-colors p-1">
                      {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
                   </button>
                   <div className="flex-1">
                       <StyledInput isEditMode={isEditMode} value={group.group_name} onChange={e => updateGroup(gIdx, 'group_name', e.target.value)} className="text-xl font-bold text-red-500 uppercase tracking-widest bg-transparent border-none p-0" />
                       {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
                   </div>
                   {isEditMode && (
                     <div className="flex items-center gap-2">
                       <button onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-red-600 hover:text-red-400'}`} title={isHidden ? "Показать в листе" : "Скрыть из листа"}>
                            {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                        </button>
                       {deleteConfirmGroupIdx === gIdx ? (
                         <div className="flex items-center gap-1">
                            <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                            <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                         </div>
                       ) : (
                         <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                       )}
                     </div>
                   )}
                </div>
                {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}
             </div>

             {!isCollapsed && (
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {visibleItems.map((item, iIdx) => {
                     const rawTrigger = String(item.trigger || '').toLowerCase().trim();
                     const isAbilityTrigger = rawTrigger === 'ability' || rawTrigger.includes('способнос');

                     return (
                     <Card key={iIdx} className="relative bg-[#0b0d10] border-gray-800 border-l-4 border-l-red-500 bg-red-900/5">
                        <div className="flex justify-between items-start mb-2 overflow-hidden">
                          <div className="flex-1 min-w-0 mr-2" title={item.name}>
                            <StyledInput isEditMode={isEditMode} value={item.name} onChange={e => updateItem(gIdx, iIdx, 'name', e.target.value)} className="font-bold text-lg truncate block w-full text-red-300" />
                          </div>
                          <div className="flex items-center gap-2 flex-shrink-0">
                            {isEditMode && (
                                <>
                                    {passives.length > 1 && (
                                        <div className="relative group">
                                            <button className="p-1 rounded text-slate-600 hover:text-red-400 transition-colors" title="Перенести в другую группу">
                                                <FolderInput size={14} />
                                            </button>
                                            <select 
                                                className="absolute inset-0 opacity-0 cursor-pointer"
                                                value="default"
                                                onChange={(e) => moveItem(gIdx, e.target.value, iIdx)}
                                            >
                                                <option value="default" disabled className="bg-[#0b0d10]">Перенести в...</option>
                                                <optgroup label="Группы Дебаффов/Пассивок" className="bg-[#0b0d10]">
                                                    {passives.map((grp, i) => (
                                                        <option key={"p"+i} value={"group_"+i} disabled={i === gIdx} className="bg-[#0b0d10]">{grp.group_name || 'Group ' + (i+1)}</option>
                                                    ))}
                                                </optgroup>
                                                {character.ability_groups && character.ability_groups.length > 0 && (
                                                    <optgroup label="Активные Способности" className="bg-[#0b0d10]">
                                                        {character.ability_groups.map((grp, i) => (
                                                            <option key={"a"+i} value={"active_"+i} className="bg-[#0b0d10]">{grp.name}</option>
                                                        ))}
                                                    </optgroup>
                                                )}
                                            </select>
                                        </div>
                                    )}
                                    <button onClick={() => removeItem(gIdx, iIdx)} className="text-red-900 hover:text-red-500"><Trash2 size={14}/></button>
                                </>
                            )}
                          </div>
                        </div>

                        {(shouldShowMech || isEditMode) && (
                          <div className="space-y-2 mb-2">
                             <div className="flex flex-wrap items-center gap-2">
                                {isEditMode ? (
                                <>
                                    <select 
                                        value={item.trigger} 
                                        onChange={e => updateItem(gIdx, iIdx, 'trigger', e.target.value)} 
                                        className="bg-gray-800 text-xs border border-gray-700 rounded p-1 max-w-[200px] text-red-400 font-bold outline-none focus:border-red-500"
                                    >
                                        {triggerOptions.map(opt => (
                                            <option key={opt.key} value={opt.key} className="bg-[#0b0d10]">{opt.label}</option>
                                        ))}
                                    </select>
                                    <button 
                                        onClick={() => setLinkingState({ gIdx, iIdx })}
                                        className="bg-red-900/30 hover:bg-red-800 text-red-300 border border-red-700/50 rounded px-2 py-1 text-[10px] flex items-center gap-1 uppercase font-bold tracking-wider transition-colors"
                                        title="Выбрать способность из списка"
                                    >
                                        <Link size={12} /> Привязать
                                    </button>
                                </>
                                ) : (
                                <span className="text-[10px] font-bold uppercase bg-gray-800 px-2 py-0.5 rounded border border-gray-700 text-red-400">
                                    {isAbilityTrigger ? 'Бремя способности' : (triggerOptions.find(o => o.key === item.trigger)?.label || item.trigger)}
                                </span>
                                )}
                                <BonusInput isEditMode={isEditMode} bonuses={item.bonuses} onChange={b => updateItem(gIdx, iIdx, 'bonuses', b)} />
                             </div>
                             {isAbilityTrigger && (
                                <div className={`text-[10px] flex items-center gap-2 font-bold px-2 py-1 rounded bg-black/40 border border-red-900/30 ${!item.trigger_ability_id ? 'text-orange-400' : 'text-red-400'}`}>
                                    <Zap size={12} />
                                    {item.trigger_ability_id ? `Связь: ${item.trigger_ability_id}` : "Связь не выбрана"}
                                </div>
                             )}
                          </div>
                        )}

                        {(shouldShowMech || isEditMode) && (
                          <div className="flex flex-wrap gap-2 mb-2">
                             <TimeInput icon={Clock} label="КД" isEditMode={isEditMode} val={item.cd} unit={item.cd_unit} onChangeVal={v => updateItem(gIdx, iIdx, 'cd', v)} onChangeUnit={u => updateItem(gIdx, iIdx, 'cd_unit', u)} options={timeUnits} />
                            <TimeInput icon={Hourglass} label="Длит." isEditMode={isEditMode} val={item.dur} unit={item.dur_unit} onChangeVal={v => updateItem(gIdx, iIdx, 'dur', v)} onChangeUnit={u => updateItem(gIdx, iIdx, 'dur_unit', u)} options={timeUnits} />
                          </div>
                        )}

                        <div className="mb-2">
                           <TagInput isEditMode={isEditMode} tags={item.tags || []} onChange={t => updateItem(gIdx, iIdx, 'tags', t)} />
                           {isEditMode && <CommonTagToggles tags={item.tags || []} onChange={t => updateItem(gIdx, iIdx, 'tags', t)} />}
                        </div>

                        {(shouldShowLore || isEditMode) && <StyledTextarea isEditMode={isEditMode} value={item.desc_lore} onChange={e => updateItem(gIdx, iIdx, 'desc_lore', e.target.value)} className="text-sm text-gray-400 italic mb-2" placeholder="Худ. описание" />}
                        {(shouldShowMech || isEditMode) && (isEditMode || item.desc_mech) && <StyledTextarea isEditMode={isEditMode} value={item.desc_mech} onChange={e => updateItem(gIdx, iIdx, 'desc_mech', e.target.value)} className={`text-xs font-mono ${isEditMode ? 'text-green-400' : 'text-green-500/80'}`} placeholder="Механика (Эффект)" />}
                     </Card>
                   )})}
                   {isEditMode && <Button onClick={() => addItem(gIdx)} variant="secondary" className="border-dashed"><Plus size={14} /> {t('mech_debuffs', "Добавить Дебафф")}</Button>}
                 </div>
             )}
           </div>
         );
      })}
       {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">{t('mech_debuffs', "Создать группу дебаффов")}</Button>}
    </div>
  );
};

