  const [editingInjuries, setEditingInjuries] = useState<InjuryDefinition[]>([...injuryDefinitions]);
  const [newInjury, setNewInjury] = useState<Partial<InjuryDefinition>>({
    tag: "", label: "", value: -5, type: 1, desc: "", stack: undefined
