                            {!isExpanded && (
                                <div className="flex justify-between items-center mt-2 pt-2 border-t border-white/5">
                                    <div className="flex -space-x-2">
                                        {q.details.acceptedBy.map((n, i) => (
                                            <div key={i} className={`w-5 h-5 rounded-full border border-slate-900 flex items-center justify-center text-[8px] font-bold text-slate-300 ring-1 ring-slate-800 bg-slate-800`} title={n}>
                                                {n.charAt(0)}
                                            </div>
                                        ))}
                                    </div>
                                    <span className="text-[10px] text-slate-600 uppercase tracking-widest group-hover:text-slate-500 transition-colors">Исполнено</span>
                                </div>
                            )}
                        </div>
                    )})
                )}
            </div>
       </Modal>

       <Modal isOpen={isPostModalOpen} onClose={() => setIsPostModalOpen(false)} title={editingQuestId ? "Перековать Квест" : "Сотворить Квест"}>
            <form onSubmit={handlePostSubmit} className="space-y-4">
                <MagicalInput required placeholder="Название Квеста" 
                    value={formQuest.title || ''} onChange={e => setFormQuest({...formQuest, title: e.target.value})} />

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                         <label className="text-xs text-slate-400">Сфера (Тип)</label>
                         <MagicalSelect
                            value={formQuest.type} onChange={e => setFormQuest({...formQuest, type: e.target.value as QuestType})}>
                            <option value={QuestType.PERSONAL} className="bg-[#020408]">Личный</option>
                            <option value={QuestType.FACTION} className="bg-[#020408]">Фракционный</option>
                            <option value={QuestType.PUBLIC} className="bg-[#020408]">Публичный</option>
                        </MagicalSelect>
                    </div>
                    {formQuest.type === QuestType.FACTION && (
                        <div className="space-y-1 animate-fadeIn">
                            <label className="text-xs text-slate-400">Аура (Мировоззрение)</label>
                            <MagicalSelect
                                value={formQuest.alignment} onChange={e => setFormQuest({...formQuest, alignment: e.target.value as QuestAlignment})}>
                                <option value="Neutral" className="bg-[#020408]">Нейтральный (Фиолетовый)</option>
                                <option value="Dark" className="bg-[#020408]">Тьма (Индиго)</option>
                                <option value="Light" className="bg-[#020408]">Свет (Золотой)</option>
                                <option value="NPC" className="bg-[#020408]">Кровь (Красный)</option>
                                <option value="Player" className="bg-[#020408]">Дух (Голубой)</option>
                            </MagicalSelect>
                        </div>
                    )}
                </div>

                <MagicalInput required placeholder="Награда" 
                    value={formQuest.reward || ''} onChange={e => setFormQuest({...formQuest, reward: e.target.value})} />

                <div className="space-y-1 bg-slate-900/30 p-2 rounded border border-slate-800/50">
                     <label className="text-xs text-slate-400 block mb-1">
                         {formQuest.type === QuestType.PERSONAL ? "Привязано к Душе" : "Происхождение / Покровитель"}
                     </label>

                     {formQuest.type !== QuestType.PERSONAL && (
                         <div className="mb-4">
                             <RuneCheckbox 
                                label="Известный Искатель?" 
                                checked={isPlayerGiver} 
                                onChange={v => setIsPlayerGiver(v)} 
                             />
                         </div>
                     )}

                     {(formQuest.type === QuestType.PERSONAL || isPlayerGiver) ? (
                         <MagicalSelect 
                            required 
                            value={formQuest.details?.givenBy || ''}
                            onChange={e => setFormQuest({...formQuest, details: {...formQuest.details!, givenBy: e.target.value}})}
                         >
                             <option value="" disabled className="bg-[#020408]">Выберите Душу...</option>
                             {Object.entries(groupedCharacters).map(([faction, chars]) => (
                                 <optgroup key={faction} label={faction} className="bg-[#020408]">
                                     {(chars as Character[]).map(c => <option key={c.id} value={c.name} className="bg-[#020408]">{c.name}</option>)}
                                 </optgroup>
                             ))}
                         </MagicalSelect>
                     ) : (
                         <MagicalInput required 
                            placeholder="Имя Сущности" 
                            value={formQuest.details?.givenBy || ''} onChange={e => setFormQuest({...formQuest, details: {...formQuest.details!, givenBy: e.target.value}})} />
                     )}
                </div>

                <MagicalTextArea required placeholder="Детали пакта..." rows={3} 
                    value={formQuest.description || ''} onChange={e => setFormQuest({...formQuest, description: e.target.value})} />

                <button type="submit" className="w-full mt-4 group relative px-6 py-3 bg-slate-900 border-2 border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.2)] text-violet-100 font-fantasy tracking-[0.2em] uppercase hover:bg-violet-900/40 hover:border-violet-400 hover:shadow-[0_0_25px_rgba(139,92,246,0.6)] transition-all duration-300 overflow-hidden">
                    <span className="relative z-10">{editingQuestId ? "Изменить Реальность" : "Воплотить"}</span>
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-violet-400/10 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
                </button>
            </form>
       </Modal>

       <Modal isOpen={acceptModalOpen} onClose={() => setAcceptModalOpen(false)} title="Связать Судьбы">
           <form onSubmit={handleAcceptSubmit} className="space-y-4">
               <div className="bg-slate-800/50 p-3 rounded text-sm text-slate-300 italic mb-4 border border-slate-700">"Плетение связывает тех, кто принимает зов..."</div>

               <div className="flex justify-between items-center mb-2">
                   <label className="text-xs text-slate-400 uppercase tracking-widest font-bold">Участники</label>
                   <button 
                      type="button" 
                      onClick={() => setIsCharSelectorOpen(true)}
                      className="text-xs flex items-center gap-1 bg-violet-900/20 text-violet-300 px-2 py-1 rounded hover:bg-violet-900/40 transition-colors border border-violet-500/30"
                   >
                       <BookOpen size={12} /> Список
                   </button>
               </div>

               <div className="space-y-2 max-h-60 overflow-y-auto">
                   {acceptNames.map((name, index) => (
                       <div key={index} className="relative group">
                           <MagicalInput 
                               autoFocus={index === acceptNames.length - 1} 
                               placeholder={`Душа ${index + 1}`} 
                               className="pr-8"
                               value={name} 
                               onChange={(e) => { const newNames = [...acceptNames]; newNames[index] = e.target.value; setAcceptNames(newNames); }} 
                           />

                           {acceptNames.length > 1 && (
                               <button 
                                  type="button" 
                                  onClick={() => setAcceptNames(acceptNames.filter((_, i) => i !== index))} 
                                  className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-500 hover:text-red-500 p-1"
                               >
                                   <X size={14} />
                               </button>
                           )}
                       </div>
                   ))}
               </div>

               <button type="button" onClick={() => setAcceptNames([...acceptNames, ''])} className="text-xs flex items-center gap-1 text-slate-400 hover:text-white transition-colors">
                   <Plus size={14} /> Добавить участника
               </button>

               <button type="submit" className="w-full mt-4 group relative px-6 py-3 bg-slate-900 border-2 border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.2)] text-violet-100 font-fantasy tracking-[0.2em] uppercase hover:bg-violet-900/40 hover:border-violet-400 hover:shadow-[0_0_25px_rgba(139,92,246,0.6)] transition-all duration-300 overflow-hidden">
                  <span className="relative z-10">Скрепить Пакт</span>
               </button>
           </form>
       </Modal>
    </div>
  );
};

export default QuestBoardPage;

import React, { useState, useEffect } from 'react';
import { BattleParticipant, SequenceStep, TargetConfig, ReactionType, SequenceNode, JsonAbility } from '../types';
import { calculateSequenceTree } from '../engine/calculator';
import { MOCK_ABILITIES } from '../constants';

interface Props {
  participants: BattleParticipant[];
  draft: SequenceStep;
  setDraft: React.Dispatch<React.SetStateAction<SequenceStep>>;
  onCommit: (formattedString: string, cost: number) => void;
}

const SequenceBuilder: React.FC<Props> = ({ participants, draft, setDraft, onCommit }) => {
  const actor = participants.find(p => p.instance_id === draft.actor_id);
  const [calculatedPreview, setCalculatedPreview] = useState<string>('');

  // Available abilities: Actor's own + Global Equipment (simplified here to just MOCK)
  const availableAbilities: JsonAbility[] = actor ? [...actor.flat_abilities, ...MOCK_ABILITIES] : MOCK_ABILITIES;
  const uniqueAbilities: JsonAbility[] = Array.from(new Map(availableAbilities.map(item => [item._id, item])).values());

  useEffect(() => {
    if (draft.actor_id && draft.ability_ids.length > 0) {
      // Create a temporary tree to calculate
      const nodes: SequenceNode[] = [{
          id: 'temp-combo',
          type: 'combo',
          children: draft.ability_ids.map(aid => ({
              id: `temp-${aid}`,
              type: 'action',
              data: { charId: draft.actor_id, abilityId: aid },
              children: []
          }))
      }];

      const result = calculateSequenceTree(nodes, participants);
      setCalculatedPreview(result.formattedString);

    } else {
      setCalculatedPreview('Ожидание действий...');
    }
  }, [draft, participants]);

  const toggleAbility = (id: string) => {
    setDraft(prev => {
      const exists = prev.ability_ids.includes(id);
      return {
        ...prev,
        ability_ids: exists 
          ? prev.ability_ids.filter(aid => aid !== id)
          : [...prev.ability_ids, id]
      };
    });
  };

  const updateTargetReaction = (participantId: string, reaction: ReactionType) => {
     setDraft(prev => {
        const targetIndex = prev.target_configs.findIndex(t => t.participant_id === participantId);
        if (targetIndex === -1) {
            // Add new
            return {
                ...prev,
                target_configs: [...prev.target_configs, { participant_id: participantId, reaction }]
            };
        }
        // Update existing
        const newTargets = [...prev.target_configs];
        newTargets[targetIndex] = { ...newTargets[targetIndex], reaction };
        return { ...prev, target_configs: newTargets };
     });
  };

  const removeTarget = (participantId: string) => {
      setDraft(prev => ({
          ...prev,
          target_configs: prev.target_configs.filter(t => t.participant_id !== participantId)
      }));
  };

  if (!actor) {
    return (
      <div className="h-full flex items-center justify-center text-slate-500 border-2 border-dashed border-console-700 rounded-lg font-rune">
        Выберите Субъекта из списка слева.
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-console-800 rounded-lg p-4 shadow-xl border border-console-700">

      {/* Header: Actor Info */}
      <div className="flex items-center gap-4 border-b border-console-700 pb-4 mb-4">
        <div className="w-12 h-12 rounded bg-yellow-600/20 text-yellow-500 flex items-center justify-center border border-yellow-600/50 font-bold">
            {actor.profile.name.substring(0, 2)}
        </div>
        <div>
            <h2 className="text-lg font-bold text-white font-rune uppercase tracking-wide">Конструктор</h2>
            <p className="text-sm text-slate-400">Субъект: <span className="text-yellow-400">{actor.profile.name}</span></p>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 space-y-6">

        {/* Section 1: Abilities (Combo) */}
        <div>
            <h3 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">Навыки (Комбо)</h3>
            <div className="grid grid-cols-2 gap-2">
                {uniqueAbilities.map(ability => {
                    const isSelected = draft.ability_ids.includes(ability._id);
                    const order = draft.ability_ids.indexOf(ability._id) + 1;

                    const totalBonus = ability.bonuses.reduce((acc, b) => acc + b.val, 0);

                    return (
                        <button
                            key={ability._id}
                            onClick={() => toggleAbility(ability._id)}
                            className={`
                                relative flex items-center justify-between px-3 py-2 rounded border text-sm text-left transition-all
                                ${isSelected 
                                    ? 'bg-blue-900/30 border-blue-500 text-blue-100 shadow-[0_0_10px_rgba(59,130,246,0.2)]' 
                                    : 'bg-console-900 border-console-700 text-slate-400 hover:border-slate-500'}
                            `}
                        >
                            <div className="flex flex-col">
                                <span className="font-semibold">{ability.name}</span>
                                <span className="text-[10px] opacity-70">Бонус: {totalBonus}</span>
                            </div>
                            {isSelected && (
                                <span className="flex items-center justify-center w-5 h-5 rounded-full bg-blue-500 text-white text-xs font-bold">
                                    {order}
                                </span>
                            )}
                        </button>
                    );
                })}
            </div>
        </div>

        {/* Section 2: Targets & Reactions */}
        <div>
             <h3 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">Цели и Реакции</h3>
             {draft.target_configs.length === 0 ? (
                 <div className="p-3 bg-console-900/50 border border-dashed border-console-700 rounded text-center text-sm text-slate-500">
                     Выберите цели в списке участников
                 </div>
             ) : (
                 <div className="space-y-2">
                     {draft.target_configs.map(tConfig => {
                         const targetParticipant = participants.find(p => p.instance_id === tConfig.participant_id);
                         if (!targetParticipant) return null;

                         return (
                             <div key={tConfig.participant_id} className="flex items-center gap-3 bg-console-900 border border-console-600 p-2 rounded">
                                 <div className="w-6 h-6 rounded bg-slate-700 flex items-center justify-center text-[10px] text-white">
                                     {targetParticipant.profile.name.substring(0,2)}
                                 </div>
                                 <span className="text-sm font-medium text-slate-200 flex-1">{targetParticipant.profile.name}</span>

                                 <select 
                                    value={tConfig.reaction}
                                    onChange={(e) => updateTargetReaction(tConfig.participant_id, e.target.value as ReactionType)}
                                    className="bg-console-800 border border-console-600 text-xs text-white rounded px-2 py-1 outline-none focus:border-blue-500"
                                 >
                                     <option value="none" className="bg-console-800">Нет реакции</option>
                                     <option value="dodge" className="bg-console-800">Уклонение</option>
                                     <option value="block" className="bg-console-800">Блок</option>
                                 </select>

                                 <button 
                                    onClick={() => removeTarget(tConfig.participant_id)}
                                    className="text-slate-500 hover:text-red-400 px-2"
                                 >
                                     &times;
                                 </button>
                             </div>
                         );
                     })}
                 </div>
             )}
        </div>

        {/* Section 3: Conditionals (Visual Mock) */}
        <div>
