import { supabase } from '../lib/supabase';
import { CharacterData, InjuryDefinition, TimeUnit, Ability, TrainingRecord, BattleTag } from '../types';
import { DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from '../constants';
